passing_property:
// Y matches the implemented NAND/OR/NOT function.
    check_functional_equivalence: assert property (
        @(posedge clk) Y == ~(~B1_N & (A1 | A2))
    );

// A high B1_N forces Y high.
    check_b1n_high_forces_y_high: assert property (
        @(posedge clk) B1_N |-> Y
    );

// A low B1_N with both A inputs low forces Y high.
    check_a_inputs_low_force_y_high: assert property (
        @(posedge clk) (!B1_N && !A1 && !A2) |-> Y
    );

// A low B1_N with A1 low and A2 high forces Y low.
    check_a1_low_a2_high_forces_y_low: assert property (
        @(posedge clk) (!B1_N && !A1 && A2) |-> !Y
    );

// A low B1_N with A1 high and A2 low forces Y low.
    check_a1_high_a2_low_forces_y_low: assert property (
        @(posedge clk) (!B1_N && A1 && !A2) |-> !Y
    );

// A low B1_N with both A inputs high forces Y low.
    check_a_inputs_high_force_y_low: assert property (
        @(posedge clk) (!B1_N && A1 && A2) |-> !Y
    );

// A low Y requires B1_N to be low.
    check_y_low_requires_b1n_low: assert property (
        @(posedge clk) !Y |-> !B1_N
    );

// A low Y requires at least one A input high.
    check_y_low_requires_a_inputs_high: assert property (
        @(posedge clk) !Y |-> (A1 || A2)
    );

// y must match the RTL's combinational equation.
    check_function_equivalence: assert property (
        @(posedge clk) y == ((~sel & a) | (sel & b))
    );

// When sel is low, y must follow a.
    check_sel_low_routes_a: assert property (
        @(posedge clk) !sel |-> (y == a)
    );

// When sel is high, y must follow b.
    check_sel_high_routes_b: assert property (
        @(posedge clk) sel |-> (y == b)
    );

// A high output requires at least one high data input.
    check_y_high_requires_data_high: assert property (
        @(posedge clk) y |-> (a || b)
    );

// sel=00 routes data0 to out.
    check_sel_00_routes_data0: assert property (
        @(posedge clk) (sel == 2'b00) |-> (out == data0)
    );

// sel=01 routes data1 to out.
    check_sel_01_routes_data1: assert property (
        @(posedge clk) (sel == 2'b01) |-> (out == data1)
    );

// sel=10 routes data2 to out.
    check_sel_10_routes_data2: assert property (
        @(posedge clk) (sel == 2'b10) |-> (out == data2)
    );

// sel=11 routes data3 to out.
    check_sel_11_routes_data3: assert property (
        @(posedge clk) (sel == 2'b11) |-> (out == data3)
    );

// If Z_B is 1, Len_int equals n63 and Ren_int equals n62.
    check_outputs_when_zb_one: assert property (
        @(posedge clk) (Z_B == 1'b1) |-> (Len_int == n63 && Ren_int == n62)
    );

// gray[3] mirrors bin[3].
    check_gray3_mirrors_bin3: assert property (
        @(posedge clk) gray[3] == bin[3]
    );

// gray[2] is bin[3] XOR bin[2].
    check_gray2_is_bin3_xor_bin2: assert property (
        @(posedge clk) gray[2] == (bin[3] ^ bin[2])
    );

// gray[1] is bin[2] XOR bin[1].
    check_gray1_is_bin2_xor_bin1: assert property (
        @(posedge clk) gray[1] == (bin[2] ^ bin[1])
    );

// gray[0] is bin[1] XOR bin[0].
    check_gray0_is_bin1_xor_bin0: assert property (
        @(posedge clk) gray[0] == (bin[1] ^ bin[0])
    );

// Reset drives q to zero on the next clock.
    check_reset_clears_q: assert property (
        @(posedge clk) reset |=> (q == 4'b0000)
    );

// When enabled, q increments by one on the next clock.
    check_increment_when_enabled: assert property (
        @(posedge clk) disable iff (reset) enable |=> (q == ($past(q) + 4'd1))
    );

// When not enabled, q holds its value on the next clock.
    check_hold_when_disabled: assert property (
        @(posedge clk) disable iff (reset) !enable |=> (q == $past(q))
    );

// The 4-bit counter wraps from 15 back to 0 when enabled.
    check_wrap_from_max: assert property (
        @(posedge clk) disable iff (reset) (enable && (q == 4'hF)) |=> (q == 4'h0)
    );

// Sum and carry match the 5-bit addition of a, b, and cin.
    check_full_add_result: assert property (
        @(posedge clk) {cout, sum} == ({1'b0, a} + {1'b0, b} + cin)
    );

// LSB sum is the XOR of a[0], b[0], and cin.
    check_sum_bit0: assert property (
        @(posedge clk) sum[0] == (a[0] ^ b[0] ^ cin)
    );

// Bit1 sum uses the carry generated from bit0.
    check_sum_bit1: assert property (
        @(posedge clk) sum[1] == (a[1] ^ b[1] ^ ((a[0] & b[0]) | (a[0] & cin) | (b[0] & cin)))
    );

// Bit2 sum uses the carry generated from bit1.
    check_sum_bit2: assert property (
        @(posedge clk) sum[2] == (a[2] ^ b[2] ^ ((a[1] & b[1]) | (a[1] & ((a[0] & b[0]) | (a[0] & cin) | (b[0] & cin))) | (b[1] & ((a[0] & b[0]) | (a[0] & cin) | (b[0] & cin)))))
    );

// Carry-out is high when the 4-bit addition overflows.
    check_cout_overflow: assert property (
        @(posedge clk) cout == (({1'b0, a} + {1'b0, b} + cin) >= 5'd16)
    );

// Addition mode returns the 8-bit sum.
    check_add_result: assert property (
        @(posedge clk) (op == 2'b00) |-> (result == (num1 + num2))
    );

// Subtraction mode returns the 8-bit difference.
    check_sub_result: assert property (
        @(posedge clk) (op == 2'b01) |-> (result == (num1 - num2))
    );

// sel=00 routes in0 to out.
    check_sel_00_routes_in0: assert property (
        @(posedge clk) (sel == 2'b00) |-> (out == in0)
    );

// sel=01 routes in1 to out.
    check_sel_01_routes_in1: assert property (
        @(posedge clk) (sel == 2'b01) |-> (out == in1)
    );

// sel=10 routes in2 to out.
    check_sel_10_routes_in2: assert property (
        @(posedge clk) (sel == 2'b10) |-> (out == in2)
    );

// sel=11 routes in3 to out.
    check_sel_11_routes_in3: assert property (
        @(posedge clk) (sel == 2'b11) |-> (out == in3)
    );

// s[0] is the XOR of the LSB inputs and carry-in.
    check_sum_bit0: assert property (
        @(posedge clk) s[0] == (a[0] ^ b[0] ^ ci)
    );

// s[2] uses the carry generated from bit 1.
    check_sum_bit2: assert property (
        @(posedge clk) s[2] == (
            a[2] ^ b[2] ^
            (
                (a[1] & b[1]) |
                (
                    (a[1] & ((a[0] & b[0]) | ((a[0] & ci) | (b[0] & ci)))) |
                    (b[1] & ((a[0] & b[0]) | ((a[0] & ci) | (b[0] & ci))))
                )
            )
        )
    );

// All-zero inputs produce all-zero outputs.
    check_zero_case: assert property (
        @(posedge clk) (a == 4'b0000 && b == 4'b0000 && ci == 1'b0) |-> (s == 4'b0000 && co == 1'b0)
    );

// X must match the implemented A&SLEEP_B AND function.
    check_functional_equivalence: assert property (
        @(posedge clk) X == (A & SLEEP_B)
    );

// When SLEEP_B is low, X must be low.
    check_sleep_forces_low: assert property (
        @(posedge clk) !SLEEP_B |-> (X == 1'b0)
    );

// When A is low, X must be low.
    check_a_low_forces_low: assert property (
        @(posedge clk) !A |-> (X == 1'b0)
    );

// When both A and SLEEP_B are high, X must be high.
    check_both_high_drive_high: assert property (
        @(posedge clk) (A && SLEEP_B) |-> (X == 1'b1)
    );

// A high X requires both A and SLEEP_B to be high.
    check_high_output_requires_both_high: assert property (
        @(posedge clk) X |-> (A && SLEEP_B)
    );

// Y matches the implemented NOR-of-ANDs function.
    check_y_function: assert property (
        @(posedge clk) Y == ~((B1 & B2) | C1 | (A1 & A2))
    );

// C1 high forces Y low.
    check_c1_forces_y_low: assert property (
        @(posedge clk) C1 |-> !Y
    );

// A1 and A2 high together force Y low.
    check_a_pair_forces_y_low: assert property (
        @(posedge clk) (A1 && A2) |-> !Y
    );

// B1 and B2 high together force Y low.
    check_b_pair_forces_y_low: assert property (
        @(posedge clk) (B1 && B2) |-> !Y
    );

// With no asserted NOR input, Y must be high.
    check_no_active_input_sets_y_high: assert property (
        @(posedge clk) (!C1 && !(A1 && A2) && !(B1 && B2)) |-> Y
    );

// A high Y requires C1, A1&A2, or B1&B2 to be low.
    check_y_high_requires_some_input_low: assert property (
        @(posedge clk) Y |-> (!C1 && !(A1 && A2) && !(B1 && B2))
    );

// Y must equal the 4-input NOR of A, B, C, and D.
    check_nor_function: assert property (
        @(posedge clk) Y == ~(A | B | C | D)
    );

// When all inputs are low, Y must be high.
    check_all_low_drives_high: assert property (
        @(posedge clk) (!A && !B && !C && !D) |-> Y
    );

// A high must force Y low.
    check_a_high_drives_low: assert property (
        @(posedge clk) A |-> !Y
    );

// B high must force Y low.
    check_b_high_drives_low: assert property (
        @(posedge clk) B |-> !Y
    );

// C high must force Y low.
    check_c_high_drives_low: assert property (
        @(posedge clk) C |-> !Y
    );

// D high must force Y low.
    check_d_high_drives_low: assert property (
        @(posedge clk) D |-> !Y
    );

// A high Y implies all inputs are low.
    check_high_output_requires_all_low: assert property (
        @(posedge clk) Y |-> (!A && !B && !C && !D)
    );

// A low Y implies at least one input is high.
    check_low_output_requires_some_high: assert property (
        @(posedge clk) !Y |-> (A || B || C || D)
    );

// Y matches the implemented NAND/OR/NAND/BUF function.
    check_functional_equivalence: assert property (
        @(posedge clk) Y == ~((A1 | A2) & (B1 | B2) & C1)
    );

// C1 low forces Y high.
    check_c1_low_forces_y_high: assert property (
        @(posedge clk) !C1 |-> Y
    );

// With C1 high, both A and B OR terms low force Y high.
    check_ab_terms_low_force_y_high: assert property (
        @(posedge clk) C1 && !(A1 || A2) && !(B1 || B2) |-> Y
    );

// With C1 high, A1 high with B terms low forces Y high.
    check_a1_with_b_terms_low_force_y_high: assert property (
        @(posedge clk) C1 && A1 && !(B1 || B2) |-> Y
    );

// With C1 high, A2 high with B terms low forces Y high.
    check_a2_with_b_terms_low_force_y_high: assert property (
        @(posedge clk) C1 && A2 && !(B1 || B2) |-> Y
    );

// With C1 high, B1 high with A terms low forces Y high.
    check_b1_with_a_terms_low_force_y_high: assert property (
        @(posedge clk) C1 && B1 && !(A1 || A2) |-> Y
    );

// With C1 high, B2 high with A terms low forces Y high.
    check_b2_with_a_terms_low_force_y_high: assert property (
        @(posedge clk) C1 && B2 && !(A1 || A2) |-> Y
    );

// With C1 high, any asserted A and B OR term forces Y low.
    check_any_ab_term_with_c1_high_forces_y_low: assert property (
        @(posedge clk) C1 && ((A1 || A2) && (B1 || B2)) |-> !Y
    );

// With C1 high, Y low implies at least one asserted A and B OR term.
    check_y_low_implies_ab_terms_high_with_c1_high: assert property (
        @(posedge clk) C1 && !Y |-> ((A1 || A2) && (B1 || B2))
    );

// With C1 high, Y high implies all A and B OR terms are low.
    check_y_high_implies_ab_terms_low_with_c1_high: assert property (
        @(posedge clk) C1 && Y |-> !(A1 || A2) || !(B1 || B2)
    );

// b1x is the lower 6 bits of e XOR k.
    check_b1x_slice: assert property (
        @(posedge clk) b1x == (e[5:0] ^ k[5:0])
    );

// b2x is the next 6 bits of e XOR k.
    check_b2x_slice: assert property (
        @(posedge clk) b2x == (e[11:6] ^ k[11:6])
    );

// b3x is the next 6 bits of e XOR k.
    check_b3x_slice: assert property (
        @(posedge clk) b3x == (e[17:12] ^ k[17:12])
    );

// b4x is the next 6 bits of e XOR k.
    check_b4x_slice: assert property (
        @(posedge clk) b4x == (e[23:18] ^ k[23:18])
    );

// b5x is the next 6 bits of e XOR k.
    check_b5x_slice: assert property (
        @(posedge clk) b5x == (e[29:24] ^ k[29:24])
    );

// b6x is the next 6 bits of e XOR k.
    check_b6x_slice: assert property (
        @(posedge clk) b6x == (e[35:30] ^ k[35:30])
    );

// b7x is the next 6 bits of e XOR k.
    check_b7x_slice: assert property (
        @(posedge clk) b7x == (e[41:36] ^ k[41:36])
    );

// b8x is the upper 6 bits of e XOR k.
    check_b8x_slice: assert property (
        @(posedge clk) b8x == (e[47:42] ^ k[47:42])
    );

// Output must match the OR of the four inputs.
    check_output_matches_or: assert property (
        @(posedge clk) output1 == (input1 | input2 | input3 | input4)
    );

// A high input1 must drive the output high.
    check_input1_sets_output: assert property (
        @(posedge clk) input1 |-> output1
    );

// A high input2 must drive the output high.
    check_input2_sets_output: assert property (
        @(posedge clk) input2 |-> output1
    );

// A high input3 must drive the output high.
    check_input3_sets_output: assert property (
        @(posedge clk) input3 |-> output1
    );

// A high input4 must drive the output high.
    check_input4_sets_output: assert property (
        @(posedge clk) input4 |-> output1
    );

// A low output implies all four inputs are low.
    check_output_low_implies_all_inputs_low: assert property (
        @(posedge clk) !output1 |-> (!input1 && !input2 && !input3 && !input4)
    );

// A high output implies at least one input is high.
    check_output_high_implies_some_input_high: assert property (
        @(posedge clk) output1 |-> (input1 || input2 || input3 || input4)
    );

// Output is 00 when input is 0 through 5.
    check_low_range_maps_to_zero: assert property (
        @(posedge clk) (input_value <= 4'd5) |-> (output_value == 2'b00)
    );

// Output is 01 when input is 6 through 9.
    check_mid_range_maps_to_one: assert property (
        @(posedge clk) (input_value >= 4'd6 && input_value <= 4'd9) |-> (output_value == 2'b01)
    );

// Output is 10 when input is 10 or higher.
    check_high_range_maps_to_two: assert property (
        @(posedge clk) (input_value >= 4'd10) |-> (output_value == 2'b10)
    );

// Output value is always one of the three implemented encodings.
    check_output_encoding_legal: assert property (
        @(posedge clk) output_value inside {2'b00, 2'b01, 2'b10}
    );

// 00 output implies input is 0 through 5.
    check_zero_output_implies_low_range: assert property (
        @(posedge clk) (output_value == 2'b00) |-> (input_value <= 4'd5)
    );

// 01 output implies input is 6 through 9.
    check_one_output_implies_mid_range: assert property (
        @(posedge clk) (output_value == 2'b01) |-> (input_value >= 4'd6 && input_value <= 4'd9)
    );

// 10 output implies input is 10 or higher.
    check_two_output_implies_high_range: assert property (
        @(posedge clk) (output_value == 2'b10) |-> (input_value >= 4'd10)
    );

// Reset clears both count and out on the next clock.
    check_reset_clears_outputs: assert property (
        @(posedge clk) reset |=> (count == 4'h0) && (out == 1'b0)
    );

// Count increments by one when reset is low.
    check_count_increments: assert property (
        @(posedge clk) disable iff (reset) 1'b1 |=> (count == ($past(count) + 4'd1))
    );

// Count wraps from 4'hF back to 4'h0 when reset is low.
    check_count_wraps: assert property (
        @(posedge clk) disable iff (reset) (count == 4'hF) |=> (count == 4'h0)
    );

// Out toggles its value when reset is low.
    check_out_toggles: assert property (
        @(posedge clk) disable iff (reset) 1'b1 |=> (out == ~$past(out))
    );

// Reset drives count to zero on the next clock.
    check_reset_clears_count: assert property (
        @(posedge clk) reset |=> (count == 4'd0)
    );

// When not in reset, count increments by one each cycle.
    check_count_increments: assert property (
        @(posedge clk) disable iff (reset) 1'b1 |=> (count == ($past(count) + 4'd1))
    );

// Count wraps from 15 back to 0.
    check_count_wraps: assert property (
        @(posedge clk) disable iff (reset) (count == 4'hF) |=> (count == 4'h0)
    );

// parallel_load captures data_in into the register on the next cycle.
    check_parallel_load_captures_data: assert property (
        @(posedge clk) parallel_load |=> (parallel_out == $past(data_in))
    );

// parallel_load has priority over shift_dir when both are high.
    check_parallel_load_priority_over_shift: assert property (
        @(posedge clk) (parallel_load && shift_dir) |=> (parallel_out == $past(data_in))
    );

// shift_dir=1 rotates the register left by one bit and inserts 0 into bit 0.
    check_left_shift_rotates: assert property (
        @(posedge clk) (!parallel_load && shift_dir) |=> (parallel_out == {$past(parallel_out[6:0]), 1'b0})
    );

// shift_dir=0 rotates the register right by one bit and inserts 0 into bit 7.
    check_right_shift_rotates: assert property (
        @(posedge clk) (!parallel_load && !shift_dir) |=> (parallel_out == {1'b0, $past(parallel_out[7:1])})
    );

// A left shift moves bits [6:0] into [7:1] and inserts 0 into bit 0.
    check_left_shift_data_mapping: assert property (
        @(posedge clk) (!parallel_load && shift_dir) |=> (parallel_out[7:1] == $past(parallel_out[6:0]))
    );

// A right shift moves bits [7:1] into [6:0] and inserts 0 into bit 7.
    check_right_shift_data_mapping: assert property (
        @(posedge clk) (!parallel_load && !shift_dir) |=> (parallel_out[6:0] == $past(parallel_out[7:1]))
    );

// On a clock edge with reset asserted, the output is cleared to zero.
    check_reset_clears_output: assert property (
        @(posedge w_clock) w_reset |-> (r_bus_addr_out == 8'h00)
    );

// On a clock edge with reset deasserted, the output captures the prior input value.
    check_capture_on_no_reset: assert property (
        @(posedge w_clock) disable iff (w_reset) 1'b1 |=> (r_bus_addr_out == $past(w_bus_addr_in))
    );

// If reset is held high across consecutive clock edges, the output remains zero.
    check_zero_held_when_reset_held: assert property (
        @(posedge w_clock) (w_reset && $past(w_reset)) |-> (r_bus_addr_out == 8'h00)
    );

// When disabled, the output must be zero.
    check_disabled_forces_zero: assert property (
        @(posedge clk) !en |-> (out == 4'b0000)
    );

// When enabled and sel==00, out equals in0.
    check_sel00_when_enabled: assert property (
        @(posedge clk) en && (sel == 2'b00) |-> (out == in0)
    );

// When enabled and sel==01, out equals in1.
    check_sel01_when_enabled: assert property (
        @(posedge clk) en && (sel == 2'b01) |-> (out == in1)
    );

// When enabled and sel==10, out equals in2.
    check_sel10_when_enabled: assert property (
        @(posedge clk) en && (sel == 2'b10) |-> (out == in2)
    );

// When enabled and sel==11, out equals in3.
    check_sel11_when_enabled: assert property (
        @(posedge clk) en && (sel == 2'b11) |-> (out == in3)
    );

// When enabled, out must equal one of the four inputs.
    check_enabled_output_matches_inputs: assert property (
        @(posedge clk) en |-> (out == in0 || out == in1 || out == in2 || out == in3)
    );

// When enabled, out must equal one of the four inputs selected by sel.
    check_enabled_output_matches_selected_input: assert property (
        @(posedge clk) en |-> (out == (sel == 2'b00 ? in0 :
                                       sel == 2'b01 ? in1 :
                                       sel == 2'b10 ? in2 :
                                       sel == 2'b11 ? in3 :
                                       4'b0000))
    );

// X matches the implemented OR-AND function.
    check_functional_equivalence: assert property (
        @(posedge clk) X == ((A1 | A2) & B1 & C1)
    );

// B1 low forces X low.
    check_b1_low_forces_x_low: assert property (
        @(posedge clk) !B1 |-> !X
    );

// C1 low forces X low.
    check_c1_low_forces_x_low: assert property (
        @(posedge clk) !C1 |-> !X
    );

// A1 high with B1 and C1 high drives X high.
    check_a1_high_drives_x_high: assert property (
        @(posedge clk) (A1 && B1 && C1) |-> X
    );

// A2 high with B1 and C1 high drives X high.
    check_a2_high_drives_x_high: assert property (
        @(posedge clk) (A2 && B1 && C1) |-> X
    );

// X high requires B1, C1, and at least one of A1/A2 to be high.
    check_x_high_requires_all_inputs: assert property (
        @(posedge clk) X |-> (B1 && C1 && (A1 || A2))
    );

// Load clears the counter on the next cycle.
    check_load_clears_counter: assert property (
        @(posedge clk) load |=> (out == 3'b000)
    );

// Up mode increments the counter when load is low.
    check_up_mode_increments: assert property (
        @(posedge clk) (!load && up_down) |=> (out == ($past(out) + 3'd1))
    );

// Down mode decrements the counter when load is low.
    check_down_mode_decrements: assert property (
        @(posedge clk) (!load && !up_down) |=> (out == ($past(out) - 3'd1))
    );

// Load has priority over up/down when both are asserted.
    check_load_priority_over_up_down: assert property (
        @(posedge clk) (load && up_down) |=> (out == 3'b000)
    );

// Increment wraps from 7 to 0 in up mode.
    check_wrap_up_from_max: assert property (
        @(posedge clk) (!load && up_down && (out == 3'b111)) |=> (out == 3'b000)
    );

// Decrement wraps from 0 to 7 in down mode.
    check_wrap_down_from_zero: assert property (
        @(posedge clk) (!load && !up_down && (out == 3'b000)) |=> (out == 3'b111)
    );

// Reset drives the counter to zero.
    check_reset_clears_state: assert property (
        @(posedge clk) !reset |-> (out == 4'b0000)
    );

// When enabled, the counter updates with the next LFSR value.
    check_enabled_update: assert property (
        @(posedge clk) disable iff (!reset)
        ena |=> (out == {$past(out[2:0]), $past(out[3]) ^ $past(out[2])})
    );

// When disabled, the counter holds its value.
    check_disabled_hold: assert property (
        @(posedge clk) disable iff (!reset)
        !ena |=> (out == $past(out))
    );

// Bit 0 shifts in the previous value of bit 2.
    check_bit0_update: assert property (
        @(posedge clk) disable iff (!reset)
        ena |=> (out[0] == $past(out[2]))
    );

// Bit 1 shifts in the previous value of bit 3.
    check_bit1_update: assert property (
        @(posedge clk) disable iff (!reset)
        ena |=> (out[1] == $past(out[3]))
    );

// Bit 2 shifts in the previous value of bit 1.
    check_bit2_update: assert property (
        @(posedge clk) disable iff (!reset)
        ena |=> (out[2] == $past(out[1]))
    );

// Bit 3 is the previous XOR of bits 3 and 2.
    check_bit3_update: assert property (
        @(posedge clk) disable iff (!reset)
        ena |=> (out[3] == $past(out[3]) ^ $past(out[2]))
    );

// sel=0000 drives only bit 0 high.
    check_sel_0000: assert property (
        @(posedge clk) (sel == 4'b0000) |-> (out == 16'h0001)
    );

// sel=0001 drives only bit 1 high.
    check_sel_0001: assert property (
        @(posedge clk) (sel == 4'b0001) |-> (out == 16'h0002)
    );

// sel=0010 drives only bit 2 high.
    check_sel_0010: assert property (
        @(posedge clk) (sel == 4'b0010) |-> (out == 16'h0004)
    );

// sel=0011 drives only bit 3 high.
    check_sel_0011: assert property (
        @(posedge clk) (sel == 4'b0011) |-> (out == 16'h0008)
    );

// sel=0100 drives only bit 4 high.
    check_sel_0100: assert property (
        @(posedge clk) (sel == 4'b0100) |-> (out == 16'h0010)
    );

// sel=0101 drives only bit 5 high.
    check_sel_0101: assert property (
        @(posedge clk) (sel == 4'b0101) |-> (out == 16'h0020)
    );

// sel=0110 drives only bit 6 high.
    check_sel_0110: assert property (
        @(posedge clk) (sel == 4'b0110) |-> (out == 16'h0040)
    );

// sel=0111 drives only bit 7 high.
    check_sel_0111: assert property (
        @(posedge clk) (sel == 4'b0111) |-> (out == 16'h0080)
    );

// sel=1000 drives only bit 8 high.
    check_sel_1000: assert property (
        @(posedge clk) (sel == 4'b1000) |-> (out == 16'h0100)
    );

// sel=1001 drives only bit 9 high.
    check_sel_1001: assert property (
        @(posedge clk) (sel == 4'b1001) |-> (out == 16'h0200)
    );

// sel=1010 drives only bit 10 high.
    check_sel_1010: assert property (
        @(posedge clk) (sel == 4'b1010) |-> (out == 16'h0400)
    );

// sel=1011 drives only bit 11 high.
    check_sel_1011: assert property (
        @(posedge clk) (sel == 4'b1011) |-> (out == 16'h0800)
    );

// sel=1100 drives only bit 12 high.
    check_sel_1100: assert property (
        @(posedge clk) (sel == 4'b1100) |-> (out == 16'h1000)
    );

// sel=1101 drives only bit 13 high.
    check_sel_1101: assert property (
        @(posedge clk) (sel == 4'b1101) |-> (out == 16'h2000)
    );

// sel=1110 drives only bit 14 high.
    check_sel_1110: assert property (
        @(posedge clk) (sel == 4'b1110) |-> (out == 16'h4000)
    );

// sel=1111 drives only bit 15 high.
    check_sel_1111: assert property (
        @(posedge clk) (sel == 4'b1111) |-> (out == 16'h8000)
    );

// Any non-listed sel value drives zero.
    check_default_zero: assert property (
        @(posedge clk) (sel > 4'hF) |-> (out == 16'h0000)
    );

// q captures d on the next rising edge.
    check_q_captures_d: assert property (
        @(posedge clk) 1'b1 |=> (q == $past(d))
    );

// B1 low forces X low.
    check_b1_low_forces_x_low: assert property (
        @(posedge clk) !B1 |-> !X
    );

// A1 high with B1 high drives X high.
    check_a1_high_with_b1_high_drives_x_high: assert property (
        @(posedge clk) (A1 && B1) |-> X
    );

// A2 high with B1 high drives X high.
    check_a2_high_with_b1_high_drives_x_high: assert property (
        @(posedge clk) (A2 && B1) |-> X
    );

// X high requires B1 to be high.
    check_x_high_requires_b1_high: assert property (
        @(posedge clk) X |-> B1
    );

// X high requires at least one A input to be high.
    check_x_high_requires_a_input_high: assert property (
        @(posedge clk) X |-> (A1 || A2)
    );

// sel=00 routes in0 to out.
    check_sel_00_routes_in0: assert property (
        @(posedge clk) (sel == 2'b00) |-> (out == in0)
    );

// sel=01 routes in1 to out.
    check_sel_01_routes_in1: assert property (
        @(posedge clk) (sel == 2'b01) |-> (out == in1)
    );

// sel=10 routes in2 to out.
    check_sel_10_routes_in2: assert property (
        @(posedge clk) (sel == 2'b10) |-> (out == in2)
    );

// sel=11 routes in3 to out.
    check_sel_11_routes_in3: assert property (
        @(posedge clk) (sel == 2'b11) |-> (out == in3)
    );

// Reset drives count to 0 on the next clock.
    check_reset_clears_count: assert property (
        @(posedge clk) reset |=> (count == 2'b00)
    );

// When enable is low, count holds its value.
    check_hold_when_disabled: assert property (
        @(posedge clk) disable iff (reset) !enable |=> (count == $past(count))
    );

// When enable is high, count increments by 1 (mod 4).
    check_increment_when_enabled: assert property (
        @(posedge clk) disable iff (reset) enable |=> (count == ($past(count) + 2'b01))
    );

// Incrementing from 3 wraps count back to 0.
    check_wrap_from_max: assert property (
        @(posedge clk) disable iff (reset) (enable && (count == 2'b11)) |=> (count == 2'b00)
    );

// When enabled, data_out captures data_in on the next clock.
    check_capture_when_enabled: assert property (
        @(posedge clk) en |=> (data_out == $past(data_in))
    );

// When disabled, data_out is forced low on the next clock.
    check_clear_when_disabled: assert property (
        @(posedge clk) !en |=> (data_out == 1'b0)
    );

// data_out is always either the previous cycle's data_in or 0.
    check_next_value_is_previous_input_or_zero: assert property (
        @(posedge clk) 1'b1 |=> ((data_out == $past(data_in)) || (data_out == 1'b0))
    );

// If data_in is 0 and enabled, data_out becomes 0 on the next clock.
    check_zero_input_sets_zero_when_enabled: assert property (
        @(posedge clk) (en && (data_in == 1'b0)) |=> (data_out == 1'b0)
    );

// If data_in is 1 and enabled, data_out becomes 1 on the next clock.
    check_one_input_sets_one_when_enabled: assert property (
        @(posedge clk) (en && (data_in == 1'b1)) |=> (data_out == 1'b1)
    );

// Sgn_Info must equal the XOR of Sgn_X and Sgn_Y.
    check_xor_function: assert property (
        @(posedge clk) Sgn_Info == (Sgn_X ^ Sgn_Y)
    );

// When Sgn_X equals Sgn_Y, Sgn_Info must be 0.
    check_equal_inputs_zero: assert property (
        @(posedge clk) (Sgn_X == Sgn_Y) |-> (Sgn_Info == 1'b0)
    );

// When Sgn_X differs from Sgn_Y, Sgn_Info must be 1.
    check_different_inputs_one: assert property (
        @(posedge clk) (Sgn_X != Sgn_Y) |-> (Sgn_Info == 1'b1)
    );

// SUM is the XOR of A and B.
    check_sum_xor: assert property (
        @(posedge clk) SUM == (A ^ B)
    );

// COUT is the AND of A and B.
    check_cout_and: assert property (
        @(posedge clk) COUT == (A & B)
    );

// When A and B are equal, SUM must be 0.
    check_sum_zero_when_equal: assert property (
        @(posedge clk) (A == B) |-> (SUM == 1'b0)
    );

// When A and B differ, SUM must be 1.
    check_sum_one_when_different: assert property (
        @(posedge clk) (A != B) |-> (SUM == 1'b1)
    );

// When A is 0, SUM must equal B.
    check_sum_follows_b_when_a0: assert property (
        @(posedge clk) (A == 1'b0) |-> (SUM == B)
    );

// When A is 1, SUM must be the inverse of B.
    check_sum_inverts_b_when_a1: assert property (
        @(posedge clk) (A == 1'b1) |-> (SUM == ~B)
    );

// When B is 0, SUM must equal A.
    check_sum_follows_a_when_b0: assert property (
        @(posedge clk) (B == 1'b0) |-> (SUM == A)
    );

// When B is 1, SUM must be the inverse of A.
    check_sum_inverts_a_when_b1: assert property (
        @(posedge clk) (B == 1'b1) |-> (SUM == ~A)
    );

// When both inputs are 0, COUT must be 0.
    check_cout_zero_when_both_zero: assert property (
        @(posedge clk) ((A == 1'b0) && (B == 1'b0)) |-> (COUT == 1'b0)
    );

// When both inputs are 1, COUT must be 1.
    check_cout_one_when_both_one: assert property (
        @(posedge clk) ((A == 1'b1) && (B == 1'b1)) |-> (COUT == 1'b1)
    );

// When A is 0, COUT must be 0.
    check_cout_zero_when_a0: assert property (
        @(posedge clk) (A == 1'b0) |-> (COUT == 1'b0)
    );

// When A is 1, COUT must equal B.
    check_cout_follows_b_when_a1: assert property (
        @(posedge clk) (A == 1'b1) |-> (COUT == B)
    );

// When B is 0, COUT must be 0.
    check_cout_zero_when_b0: assert property (
        @(posedge clk) (B == 1'b0) |-> (COUT == 1'b0)
    );

// When B is 1, COUT must equal A.
    check_cout_follows_a_when_b1: assert property (
        @(posedge clk) (B == 1'b1) |-> (COUT == A)
    );

// Reset clears the register on the next clock.
    check_reset_clears_register: assert property (
        @(posedge clk) reset |=> (q == 4'b0000)
    );

// Parallel load captures parallel_input when not in shift mode.
    check_parallel_load_captures_input: assert property (
        @(posedge clk) disable iff (reset)
        parallel_load |=> (q == $past(parallel_input))
    );

// Shift left moves bits [2:0] into [3:1] and inserts 0 into bit 0.
    check_shift_left_behavior: assert property (
        @(posedge clk) disable iff (reset)
        (!parallel_load && shift_left) |=> (q == {$past(q[2:0]), 1'b0})
    );

// Shift right moves bits [3:1] into [2:0] and inserts 0 into bit 3.
    check_shift_right_behavior: assert property (
        @(posedge clk) disable iff (reset)
        (!parallel_load && !shift_left && shift_right) |=> (q == {1'b0, $past(q[3:1])})
    );

// With no load or shift request, the register holds its value.
    check_hold_when_idle: assert property (
        @(posedge clk) disable iff (reset)
        (!parallel_load && !shift_left && !shift_right) |=> (q == $past(q))
    );

// Shift left has priority over shift right when both are asserted.
    check_shift_left_priority_over_right: assert property (
        @(posedge clk) disable iff (reset)
        (!parallel_load && shift_left && shift_right) |=> (q == {$past(q[2:0]), 1'b0})
    );

// 00 decodes to out0=1, out1=0, out2=0, out3=0.
    check_decode_00: assert property (
        @(posedge clk) (in == 2'b00) |-> (out0 == 1'b1) && (out1 == 1'b0) && (out2 == 1'b0) && (out3 == 1'b0)
    );

// 01 decodes to out0=0, out1=1, out2=0, out3=0.
    check_decode_01: assert property (
        @(posedge clk) (in == 2'b01) |-> (out0 == 1'b0) && (out1 == 1'b1) && (out2 == 1'b0) && (out3 == 1'b0)
    );

// 10 decodes to out0=0, out1=0, out2=1, out3=0.
    check_decode_10: assert property (
        @(posedge clk) (in == 2'b10) |-> (out0 == 1'b0) && (out1 == 1'b0) && (out2 == 1'b1) && (out3 == 1'b0)
    );

// 11 decodes to out0=0, out1=0, out2=0, out3=1.
    check_decode_11: assert property (
        @(posedge clk) (in == 2'b11) |-> (out0 == 1'b0) && (out1 == 1'b0) && (out2 == 1'b0) && (out3 == 1'b1)
    );

// Exactly one output is asserted for all input values.
    check_onehot_output: assert property (
        @(posedge clk) $onehot({out0, out1, out2, out3})
    );

// Output bits are never asserted in combination.
    check_output_mutex: assert property (
        @(posedge clk) !(out0 && out1) && !(out0 && out2) && !(out0 && out3) && !(out1 && out2) && !(out1 && out3) && !(out2 && out3)
    );

// Clock: clk (posedge). Reset: rst_n active-low, asynchronous.
    // Logic: sequential toggle on clk; output is 0 when reset is asserted.

    // During reset, pwm_out must be 0.
    check_reset_forces_low: assert property (
        @(posedge clk) !rst_n |-> (pwm_out == 1'b0)
    );

// On the first clock after reset deasserts, pwm_out is still 0.
    check_first_cycle_after_reset_release: assert property (
        @(posedge clk) disable iff (!rst_n) $rose(rst_n) |-> (pwm_out == 1'b0)
    );

// On the second clock after reset deasserts, pwm_out is 1.
    check_second_cycle_after_reset_release: assert property (
        @(posedge clk) disable iff (!rst_n) $rose(rst_n) |-> ##1 (pwm_out == 1'b1)
    );

// After reset deasserts, pwm_out toggles every clock.
    check_toggle_every_cycle: assert property (
        @(posedge clk) disable iff (!rst_n) $rose(rst_n) |-> ##1 (pwm_out == ~$past(pwm_out))
    );

// X equals (A1 & A2 & A3) | B1.
    check_function_equivalence: assert property (
        @(posedge clk) X == ((A1 & A2 & A3) | B1)
    );

// B1 high forces X high.
    check_b1_forces_x_high: assert property (
        @(posedge clk) B1 |-> X
    );

// A1, A2, and A3 high force X high.
    check_a_triplet_forces_x_high: assert property (
        @(posedge clk) (A1 & A2 & A3) |-> X
    );

// With B1 low, X equals A1 & A2 & A3.
    check_b1_low_reduces_to_and: assert property (
        @(posedge clk) !B1 |-> (X == (A1 & A2 & A3))
    );

// If X is low, then B1 is low and not all A inputs are high.
    check_x_low_implies_conditions: assert property (
        @(posedge clk) !X |-> (!B1 && !(A1 & A2 & A3))
    );

// If X is high, then B1 is high or all A inputs are high.
    check_x_high_implies_conditions: assert property (
        @(posedge clk) X |-> (B1 || (A1 & A2 & A3))
    );

// F equals A & ~B & ~C when A=1, B=0, C=0.
    check_f_true_m3: assert property (
        @(posedge clk) (A && !B && !C) |-> (F == 1'b1)
    );

// F equals A & ~B & C when A=1, B=0, C=1.
    check_f_true_m2: assert property (
        @(posedge clk) (A && !B && C) |-> (F == 1'b1)
    );

// F equals A & B & ~C when A=1, B=1, C=0.
    check_f_true_m1: assert property (
        @(posedge clk) (A && B && !C) |-> (F == 1'b1)
    );

// F equals A & B & C when A=1, B=1, C=1.
    check_f_true_m0: assert property (
        @(posedge clk) (A && B && C) |-> (F == 1'b1)
    );

// F equals 0 when A=0 and B=0 (regardless of C).
    check_f_zero_when_a0_b0: assert property (
        @(posedge clk) (!A && !B) |-> (F == 1'b0)
    );

// F equals 0 when A=0 and B=1 (regardless of C).
    check_f_zero_when_a0_b1: assert property (
        @(posedge clk) (!A && B) |-> (F == 1'b0)
    );

// Z must equal A when TE_B is low.
    check_select_a_when_te_b_low: assert property (
        @(posedge clk) !TE_B |-> (Z == A)
    );

// Z must be high when TE_B is high.
    check_te_b_forces_high: assert property (
        @(posedge clk) TE_B |-> (Z == 1'b1)
    );

// A high with TE_B low must drive Z high.
    check_a_high_drives_z_high: assert property (
        @(posedge clk) (!TE_B && A) |-> (Z == 1'b1)
    );

// A low with TE_B low must drive Z low.
    check_a_low_drives_z_low: assert property (
        @(posedge clk) (!TE_B && !A) |-> (Z == 1'b0)
    );

// Result matches the selected arithmetic operation.
    check_function_select: assert property (
        @(posedge clk) result == (op ? (a - b) : (a + b))
    );

// When op is 0, result is the 4-bit sum of a and b.
    check_addition_result: assert property (
        @(posedge clk) (op == 1'b0) |-> (result == (a + b))
    );

// When op is 1, result is the 4-bit difference of a and b.
    check_subtraction_result: assert property (
        @(posedge clk) (op == 1'b1) |-> (result == (a - b))
    );

// Zero on b passes a through unchanged regardless of op.
    check_b_zero_passthrough: assert property (
        @(posedge clk) (b == 4'h0) |-> (result == a)
    );

// Equal operands yield zero on subtraction.
    check_equal_operands_subtract_zero: assert property (
        @(posedge clk) (op == 1'b1) && (a == b) |-> (result == 4'h0)
    );

// Adding 1 to zero on a returns 1.
    check_add_one_to_zero: assert property (
        @(posedge clk) (op == 1'b0) && (a == 4'h0) && (b == 4'h1) |-> (result == 4'h1)
    );

// Subtracting 1 from zero on a returns 15.
    check_sub_one_from_zero: assert property (
        @(posedge clk) (op == 1'b1) && (a == 4'h0) && (b == 4'h1) |-> (result == 4'hF)
    );

// eq must equal the bitwise equality of the two inputs.
    check_eq_definition: assert property (
        @(posedge clk) eq == (a == b)
    );

// When a equals b, only eq can be asserted.
    check_eq_only_when_a_eq_b: assert property (
        @(posedge clk) (a == b) |-> (eq && !gt && !lt)
    );

// Y must match the implemented OAI21 function.
    check_functional_equivalence: assert property (
        @(posedge clk) Y == ~((A | B) & C)
    );

// When C is low, Y must be high.
    check_c_low_forces_y_high: assert property (
        @(posedge clk) !C |-> Y
    );

// When both A and B are low, Y must be high.
    check_ab_low_forces_y_high: assert property (
        @(posedge clk) (!A && !B) |-> Y
    );

// When A is high and C is high, Y must be low.
    check_a_high_c_high_forces_y_low: assert property (
        @(posedge clk) (A && C) |-> !Y
    );

// When B is high and C is high, Y must be low.
    check_b_high_c_high_forces_y_low: assert property (
        @(posedge clk) (B && C) |-> !Y
    );

// aluflags[3:2] encode zero and sign from aluresult.
    check_aluflags_zero_sign: assert property (
        @(posedge clk)
        aluflags[3:2] == {aluresult[31], (aluresult == 32'h0)}
    );

// When FSM_selector_C is high, the next state is 00.
    check_reset_forces_zero: assert property (
        @(posedge clk_IBUF_BUFG) FSM_selector_C |=> (FSM_sequential_state_reg_reg == 2'b00)
    );

// When FSM_selector_C is low, the next state increments by AR modulo 4.
    check_increment_by_ar: assert property (
        @(posedge clk_IBUF_BUFG) !FSM_selector_C |=> (FSM_sequential_state_reg_reg == ($past(FSM_sequential_state_reg_reg) + $past(AR)))
    );

// When AR is 0, the next state holds its value.
    check_hold_when_ar_zero: assert property (
        @(posedge clk_IBUF_BUFG) (!FSM_selector_C && (AR == 1'b0)) |=> (FSM_sequential_state_reg_reg == $past(FSM_sequential_state_reg_reg))
    );

// When AR is 1, the next state increments by 1 modulo 4.
    check_increment_by_one: assert property (
        @(posedge clk_IBUF_BUFG) (!FSM_selector_C && (AR == 1'b1)) |=> (FSM_sequential_state_reg_reg == ($past(FSM_sequential_state_reg_reg) + 2'd1))
    );

// When AR is 2, the next state increments by 2 modulo 4.
    check_increment_by_two: assert property (
        @(posedge clk_IBUF_BUFG) (!FSM_selector_C && (AR == 2'b10)) |=> (FSM_sequential_state_reg_reg == ($past(FSM_sequential_state_reg_reg) + 2'd2))
    );

// When AR is 3, the next state increments by 3 modulo 4.
    check_increment_by_three: assert property (
        @(posedge clk_IBUF_BUFG) (!FSM_selector_C && (AR == 2'b11)) |=> (FSM_sequential_state_reg_reg == ($past(FSM_sequential_state_reg_reg) + 2'd3))
    );

// Y must equal the NOR of A, B, C, and D_N.
    check_nor_function: assert property (
        @(posedge clk) Y == ~(A | B | C | D_N)
    );

// A high must force Y low.
    check_a_high_forces_y_low: assert property (
        @(posedge clk) A |-> !Y
    );

// B high must force Y low.
    check_b_high_forces_y_low: assert property (
        @(posedge clk) B |-> !Y
    );

// C high must force Y low.
    check_c_high_forces_y_low: assert property (
        @(posedge clk) C |-> !Y
    );

// D_N high must force Y low.
    check_d_n_high_forces_y_low: assert property (
        @(posedge clk) D_N |-> !Y
    );

// All inputs low must drive Y high.
    check_all_inputs_low_drives_y_high: assert property (
        @(posedge clk) (!A && !B && !C && !D_N) |-> Y
    );

// Y high implies all inputs are low.
    check_y_high_implies_all_inputs_low: assert property (
        @(posedge clk) Y |-> (!A && !B && !C && !D_N)
    );

// S equals A minus B (32-bit two's complement).
    check_subtraction_result: assert property (
        @(posedge clk) S == (A - B)
    );

// LSB of S equals XOR of LSBs of A and B.
    check_lsb_xor: assert property (
        @(posedge clk) S[0] == (A[0] ^ B[0])
    );

// When B is zero, S equals A.
    check_zero_subtrahend: assert property (
        @(posedge clk) (B == 32'h0) |-> (S == A)
    );

// When A is zero, S equals two's complement of B.
    check_zero_minuend: assert property (
        @(posedge clk) (A == 32'h0) |-> (S == ~B + 32'h1)
    );

// When A equals B, S is zero.
    check_equal_operands: assert property (
        @(posedge clk) (A == B) |-> (S == 32'h0)
    );

// 0000 maps to 00.
    check_map_0000: assert property (
        @(posedge clk) (in == 4'b0000) |-> (out == 2'b00)
    );

// 0001 maps to 01.
    check_map_0001: assert property (
        @(posedge clk) (in == 4'b0001) |-> (out == 2'b01)
    );

// 0010 maps to 01.
    check_map_0010: assert property (
        @(posedge clk) (in == 4'b0010) |-> (out == 2'b01)
    );

// 0011 maps to 10.
    check_map_0011: assert property (
        @(posedge clk) (in == 4'b0011) |-> (out == 2'b10)
    );

// 0100 maps to 01.
    check_map_0100: assert property (
        @(posedge clk) (in == 4'b0100) |-> (out == 2'b01)
    );

// 0101 maps to 10.
    check_map_0101: assert property (
        @(posedge clk) (in == 4'b0101) |-> (out == 2'b10)
    );

// 0110 maps to 10.
    check_map_0110: assert property (
        @(posedge clk) (in == 4'b0110) |-> (out == 2'b10)
    );

// 0111 maps to 11.
    check_map_0111: assert property (
        @(posedge clk) (in == 4'b0111) |-> (out == 2'b11)
    );

// 1000 maps to 01.
    check_map_1000: assert property (
        @(posedge clk) (in == 4'b1000) |-> (out == 2'b01)
    );

// 1001 maps to 10.
    check_map_1001: assert property (
        @(posedge clk) (in == 4'b1001) |-> (out == 2'b10)
    );

// 1010 maps to 10.
    check_map_1010: assert property (
        @(posedge clk) (in == 4'b1010) |-> (out == 2'b10)
    );

// 1011 maps to 11.
    check_map_1011: assert property (
        @(posedge clk) (in == 4'b1011) |-> (out == 2'b11)
    );

// 1100 maps to 10.
    check_map_1100: assert property (
        @(posedge clk) (in == 4'b1100) |-> (out == 2'b10)
    );

// 1101 maps to 11.
    check_map_1101: assert property (
        @(posedge clk) (in == 4'b1101) |-> (out == 2'b11)
    );

// 1110 maps to 11.
    check_map_1110: assert property (
        @(posedge clk) (in == 4'b1110) |-> (out == 2'b11)
    );

// 1111 maps to 10.
    check_map_1111: assert property (
        @(posedge clk) (in == 4'b1111) |-> (out == 2'b10)
    );

// op is 0 when clr is 1.
    check_clear_forces_zero: assert property (
        @(posedge clk) clr |-> (op == 1'b0)
    );

// With ce=1, op captures ~ip on the next clock.
    check_capture_inverted_when_ce_high: assert property (
        @(posedge clk) disable iff (clr) ce |=> (op == ~$past(ip))
    );

// With ce=0, op holds its previous value.
    check_hold_when_ce_low: assert property (
        @(posedge clk) disable iff (clr) !ce |=> (op == $past(op))
    );

// With ce=1, op equals ~ip on the next clock.
    check_next_cycle_matches_inversion_when_ce_high: assert property (
        @(posedge clk) disable iff (clr) ce |=> (op == ~$past(ip))
    );

// Reset drives io_out to io_init on the next clock.
    check_reset_sets_output: assert property (
        @(posedge clock) reset |=> (io_out == $past(io_init))
    );

// With enable high, io_out captures io_in on the next clock.
    check_enable_captures_input: assert property (
        @(posedge clock) disable iff (reset) io_enable |=> (io_out == $past(io_in))
    );

// With enable low, io_out holds its previous value.
    check_disable_holds_output: assert property (
        @(posedge clock) disable iff (reset) !io_enable |=> (io_out == $past(io_out))
    );

// When enabled and io_in equals io_out, io_out remains unchanged.
    check_enable_no_change_when_input_matches_output: assert property (
        @(posedge clock) disable iff (reset) (io_enable && (io_in == io_out)) |=> (io_out == $past(io_out))
    );

// When enabled and io_in differs from io_out, io_out updates to io_in.
    check_enable_updates_output_when_input_differs: assert property (
        @(posedge clock) disable iff (reset) (io_enable && (io_in != io_out)) |=> (io_out == $past(io_in))
    );

// g_out must equal a AND b.
    check_g_out_and: assert property (
        @(posedge clk) g_out == (a & b)
    );

// p_out must equal a OR b.
    check_p_out_or: assert property (
        @(posedge clk) p_out == (a | b)
    );

// If both inputs are 1, both outputs must be 1.
    check_both_high: assert property (
        @(posedge clk) (a && b) |-> (g_out && p_out)
    );

// If either input is 0, g_out must be 0.
    check_g_out_zero_when_any_zero: assert property (
        @(posedge clk) (!a || !b) |-> !g_out
    );

// If either input is 1, p_out must be 1.
    check_p_out_one_when_any_one: assert property (
        @(posedge clk) (a || b) |-> p_out
    );

// If both inputs are 0, both outputs must be 0.
    check_both_low: assert property (
        @(posedge clk) (!a && !b) |-> (!g_out && !p_out)
    );

// key_input 0000000001 drives led_output to 00001.
    check_map_0000000001: assert property (
        @(posedge clk) (key_input == 9'b0000000001) |-> (led_output == 5'b00001)
    );

// key_input 0000000010 drives led_output to 00010.
    check_map_0000000010: assert property (
        @(posedge clk) (key_input == 9'b0000000010) |-> (led_output == 5'b00010)
    );

// key_input 0000000100 drives led_output to 00100.
    check_map_0000000100: assert property (
        @(posedge clk) (key_input == 9'b0000000100) |-> (led_output == 5'b00100)
    );

// key_input 0000001000 drives led_output to 01000.
    check_map_0000001000: assert property (
        @(posedge clk) (key_input == 9'b0000001000) |-> (led_output == 5'b01000)
    );

// key_input 0000010000 drives led_output to 10000.
    check_map_0000010000: assert property (
        @(posedge clk) (key_input == 9'b0000010000) |-> (led_output == 5'b10000)
    );

// key_input 0000100000 drives led_output to 00000.
    check_map_0000100000: assert property (
        @(posedge clk) (key_input == 9'b0000100000) |-> (led_output == 5'b00000)
    );

// key_input 0001000000 drives led_output to 11111.
    check_map_0001000000: assert property (
        @(posedge clk) (key_input == 9'b0001000000) |-> (led_output == 5'b11111)
    );

// X equals the AND of all four inputs.
    check_function_equivalence: assert property (
        @(posedge clk) X == (A & B & C & D)
    );

// If all inputs are HIGH, X must be HIGH.
    check_all_high_implies_x_high: assert property (
        @(posedge clk) (A & B & C & D) |-> X
    );

// If any input is LOW, X must be LOW.
    check_any_low_implies_x_low: assert property (
        @(posedge clk) (!A || !B || !C || !D) |-> !X
    );

// A HIGH X requires all inputs to be HIGH.
    check_x_high_requires_all_high: assert property (
        @(posedge clk) X |-> (A & B & C & D)
    );

// A LOW X implies at least one input is LOW.
    check_x_low_requires_any_low: assert property (
        @(posedge clk) !X |-> (!A || !B || !C || !D)
    );

// X must equal the OR of A, B, and C.
    check_or_function: assert property (
        @(posedge clk) X == (A | B | C)
    );

// A high must drive X high.
    check_a_high_sets_x: assert property (
        @(posedge clk) A |-> X
    );

// B high must drive X high.
    check_b_high_sets_x: assert property (
        @(posedge clk) B |-> X
    );

// C high must drive X high.
    check_c_high_sets_x: assert property (
        @(posedge clk) C |-> X
    );

// All inputs low must drive X low.
    check_all_low_clears_x: assert property (
        @(posedge clk) (!A && !B && !C) |-> !X
    );

// X high implies at least one input is high.
    check_x_high_requires_some_input: assert property (
        @(posedge clk) X |-> (A || B || C)
    );

// out_comb must match the RTL expression.
    check_out_matches_rtl_expr: assert property (
        @(posedge clk) out_comb == ((a & ~b) | (~a & b))
    );

// When a is 0 and b is 1, out_comb must be 1.
    check_a0_b1_sets_out: assert property (
        @(posedge clk) (a == 1'b0 && b == 1'b1) |-> (out_comb == 1'b1)
    );

// When a is 1 and b is 0, out_comb must be 1.
    check_a1_b0_sets_out: assert property (
        @(posedge clk) (a == 1'b1 && b == 1'b0) |-> (out_comb == 1'b1)
    );

// When a equals b, out_comb must be 0.
    check_equal_inputs_clear_out: assert property (
        @(posedge clk) (a == b) |-> (out_comb == 1'b0)
    );

// When a is 1 and b is 1, out_comb must be 0.
    check_a1_b1_clears_out: assert property (
        @(posedge clk) (a == 1'b1 && b == 1'b1) |-> (out_comb == 1'b0)
    );

// When a is 0 and b is 0, out_comb must be 0.
    check_a0_b0_clears_out: assert property (
        @(posedge clk) (a == 1'b0 && b == 1'b0) |-> (out_comb == 1'b0)
    );

// When A1 is high and A2 is low, Y follows B2.
    check_select_10: assert property (
        @(posedge clk) (A1_N && !A2_N) |-> (Y == B2)
    );

// When both select inputs are high, Y follows B1.
    check_select_11: assert property (
        @(posedge clk) (A1_N && A2_N) |-> (Y == B1)
    );

// gray[3] mirrors binary[3].
    check_gray3_mirrors_binary3: assert property (
        @(posedge clk) gray[3] == binary[3]
    );

// gray[2] is binary[3] XOR binary[2].
    check_gray2_is_binary3_xor_binary2: assert property (
        @(posedge clk) gray[2] == (binary[3] ^ binary[2])
    );

// gray[1] is binary[2] XOR binary[1].
    check_gray1_is_binary2_xor_binary1: assert property (
        @(posedge clk) gray[1] == (binary[2] ^ binary[1])
    );

// gray[0] is binary[1] XOR binary[0].
    check_gray0_is_binary1_xor_binary0: assert property (
        @(posedge clk) gray[0] == (binary[1] ^ binary[0])
    );

// C must equal the 4-bit sum of A and B.
    check_sum_matches_addition: assert property (
        @(posedge clk) C == (A + B)
    );

// Bit 0 of C must match the least-significant sum bit.
    check_lsb_sum: assert property (
        @(posedge clk) C[0] == (A[0] ^ B[0])
    );

// Bit 1 of C must include the carry from bit 0.
    check_bit1_sum: assert property (
        @(posedge clk) C[1] == (A[1] ^ B[1] ^ (A[0] & B[0]))
    );

// Bit 2 of C must include the carry from bits 0 and 1.
    check_bit2_sum: assert property (
        @(posedge clk) C[2] == (A[2] ^ B[2] ^ ((A[1] & B[1]) | ((A[0] & B[0]) & (A[1] | B[1]))))
    );

// Bit 3 of C must include the carry from bits 0 through 2.
    check_bit3_sum: assert property (
        @(posedge clk) C[3] == (A[3] ^ B[3] ^ ((A[2] & B[2]) | ((A[1] & B[1]) & (A[2] | B[2])) | ((A[0] & B[0]) & (A[1] | B[1]) & (A[2] | B[2]))))
    );

// Addition opcode drives the sum of A and B.
    check_addition: assert property (
        @(posedge clk) (op == 4'b0000) |-> (Y == (A + B))
    );

// Subtraction opcode drives A minus B.
    check_subtraction: assert property (
        @(posedge clk) (op == 4'b0001) |-> (Y == (A - B))
    );

// AND opcode drives the bitwise AND of A and B.
    check_and_operation: assert property (
        @(posedge clk) (op == 4'b0010) |-> (Y == (A & B))
    );

// OR opcode drives the bitwise OR of A and B.
    check_or_operation: assert property (
        @(posedge clk) (op == 4'b0011) |-> (Y == (A | B))
    );

// XOR opcode drives the bitwise XOR of A and B.
    check_xor_operation: assert property (
        @(posedge clk) (op == 4'b0100) |-> (Y == (A ^ B))
    );

// NOT-A opcode drives the bitwise complement of A.
    check_not_a_operation: assert property (
        @(posedge clk) (op == 4'b0101) |-> (Y == (~A))
    );

// Shift-left opcode drives A shifted left by one bit.
    check_shift_left_operation: assert property (
        @(posedge clk) (op == 4'b0110) |-> (Y == ({A[14:0], 1'b0}))
    );

// Shift-right opcode drives A shifted right by one bit.
    check_shift_right_operation: assert property (
        @(posedge clk) (op == 4'b0111) |-> (Y == ({1'b0, A[15:1]}))
    );

// Rotate-left opcode drives A rotated left by one bit.
    check_rotate_left_operation: assert property (
        @(posedge clk) (op == 4'b1000) |-> (Y == ({A[14:0], A[15]}))
    );

// Rotate-right opcode drives A rotated right by one bit.
    check_rotate_right_operation: assert property (
        @(posedge clk) (op == 4'b1001) |-> (Y == ({A[0], A[15:1]}))
    );

// Any unimplemented opcode drives zero.
    check_default_zero: assert property (
        @(posedge clk) (op >= 4'b1010) |-> (Y == 16'h0000)
    );

// out_xor is the XOR of the selected input with a.
    check_out_xor_function: assert property (
        @(posedge clk) out_xor == ((sel_b2 ? b : (sel_b1 ? b : a)) ^ a)
    );

// out_xor_inv is the bitwise inversion of out_xor.
    check_out_xor_inv_function: assert property (
        @(posedge clk) out_xor_inv == ~out_xor
    );

// out_logical_inv is the logical inversion of out_xor.
    check_out_logical_inv_function: assert property (
        @(posedge clk) out_logical_inv == !out_xor
    );

// When enable is low, the output must be zero.
    check_disable_clears_out: assert property (
        @(posedge clk) !enable |-> (out == 4'b0000)
    );

// When enable is high and sel==00, out equals in0.
    check_sel00_when_enabled: assert property (
        @(posedge clk) enable && (sel == 2'b00) |-> (out == in0)
    );

// When enable is high and sel==01, out equals in1.
    check_sel01_when_enabled: assert property (
        @(posedge clk) enable && (sel == 2'b01) |-> (out == in1)
    );

// When enable is high and sel==10, out equals in2.
    check_sel10_when_enabled: assert property (
        @(posedge clk) enable && (sel == 2'b10) |-> (out == in2)
    );

// When enable is high and sel==11, out equals in3.
    check_sel11_when_enabled: assert property (
        @(posedge clk) enable && (sel == 2'b11) |-> (out == in3)
    );

// ctrl[7:5]==000 selects 0000.
    check_ctrl_000_maps_to_0000: assert property (
        @(posedge clk)
        (ctrl[7:5] == 3'b000) |-> (td_mode == 4'b0000)
    );

// ctrl[7:5]==001 selects 1000.
    check_ctrl_001_maps_to_1000: assert property (
        @(posedge clk)
        (ctrl[7:5] == 3'b001) |-> (td_mode == 4'b1000)
    );

// ctrl[7:5]==010 selects 0100.
    check_ctrl_010_maps_to_0100: assert property (
        @(posedge clk)
        (ctrl[7:5] == 3'b010) |-> (td_mode == 4'b0100)
    );

// ctrl[7:5]==011 selects 1100.
    check_ctrl_011_maps_to_1100: assert property (
        @(posedge clk)
        (ctrl[7:5] == 3'b011) |-> (td_mode == 4'b1100)
    );

// ctrl[7:5]==100 selects 0010.
    check_ctrl_100_maps_to_0010: assert property (
        @(posedge clk)
        (ctrl[7:5] == 3'b100) |-> (td_mode == 4'b0010)
    );

// ctrl[7:5]==101 selects 1010.
    check_ctrl_101_maps_to_1010: assert property (
        @(posedge clk)
        (ctrl[7:5] == 3'b101) |-> (td_mode == 4'b1010)
    );

// ctrl[7:5]==110 selects 0101.
    check_ctrl_110_maps_to_0101: assert property (
        @(posedge clk)
        (ctrl[7:5] == 3'b110) |-> (td_mode == 4'b0101)
    );

// ctrl[7:5]==111 selects 1111.
    check_ctrl_111_maps_to_1111: assert property (
        @(posedge clk)
        (ctrl[7:5] == 3'b111) |-> (td_mode == 4'b1111)
    );

// Output is always exactly one-hot.
    check_out_onehot: assert property (
        @(posedge clk) $onehot(out)
    );

// Input 0000 decodes to bit 0.
    check_decode_0000: assert property (
        @(posedge clk) (in == 4'b0000) |-> (out == 16'b0000000000000001)
    );

// Input 0001 decodes to bit 1.
    check_decode_0001: assert property (
        @(posedge clk) (in == 4'b0001) |-> (out == 16'b0000000000000010)
    );

// Input 0010 decodes to bit 2.
    check_decode_0010: assert property (
        @(posedge clk) (in == 4'b0010) |-> (out == 16'b0000000000000100)
    );

// Input 0011 decodes to bit 3.
    check_decode_0011: assert property (
        @(posedge clk) (in == 4'b0011) |-> (out == 16'b0000000000001000)
    );

// Input 0100 decodes to bit 4.
    check_decode_0100: assert property (
        @(posedge clk) (in == 4'b0100) |-> (out == 16'b0000000000010000)
    );

// Input 0101 decodes to bit 5.
    check_decode_0101: assert property (
        @(posedge clk) (in == 4'b0101) |-> (out == 16'b0000000000100000)
    );

// Input 0110 decodes to bit 6.
    check_decode_0110: assert property (
        @(posedge clk) (in == 4'b0110) |-> (out == 16'b0000000001000000)
    );

// Input 0111 decodes to bit 7.
    check_decode_0111: assert property (
        @(posedge clk) (in == 4'b0111) |-> (out == 16'b0000000010000000)
    );

// Input 1000 decodes to bit 8.
    check_decode_1000: assert property (
        @(posedge clk) (in == 4'b1000) |-> (out == 16'b0000000100000000)
    );

// Input 1001 decodes to bit 9.
    check_decode_1001: assert property (
        @(posedge clk) (in == 4'b1001) |-> (out == 16'b0000001000000000)
    );

// Input 1010 decodes to bit 10.
    check_decode_1010: assert property (
        @(posedge clk) (in == 4'b1010) |-> (out == 16'b0000010000000000)
    );

// Input 1011 decodes to bit 11.
    check_decode_1011: assert property (
        @(posedge clk) (in == 4'b1011) |-> (out == 16'b0000100000000000)
    );

// Input 1100 decodes to bit 12.
    check_decode_1100: assert property (
        @(posedge clk) (in == 4'b1100) |-> (out == 16'b0001000000000000)
    );

// Input 1101 decodes to bit 13.
    check_decode_1101: assert property (
        @(posedge clk) (in == 4'b1101) |-> (out == 16'b0010000000000000)
    );

// Input 1110 decodes to bit 14.
    check_decode_1110: assert property (
        @(posedge clk) (in == 4'b1110) |-> (out == 16'b0100000000000000)
    );

// Input 1111 decodes to bit 15.
    check_decode_1111: assert property (
        @(posedge clk) (in == 4'b1111) |-> (out == 16'b1000000000000000)
    );

// Output equals a ^ b on a rising edge.
    check_xor_on_a: assert property (
        @(posedge clk) out_comb_logic == (a ^ b)
    );

// Output equals a ^ b on a falling edge.
    check_xor_on_a_fall: assert property (
        @(negedge clk) out_comb_logic == (a ^ b)
    );

// Output equals a ^ b on b rising edge.
    check_xor_on_b: assert property (
        @(posedge clk) out_comb_logic == (a ^ b)
    );

// Output equals a ^ b on b falling edge.
    check_xor_on_b_fall: assert property (
        @(negedge clk) out_comb_logic == (a ^ b)
    );

// When a==b, out_comb_logic is 0 on a rising edge.
    check_zero_when_equal_a: assert property (
        @(posedge clk) (a == b) |-> (out_comb_logic == 1'b0)
    );

// When a==b, out_comb_logic is 0 on a falling edge.
    check_zero_when_equal_a_fall: assert property (
        @(negedge clk) (a == b) |-> (out_comb_logic == 1'b0)
    );

// When a!=b, out_comb_logic is 1 on a rising edge.
    check_one_when_not_equal_a: assert property (
        @(posedge clk) (a != b) |-> (out_comb_logic == 1'b1)
    );

// When a!=b, out_comb_logic is 1 on a falling edge.
    check_one_when_not_equal_a_fall: assert property (
        @(negedge clk) (a != b) |-> (out_comb_logic == 1'b1)
    );

// X matches the implemented OR/NOT function.
    check_functional_equivalence: assert property (
        @(posedge clk) X == (A | B | C | ~D_N)
    );

// A high forces X high.
    check_a_high_sets_x: assert property (
        @(posedge clk) A |-> X
    );

// B high forces X high.
    check_b_high_sets_x: assert property (
        @(posedge clk) B |-> X
    );

// C high forces X high.
    check_c_high_sets_x: assert property (
        @(posedge clk) C |-> X
    );

// D_N low forces X high.
    check_d_n_low_sets_x: assert property (
        @(posedge clk) !D_N |-> X
    );

// With all inputs inactive, X is low.
    check_all_inputs_inactive_clear_x: assert property (
        @(posedge clk) (!A && !B && !C && D_N) |-> !X
    );

// A high X requires at least one active input.
    check_x_high_requires_active_input: assert property (
        @(posedge clk) X |-> (A || B || C || !D_N)
    );

// X equals A|B|C|~D_N.
    check_function_equivalence: assert property (
        @(posedge clk) X == (A | B | C | ~D_N)
    );

// When all inputs are 0, X must be 0.
    check_all_zero_implies_zero: assert property (
        @(posedge clk) (!A && !B && !C && D_N) |-> (X == 1'b0)
    );

// When any input is 1, X must be 1.
    check_any_one_implies_one: assert property (
        @(posedge clk) (A || B || C || !D_N) |-> (X == 1'b1)
    );

// A high forces X high.
    check_a_high_sets_x: assert property (
        @(posedge clk) A |-> (X == 1'b1)
    );

// B high forces X high.
    check_b_high_sets_x: assert property (
        @(posedge clk) B |-> (X == 1'b1)
    );

// C high forces X high.
    check_c_high_sets_x: assert property (
        @(posedge clk) C |-> (X == 1'b1)
    );

// D_N low forces X high.
    check_dn_low_sets_x: assert property (
        @(posedge clk) !D_N |-> (X == 1'b1)
    );

// X low implies all inputs are 0.
    check_zero_implies_all_zero: assert property (
        @(posedge clk) (X == 1'b0) |-> (!A && !B && !C && D_N)
    );

// X high implies at least one input is 1.
    check_one_implies_any_one: assert property (
        @(posedge clk) (X == 1'b1) |-> (A || B || C || !D_N)
    );

// X must equal the AND of all four inputs.
    check_x_matches_and4: assert property (
        @(posedge clk) X == (A & B & C & D)
    );

// A low forces X low.
    check_a_low_forces_x_low: assert property (
        @(posedge clk) !A |-> !X
    );

// B low forces X low.
    check_b_low_forces_x_low: assert property (
        @(posedge clk) !B |-> !X
    );

// C low forces X low.
    check_c_low_forces_x_low: assert property (
        @(posedge clk) !C |-> !X
    );

// D low forces X low.
    check_d_low_forces_x_low: assert property (
        @(posedge clk) !D |-> !X
    );

// All four high drive X high.
    check_all_high_drives_x_high: assert property (
        @(posedge clk) (A & B & C & D) |-> X
    );

// When a is greater than or equal to b, out equals a.
    check_out_eq_a_when_a_ge_b: assert property (
        @(posedge clk) (a >= b) |-> (out == a)
    );

// When b is greater than a, out equals b.
    check_out_eq_b_when_b_gt_a: assert property (
        @(posedge clk) (b > a) |-> (out == b)
    );

// When a is greater than b, out is not zero.
    check_out_not_zero_when_a_gt_b: assert property (
        @(posedge clk) (a > b) |-> (out != 8'h00)
    );

// When a is less than b, out is not zero.
    check_out_not_zero_when_a_lt_b: assert property (
        @(posedge clk) (a < b) |-> (out != 8'h00)
    );

// When a is greater than b, out is not equal to b.
    check_out_ne_b_when_a_gt_b: assert property (
        @(posedge clk) (a > b) |-> (out != b)
    );

// When b is greater than a, out is not equal to a.
    check_out_ne_a_when_b_gt_a: assert property (
        @(posedge clk) (b > a) |-> (out != a)
    );

// Reset clears the stored output value.
    check_reset_clears_out_port: assert property (
        @(posedge clk) !reset_n |-> (out_port == 6'h00)
    );

// Reset clears the readback value.
    check_reset_clears_readdata: assert property (
        @(posedge clk) !reset_n |-> (readdata == 32'h00000000)
    );

// Address 0 writes load the lower 6 bits of writedata into out_port.
    check_write_loads_out_port: assert property (
        @(posedge clk) disable iff (!reset_n)
        (chipselect && !write_n && (address == 2'h0)) |=> (out_port == $past(writedata[5:0]))
    );

// Nonzero addresses do not modify out_port.
    check_nonzero_address_ignored: assert property (
        @(posedge clk) disable iff (!reset_n)
        ((address != 2'h0) || write_n || !chipselect) |=> (out_port == $past(out_port))
    );

// A write to address 0 with chipselect low does not modify out_port.
    check_chipselect_low_ignored: assert property (
        @(posedge clk) disable iff (!reset_n)
        (chipselect == 1'b0) |=> (out_port == $past(out_port))
    );

// A write to address 0 with write_n high does not modify out_port.
    check_write_n_high_ignored: assert property (
        @(posedge clk) disable iff (!reset_n)
        (write_n == 1'b1) |=> (out_port == $past(out_port))
    );

// Reads from address 0 return the current out_port value.
    check_read_address_0_returns_out_port: assert property (
        @(posedge clk) disable iff (!reset_n)
        (address == 2'h0) |-> (readdata == {26'b0, out_port})
    );

// Reads from nonzero addresses return zero.
    check_read_nonzero_address_returns_zero: assert property (
        @(posedge clk) disable iff (!reset_n)
        (address != 2'h0) |-> (readdata == 32'h00000000)
    );

// gray[3] must equal binary[8].
    check_gray3_matches_binary8: assert property (
        @(posedge clk) gray[3] == binary[8]
    );

// gray[2] must equal binary[8] XOR binary[7].
    check_gray2_matches_binary8_xor7: assert property (
        @(posedge clk) gray[2] == (binary[8] ^ binary[7])
    );

// gray[1] must equal binary[7] XOR binary[6].
    check_gray1_matches_binary7_xor6: assert property (
        @(posedge clk) gray[1] == (binary[7] ^ binary[6])
    );

// gray[0] must equal binary[6] XOR binary[5].
    check_gray0_matches_binary6_xor5: assert property (
        @(posedge clk) gray[0] == (binary[6] ^ binary[5])
    );

// X is 0 on the cycle after reset is asserted.
    check_reset_clears_x: assert property (
        @(posedge clk) reset |=> (X == 1'b0)
    );

// X is 0 on the cycle after reset is deasserted.
    check_reset_release_clears_x: assert property (
        @(posedge clk) reset ##1 !reset |=> (X == 1'b0)
    );

// When not in reset, X equals the previous cycle's A & B.
    check_and_update: assert property (
        @(posedge clk) disable iff (reset) 1'b1 |=> (X == ($past(A) & $past(B)))
    );

// When not in reset and A is 0, X becomes 0 on the next cycle.
    check_zero_when_a_zero: assert property (
        @(posedge clk) disable iff (reset) (A == 1'b0) |=> (X == 1'b0)
    );

// When not in reset and B is 0, X becomes 0 on the next cycle.
    check_zero_when_b_zero: assert property (
        @(posedge clk) disable iff (reset) (B == 1'b0) |=> (X == 1'b0)
    );

// When not in reset and both inputs are 1, X becomes 1 on the next cycle.
    check_one_when_both_one: assert property (
        @(posedge clk) disable iff (reset) (A == 1'b1 && B == 1'b1) |=> (X == 1'b1)
    );

// Y matches the implemented A211OI logic.
    check_functional_equivalence: assert property (
        @(posedge clk) Y == ~(A1 & A2 | B1 | C1)
    );

// A high B1 forces Y low.
    check_b1_forces_low: assert property (
        @(posedge clk) B1 |-> !Y
    );

// A high C1 forces Y low.
    check_c1_forces_low: assert property (
        @(posedge clk) C1 |-> !Y
    );

// A1 and A2 high together force Y low.
    check_a1_a2_force_low: assert property (
        @(posedge clk) (A1 && A2) |-> !Y
    );

// With no asserted NOR inputs, Y must be high.
    check_no_nor_inputs_drive_high: assert property (
        @(posedge clk) (!B1 && !C1 && !(A1 && A2)) |-> Y
    );

// A high Y requires all NOR inputs to be inactive.
    check_high_output_requires_no_nor_inputs: assert property (
        @(posedge clk) Y |-> (!B1 && !C1 && !(A1 && A2))
    );

// Y must match the RTL equation.
    check_function_equation: assert property (
        @(posedge clk) Y == ((A1 & A2) | B1)
    );

// B1 high must force Y high.
    check_b1_forces_y_high: assert property (
        @(posedge clk) B1 |-> Y
    );

// A1 and A2 high together must force Y high.
    check_a1_a2_force_y_high: assert property (
        @(posedge clk) (A1 & A2) |-> Y
    );

// With B1 low, Y must follow A1 & A2.
    check_b1_low_passes_a1_a2: assert property (
        @(posedge clk) !B1 |-> (Y == (A1 & A2))
    );

// With B1 low and A1 low, Y must be low.
    check_b1_low_a1_low_gives_y_low: assert property (
        @(posedge clk) (!B1 && !A1) |-> !Y
    );

// With B1 low and A2 low, Y must be low.
    check_b1_low_a2_low_gives_y_low: assert property (
        @(posedge clk) (!B1 && !A2) |-> !Y
    );

// A high Y must come from B1 or A1 & A2.
    check_y_high_has_valid_source: assert property (
        @(posedge clk) Y |-> (B1 || (A1 && A2))
    );

// out_and is the 4-bit AND of all four inputs.
    check_and_result: assert property (
        @(posedge clk) out_and == (in1 & in2 & in3 & in4)
    );

// out_or is the 4-bit OR of all four inputs.
    check_or_result: assert property (
        @(posedge clk) out_or == (in1 | in2 | in3 | in4)
    );

// out_xor is the 4-bit XOR of all four inputs.
    check_xor_result: assert property (
        @(posedge clk) out_xor == (in1 ^ in2 ^ in3 ^ in4)
    );

// If all inputs are zero, all outputs must be zero.
    check_zero_inputs_zero_outputs: assert property (
        @(posedge clk) ((in1 == 4'b0000) && (in2 == 4'b0000) && (in3 == 4'b0000) && (in4 == 4'b0000)) |-> ((out_and == 4'b0000) && (out_or == 4'b0000) && (out_xor == 4'b0000))
    );

// If any input is all ones, out_or must be all ones.
    check_any_all_ones_out_or_all_ones: assert property (
        @(posedge clk) ((in1 == 4'b1111) || (in2 == 4'b1111) || (in3 == 4'b1111) || (in4 == 4'b1111)) |-> (out_or == 4'b1111)
    );

// If all inputs are equal, out_xor must be zero.
    check_equal_inputs_zero_xor: assert property (
        @(posedge clk) ((in1 == in2) && (in2 == in3) && (in3 == in4)) |-> (out_xor == 4'b0000)
    );

// Reset low forces count to 0 on the next sampled cycle.
    check_reset_clears_count: assert property (
        @(posedge clk) !rst |=> (count == 3'b000)
    );

// When not in reset, count increments by 1 on the next sampled cycle.
    check_count_increments: assert property (
        @(posedge clk) disable iff (!rst) 1'b1 |=> (count == ($past(count) + 3'd1))
    );

// Count wraps from 7 back to 0 when not in reset.
    check_count_wraps: assert property (
        @(posedge clk) disable iff (!rst) (count == 3'b111) |=> (count == 3'b000)
    );

// SUM equals A + B when SUB is 0.
    check_add_mode: assert property (
        @(posedge CLK) !SUB |-> (SUM == (A + B))
    );

// SUM equals A + (B's 2's complement) when SUB is 1.
    check_sub_mode: assert property (
        @(posedge CLK) SUB |-> (SUM == (A + ((~B) + 4'b0001)))
    );

// In add mode, SUM equals A + B (4-bit wraparound).
    check_add_result: assert property (
        @(posedge CLK) !SUB |-> (SUM == (A + B))
    );

// In sub mode, SUM equals A + (B's 2's complement) (4-bit wraparound).
    check_sub_result: assert property (
        @(posedge CLK) SUB |-> (SUM == (A + ((~B) + 4'b0001)))
    );

// In sub mode, SUM equals A - B (4-bit wraparound).
    check_sub_result_alt: assert property (
        @(posedge CLK) SUB |-> (SUM == (A - B))
    );

// In add mode, SUM equals A + B (4-bit wraparound).
    check_add_result_alt: assert property (
        @(posedge CLK) !SUB |-> (SUM == (A + B))
    );

// In sub mode, SUM equals A + (B's 2's complement) (4-bit wraparound).
    check_sub_result_alt2: assert property (
        @(posedge CLK) SUB |-> (SUM == (A + ((~B) + 4'b0001)))
    );

// In sub mode, SUM equals A - B (4-bit wraparound).
    check_sub_result_alt3: assert property (
        @(posedge CLK) SUB |-> (SUM == (A - B))
    );

// CLR clears both Q and Q_next on the next cycle.
    check_clear_sets_outputs: assert property (
        @(posedge CLK) CLR |=> (Q == 4'b0000) && (Q_next == 4'b0000)
    );

// LOAD captures D into both Q and Q_next on the next cycle.
    check_load_captures_d: assert property (
        @(posedge CLK) disable iff (CLR) LOAD |=> (Q == $past(D)) && (Q_next == $past(D))
    );

// Without LOAD, Q_next shifts left by one and takes D[3] into bit 0.
    check_shift_updates_qnext: assert property (
        @(posedge CLK) disable iff (CLR) !LOAD |=> (Q_next == {$past(Q[2:0]), $past(D[3])})
    );

// Without LOAD, Q shifts left by one and takes D[3] into bit 0.
    check_shift_updates_q: assert property (
        @(posedge CLK) disable iff (CLR) !LOAD |=> (Q == {$past(Q[2:0]), $past(D[3])})
    );

// With LOAD, Q_next equals Q on the next cycle.
    check_load_keeps_qnext_equal_q: assert property (
        @(posedge CLK) LOAD |=> (Q_next == Q)
    );

// Without LOAD, Q_next equals Q on the next cycle.
    check_shift_keeps_qnext_equal_q: assert property (
        @(posedge CLK) disable iff (CLR) !LOAD |=> (Q_next == Q)
    );

// Addition mode returns the 8-bit sum.
    check_addition_result: assert property (
        @(posedge clk) (op == 2'b00) |-> (result == (a + b))
    );

// Subtraction mode returns the 8-bit difference.
    check_subtraction_result: assert property (
        @(posedge clk) (op == 2'b01) |-> (result == (a - b))
    );

// Y matches the RTL mux network for all S values.
    check_full_mux_function: assert property (
        @(posedge clk) disable iff (1'b0)
        Y == ((S1 == 1'b0) ? ((S0 == 1'b0) ? D0 : D1) : ((S0 == 1'b0) ? D2 : D3))
    );

// When S1 is low, Y selects between D0 and D1 on S0.
    check_low_s1_select: assert property (
        @(posedge clk) disable iff (1'b0)
        (S1 == 1'b0) |-> (Y == ((S0 == 1'b0) ? D0 : D1))
    );

// When S1 is high, Y selects between D2 and D3 on S0.
    check_high_s1_select: assert property (
        @(posedge clk) disable iff (1'b0)
        (S1 == 1'b1) |-> (Y == ((S0 == 1'b0) ? D2 : D3))
    );

// With S1 low and S0 low, Y follows D0.
    check_low_s1_low_s0_selects_d0: assert property (
        @(posedge clk) disable iff (1'b0)
        (S1 == 1'b0 && S0 == 1'b0) |-> (Y == D0)
    );

// With S1 low and S0 high, Y follows D1.
    check_low_s1_high_s0_selects_d1: assert property (
        @(posedge clk) disable iff (1'b0)
        (S1 == 1'b0 && S0 == 1'b1) |-> (Y == D1)
    );

// With S1 high and S0 low, Y follows D2.
    check_high_s1_low_s0_selects_d2: assert property (
        @(posedge clk) disable iff (1'b0)
        (S1 == 1'b1 && S0 == 1'b0) |-> (Y == D2)
    );

// With S1 high and S0 high, Y follows D3.
    check_high_s1_high_s0_selects_d3: assert property (
        @(posedge clk) disable iff (1'b0)
        (S1 == 1'b1 && S0 == 1'b1) |-> (Y == D3)
    );

// input_1==0 forces output_1 low.
    check_map_0: assert property (
        @(posedge clk) (input_1 == 4'd0) |-> (output_1 == 1'b0)
    );

// input_1==1 selects input_3.
    check_map_1: assert property (
        @(posedge clk) (input_1 == 4'd1) |-> (output_1 == input_3)
    );

// input_1==2 selects input_4.
    check_map_2: assert property (
        @(posedge clk) (input_1 == 4'd2) |-> (output_1 == input_4)
    );

// input_1==3 selects input_5.
    check_map_3: assert property (
        @(posedge clk) (input_1 == 4'd3) |-> (output_1 == input_5)
    );

// input_1==4 selects input_6.
    check_map_4: assert property (
        @(posedge clk) (input_1 == 4'd4) |-> (output_1 == input_6)
    );

// input_1==5 selects input_7.
    check_map_5: assert property (
        @(posedge clk) (input_1 == 4'd5) |-> (output_1 == input_7)
    );

// input_1==6 selects input_8.
    check_map_6: assert property (
        @(posedge clk) (input_1 == 4'd6) |-> (output_1 == input_8)
    );

// input_1==7 selects input_2[0].
    check_map_7: assert property (
        @(posedge clk) (input_1 == 4'd7) |-> (output_1 == input_2[0])
    );

// input_1==8..15 drive output_1 low.
    check_map_default: assert property (
        @(posedge clk) (input_1 >= 4'd8) |-> (output_1 == 1'b0)
    );

// out_and is the reduction AND of in.
    check_and_function: assert property (
        @(posedge clk) out_and == (&in)
    );

// X must equal A OR B.
    check_or_function: assert property (
        @(posedge clk) X == (A | B)
    );

// A high must drive X high.
    check_a_high_sets_x: assert property (
        @(posedge clk) A |-> X
    );

// B high must drive X high.
    check_b_high_sets_x: assert property (
        @(posedge clk) B |-> X
    );

// Both inputs low must drive X low.
    check_both_low_clear_x: assert property (
        @(posedge clk) (!A && !B) |-> !X
    );

// X low implies both inputs are low.
    check_x_low_implies_both_low: assert property (
        @(posedge clk) !X |-> (!A && !B)
    );

// Clear forces op low on the next clock.
    check_clear_forces_low: assert property (
        @(posedge clk) clr |=> (op == 1'b0)
    );

// Clear has priority over enable when both are asserted.
    check_clear_priority_over_enable: assert property (
        @(posedge clk) (clr && ce) |=> (op == 1'b0)
    );

// Enable sets op high on the next clock when clear is low.
    check_enable_sets_high: assert property (
        @(posedge clk) disable iff (clr) ce |=> (op == 1'b1)
    );

// Op holds its value when neither clear nor enable is asserted.
    check_hold_when_idle: assert property (
        @(posedge clk) disable iff (clr) (!ce && !clr) |=> (op == $past(op))
    );

// Clock: CLK (posedge). Reset: RST active-low, asynchronous. Sequential DFF with Q=1'b0 and QN=1'b1 when RST is LOW.

    // When RST is LOW at a clock edge, Q must be 0 and QN must be 1.
    check_reset_forces_outputs: assert property (
        @(posedge CLK) !RST |-> (Q == 1'b0) && (QN == 1'b1)
    );

// On the first clock after RST rises, Q captures D and QN captures ~D.
    check_capture_after_reset_release: assert property (
        @(posedge CLK) disable iff (!RST) $rose(RST) |-> ##1 (Q == $past(D)) && (QN == ~$past(D))
    );

// With RST HIGH, Q and QN are complementary on every clock edge.
    check_complementary_outputs_when_active: assert property (
        @(posedge CLK) disable iff (!RST) 1'b1 |-> (QN == ~Q)
    );

// With RST HIGH, Q holds its value when D is equal to the previous Q.
    check_q_holds_when_d_matches_prev_q: assert property (
        @(posedge CLK) disable iff (!RST) (D == $past(Q)) |-> ##1 (Q == $past(Q))
    );

// With RST HIGH, QN holds its value when D is equal to the previous QN.
    check_qn_holds_when_d_matches_prev_qn: assert property (
        @(posedge CLK) disable iff (!RST) (D == $past(QN)) |-> ##1 (QN == $past(QN))
    );

// With RST HIGH, QN holds its value when D is equal to the previous Q.
    check_qn_holds_when_d_matches_prev_q: assert property (
        @(posedge CLK) disable iff (!RST) (D == $past(Q)) |-> ##1 (QN == $past(Q))
    );

// With RST HIGH, Q holds its value when D is equal to the previous QN.
    check_q_holds_when_d_matches_prev_qn: assert property (
        @(posedge CLK) disable iff (!RST) (D == $past(QN)) |-> ##1 (Q == $past(QN))
    );

// X matches the implemented A211O function.
    check_functional_equivalence: assert property (
        @(posedge clk) X == ((A1 & A2) | B1 | C1)
    );

// B1 high forces X high.
    check_b1_forces_x_high: assert property (
        @(posedge clk) B1 |-> X
    );

// C1 high forces X high.
    check_c1_forces_x_high: assert property (
        @(posedge clk) C1 |-> X
    );

// A1 and A2 high together force X high.
    check_a1_a2_force_x_high: assert property (
        @(posedge clk) (A1 & A2) |-> X
    );

// With no asserted OR term, X must be low.
    check_no_or_term_means_x_low: assert property (
        @(posedge clk) !(B1 | C1 | (A1 & A2)) |-> !X
    );

// X low implies no asserted OR term.
    check_x_low_implies_no_or_term: assert property (
        @(posedge clk) !X |-> !(B1 | C1 | (A1 & A2))
    );

// Bit 0 sum matches the first full-adder XOR equation.
    check_bit0_sum: assert property (
        @(posedge clk) S[0] == (A[0] ^ B[0] ^ Cin)
    );

// Bit 2 sum uses the carry generated from bit 1.
    check_bit2_sum: assert property (
        @(posedge clk) S[2] == (A[2] ^ B[2] ^ (
            (A[1] & B[1]) |
            (B[1] & ((A[0] & B[0]) | (B[0] & Cin) | (A[0] & Cin))) |
            (A[1] & ((A[0] & B[0]) | (B[0] & Cin) | (A[0] & Cin)))
        ))
    );

// Reset drives count to zero on the next clock.
    check_reset_clears_count: assert property (
        @(posedge clk) !reset |=> (count == 4'b0000)
    );

// When enabled, count increments by one on the next clock.
    check_count_increments_when_enabled: assert property (
        @(posedge clk) disable iff (!reset)
        enable |=> (count == ($past(count) + 4'd1))
    );

// When not enabled, count holds its value on the next clock.
    check_count_holds_when_disabled: assert property (
        @(posedge clk) disable iff (!reset)
        !enable |=> (count == $past(count))
    );

// Count wraps from 15 back to 0 when enabled.
    check_count_wraps_from_max: assert property (
        @(posedge clk) disable iff (!reset)
        (enable && (count == 4'hF)) |=> (count == 4'h0)
    );

// q equals address shifted left by 2 with 00 appended.
    check_q_shift_and_zero: assert property (
        @(posedge clock) q == {address, 2'b00}
    );

// LSBs are always zero due to zero extension.
    check_q_lsb_zero: assert property (
        @(posedge clock) q[1:0] == 2'b00
    );

// Upper 9 bits match address.
    check_q_upper_matches_address: assert property (
        @(posedge clock) q[11:2] == address
    );

// When clock is low, q equals address shifted left by 2.
    check_q_when_clock_low: assert property (
        @(posedge clock) !clock |-> (q == {address, 2'b00})
    );

// When clock is high, q equals bitwise inversion of address shifted left by 2.
    check_q_when_clock_high: assert property (
        @(posedge clock) clock |-> (q == ~{address, 2'b00})
    );

// Reset drives count to zero on the next sampled cycle.
    check_reset_clears_count: assert property (
        @(posedge clk) rst |=> (count == 4'h0)
    );

// When not in reset, count increments by one on the next sampled cycle.
    check_count_increments: assert property (
        @(posedge clk) disable iff (rst) 1'b1 |=> (count == ($past(count) + 4'd1))
    );

// Count wraps from 15 back to 0 when not in reset.
    check_count_wraps: assert property (
        @(posedge clk) disable iff (rst) (count == 4'hF) |=> (count == 4'h0)
    );

// Reset clears both outputs on the next clock.
    check_reset_clears_outputs: assert property (
        @(posedge clk) rst |=> (control_o == 9'b0) && (pc_op == 2'b00)
    );

// When enabled, control_o[0] captures en_mem.
    check_control_en_mem_capture: assert property (
        @(posedge clk) disable iff (rst) en |=> (control_o[0] == $past(en_mem))
    );

// When enabled, control_o[1] captures should_branch.
    check_control_branch_capture: assert property (
        @(posedge clk) disable iff (rst) en |=> (control_o[1] == $past(should_branch))
    );

// When enabled, control_o[2] captures imm.
    check_control_imm_capture: assert property (
        @(posedge clk) disable iff (rst) en |=> (control_o[2] == $past(imm))
    );

// When enabled with imm high, pc_op selects 2'b10.
    check_pc_op_and_when_imm_high: assert property (
        @(posedge clk) disable iff (rst) (en && imm) |=> (pc_op == 2'b10)
    );

// When enabled with imm low, pc_op selects 2'b00.
    check_pc_op_add_when_imm_low: assert property (
        @(posedge clk) disable iff (rst) (en && !imm) |=> (pc_op == 2'b00)
    );

// When not enabled, control_o holds its previous value.
    check_control_hold_when_disabled: assert property (
        @(posedge clk) disable iff (rst) !en |=> (control_o == $past(control_o))
    );

// When not enabled, pc_op holds its previous value.
    check_pc_op_hold_when_disabled: assert property (
        @(posedge clk) disable iff (rst) !en |=> (pc_op == $past(pc_op))
    );

// No reset in RTL; sample combinational behavior on CLK.

    // When SHIFT_DIRECTION==0, output equals DATA shifted left by SHIFT_AMOUNT.
    check_left_shift_function: assert property (
        @(posedge CLK) (SHIFT_DIRECTION == 1'b0) |-> (SHIFTED_DATA == (DATA << SHIFT_AMOUNT))
    );

// When SHIFT_DIRECTION==1, output equals DATA shifted right by SHIFT_AMOUNT.
    check_right_shift_function: assert property (
        @(posedge CLK) (SHIFT_DIRECTION == 1'b1) |-> (SHIFTED_DATA == (DATA >> SHIFT_AMOUNT))
    );

// Left shift by 0 returns the input unchanged.
    check_left_shift_zero: assert property (
        @(posedge CLK) (SHIFT_DIRECTION == 1'b0 && SHIFT_AMOUNT == 3'd0) |-> (SHIFTED_DATA == DATA)
    );

// Right shift by 0 returns the input unchanged.
    check_right_shift_zero: assert property (
        @(posedge CLK) (SHIFT_DIRECTION == 1'b1 && SHIFT_AMOUNT == 3'd0) |-> (SHIFTED_DATA == DATA)
    );

// Left shift by 1 inserts a zero into the LSB.
    check_left_shift_one: assert property (
        @(posedge CLK) (SHIFT_DIRECTION == 1'b0 && SHIFT_AMOUNT == 3'd1) |-> (SHIFTED_DATA == {DATA[6:0], 1'b0})
    );

// Right shift by 1 inserts a zero into the MSB.
    check_right_shift_one: assert property (
        @(posedge CLK) (SHIFT_DIRECTION == 1'b1 && SHIFT_AMOUNT == 3'd1) |-> (SHIFTED_DATA == {1'b0, DATA[7:1]})
    );

// Add opcode drives out to A + B.
    check_add_result: assert property (
        @(posedge clk) (opcode == 3'b000) |-> (out == (A + B))
    );

// Subtract opcode drives out to A - B.
    check_sub_result: assert property (
        @(posedge clk) (opcode == 3'b001) |-> (out == (A - B))
    );

// AND opcode drives out to A & B.
    check_and_result: assert property (
        @(posedge clk) (opcode == 3'b010) |-> (out == (A & B))
    );

// OR opcode drives out to A | B.
    check_or_result: assert property (
        @(posedge clk) (opcode == 3'b011) |-> (out == (A | B))
    );

// XOR opcode drives out to A ^ B.
    check_xor_result: assert property (
        @(posedge clk) (opcode == 3'b100) |-> (out == (A ^ B))
    );

// Shift-left opcode drives out to A << 1.
    check_shift_left_result: assert property (
        @(posedge clk) (opcode == 3'b101) |-> (out == (A << 1))
    );

// Shift-right opcode drives out to A >> 1.
    check_shift_right_result: assert property (
        @(posedge clk) (opcode == 3'b110) |-> (out == (A >> 1))
    );

// NOT opcode drives out to ~A.
    check_not_result: assert property (
        @(posedge clk) (opcode == 3'b111) |-> (out == (~A))
    );

// Zero flag is asserted when out is zero.
    check_zero_flag_set: assert property (
        @(posedge clk) (out == 4'b0000) |-> (zero == 1'b1)
    );

// Zero flag is deasserted when out is non-zero.
    check_zero_flag_clear: assert property (
        @(posedge clk) (out != 4'b0000) |-> (zero == 1'b0)
    );

// Z equals the AND of all four inputs.
    check_function_equivalence: assert property (
        @(posedge clk) Z == (A & B & C & D)
    );

// All inputs high drives Z high.
    check_all_high_drives_high: assert property (
        @(posedge clk) (A & B & C & D) |-> Z
    );

// A low forces Z low.
    check_a_low_forces_low: assert property (
        @(posedge clk) !A |-> !Z
    );

// B low forces Z low.
    check_b_low_forces_low: assert property (
        @(posedge clk) !B |-> !Z
    );

// C low forces Z low.
    check_c_low_forces_low: assert property (
        @(posedge clk) !C |-> !Z
    );

// D low forces Z low.
    check_d_low_forces_low: assert property (
        @(posedge clk) !D |-> !Z
    );

// Z high implies all inputs are high.
    check_high_output_requires_all_high: assert property (
        @(posedge clk) Z |-> (A & B & C & D)
    );

// sum must equal A ^ B.
    check_sum_xor: assert property (
        @(posedge clk) sum == (A ^ B)
    );

// carry_out must equal A & B.
    check_carry_and: assert property (
        @(posedge clk) carry_out == (A & B)
    );

// When both inputs are 0, sum must be 0.
    check_sum_zero_when_both_zero: assert property (
        @(posedge clk) (!A && !B) |-> (sum == 1'b0)
    );

// When A is 0 and B is 1, sum must be 1.
    check_sum_one_when_a_zero_b_one: assert property (
        @(posedge clk) (!A && B) |-> (sum == 1'b1)
    );

// When A is 1 and B is 0, sum must be 1.
    check_sum_one_when_a_one_b_zero: assert property (
        @(posedge clk) (A && !B) |-> (sum == 1'b1)
    );

// When A is 0 and B is 1, carry_out must be 0.
    check_carry_zero_when_a_zero_b_one: assert property (
        @(posedge clk) (!A && B) |-> (carry_out == 1'b0)
    );

// When A is 1 and B is 0, carry_out must be 0.
    check_carry_zero_when_a_one_b_zero: assert property (
        @(posedge clk) (A && !B) |-> (carry_out == 1'b0)
    );

// When both inputs are 1, carry_out must be 1.
    check_carry_one_when_both_one: assert property (
        @(posedge clk) (A && B) |-> (carry_out == 1'b1)
    );

// X matches the implemented OR-then-AND function.
    check_functional_equivalence: assert property (
        @(posedge clk) X == (B1 & (A1 | A2 | A3 | A4))
    );

// B1 low forces X low.
    check_b1_low_forces_x_low: assert property (
        @(posedge clk) !B1 |-> !X
    );

// Any asserted A input with B1 high drives X high.
    check_any_a_with_b1_high_drives_x_high: assert property (
        @(posedge clk) (B1 & (A1 | A2 | A3 | A4)) |-> X
    );

// X high requires B1 to be high.
    check_x_high_requires_b1_high: assert property (
        @(posedge clk) X |-> B1
    );

// X high requires at least one A input to be high.
    check_x_high_requires_any_a_high: assert property (
        @(posedge clk) X |-> (A1 | A2 | A3 | A4)
    );

// With B1 high, X low implies all A inputs are low.
    check_x_low_with_b1_high_requires_all_a_low: assert property (
        @(posedge clk) (B1 & !X) |-> (!A1 & !A2 & !A3 & !A4)
    );

// With B1 high, all A inputs low implies X is low.
    check_all_a_low_with_b1_high_drives_x_low: assert property (
        @(posedge clk) (B1 & !A1 & !A2 & !A3 & !A4) |-> !X
    );

// Reset drives count to zero on the next clock.
    check_reset_clears_count: assert property (
        @(posedge clk) reset |=> (count == 4'b0000)
    );

// When enabled, count increments by one on the next clock.
    check_count_increments_when_enabled: assert property (
        @(posedge clk) disable iff (reset) enable |=> (count == ($past(count) + 4'd1))
    );

// When not enabled, count holds its value on the next clock.
    check_count_holds_when_disabled: assert property (
        @(posedge clk) disable iff (reset) !enable |=> (count == $past(count))
    );

// Count wraps from 15 back to 0 when enabled.
    check_count_wraps_from_max: assert property (
        @(posedge clk) disable iff (reset) (enable && (count == 4'hF)) |=> (count == 4'h0)
    );

// ENCLK is 0 on the first clock after EN is 0.
    check_enclk_zero_after_en_low: assert property (
        @(posedge CLK) !EN |=> (ENCLK == 1'b0)
    );

// ENCLK is 1 when EN is 1 and TE is 1.
    check_enclk_one_when_en_and_te_high: assert property (
        @(posedge CLK) (EN && TE) |=> (ENCLK == 1'b1)
    );

// ENCLK is 0 when EN is 1 and TE is 0.
    check_enclk_zero_when_en_and_te_low: assert property (
        @(posedge CLK) (EN && !TE) |=> (ENCLK == 1'b0)
    );

// S must match the RTL mux equation.
    check_mux_equation: assert property (
        @(posedge clk) S == (ctrl ? D1 : D0)
    );

// When ctrl is 0, S must equal D0.
    check_select_d0: assert property (
        @(posedge clk) !ctrl |-> (S == D0)
    );

// When ctrl is 1, S must equal D1.
    check_select_d1: assert property (
        @(posedge clk) ctrl |-> (S == D1)
    );

// If both data inputs are equal, S must equal that value regardless of ctrl.
    check_equal_inputs_passthrough: assert property (
        @(posedge clk) (D0 == D1) |-> (S == D0)
    );

// o_wk3_7 selects i_mk15to12[31:24] when i_op == i_wf_post_pre.
    check_wk3_7_selects_15to12_when_op_eq_postpre: assert property (
        @(posedge clk) (i_op == i_wf_post_pre) |-> (o_wk3_7 == i_mk15to12[31:24])
    );

// o_wk3_7 selects i_mk3to0[31:24] when i_op != i_wf_post_pre.
    check_wk3_7_selects_3to0_when_op_ne_postpre: assert property (
        @(posedge clk) (i_op != i_wf_post_pre) |-> (o_wk3_7 == i_mk3to0[31:24])
    );

// o_wk2_6 selects i_mk15to12[23:16] when i_op == i_wf_post_pre.
    check_wk2_6_selects_15to12_when_op_eq_postpre: assert property (
        @(posedge clk) (i_op == i_wf_post_pre) |-> (o_wk2_6 == i_mk15to12[23:16])
    );

// o_wk2_6 selects i_mk3to0[23:16] when i_op != i_wf_post_pre.
    check_wk2_6_selects_3to0_when_op_ne_postpre: assert property (
        @(posedge clk) (i_op != i_wf_post_pre) |-> (o_wk2_6 == i_mk3to0[23:16])
    );

// o_wk1_5 selects i_mk15to12[15:8] when i_op == i_wf_post_pre.
    check_wk1_5_selects_15to12_when_op_eq_postpre: assert property (
        @(posedge clk) (i_op == i_wf_post_pre) |-> (o_wk1_5 == i_mk15to12[15:8])
    );

// o_wk1_5 selects i_mk3to0[15:8] when i_op != i_wf_post_pre.
    check_wk1_5_selects_3to0_when_op_ne_postpre: assert property (
        @(posedge clk) (i_op != i_wf_post_pre) |-> (o_wk1_5 == i_mk3to0[15:8])
    );

// o_wk0_4 selects i_mk15to12[7:0] when i_op == i_wf_post_pre.
    check_wk0_4_selects_15to12_when_op_eq_postpre: assert property (
        @(posedge clk) (i_op == i_wf_post_pre) |-> (o_wk0_4 == i_mk15to12[7:0])
    );

// o_wk0_4 selects i_mk3to0[7:0] when i_op != i_wf_post_pre.
    check_wk0_4_selects_3to0_when_op_ne_postpre: assert property (
        @(posedge clk) (i_op != i_wf_post_pre) |-> (o_wk0_4 == i_mk3to0[7:0])
    );

// When SUB is 0, OUT equals A + B.
    check_add_mode_result: assert property (
        @(posedge clk) !SUB |-> (OUT == (A + B))
    );

// When SUB is 1, OUT equals B - A.
    check_sub_mode_result: assert property (
        @(posedge clk) SUB |-> (OUT == (B - A))
    );

// In sub mode, equal inputs produce zero.
    check_sub_equal_inputs_zero: assert property (
        @(posedge clk) (SUB && (A == B)) |-> (OUT == 4'h0)
    );

// In add mode, 0 on B passes A through.
    check_add_b_zero_passthrough: assert property (
        @(posedge clk) (!SUB && (B == 4'h0)) |-> (OUT == A)
    );

// In sub mode, 0 on A passes B through.
    check_sub_a_zero_passthrough: assert property (
        @(posedge clk) (SUB && (A == 4'h0)) |-> (OUT == B)
    );

// Reset clears both registers and the output selector.
    check_reset_clears_state: assert property (
        @(posedge clk) !rst_n |-> ((rat == 8'h00) && (pc == 8'h00) && (m_at == 8'h00))
    );

// When not loading, valid is deasserted on the next cycle.
    check_valid_deasserts_when_not_loading: assert property (
        @(posedge load) !load |=> (valid == 1'b0)
    );

// When not loading, out holds its previous value.
    check_out_holds_when_not_loading: assert property (
        @(posedge load) !load |=> (out == $past(out))
    );

// Load captures data_in on the next cycle.
    check_load_captures_data: assert property (
        @(posedge clk) load |=> (data_out == $past(data_in))
    );

// Without load, the register shifts left and inserts 0 in bit 0.
    check_shift_left_when_not_load: assert property (
        @(posedge clk) !load |=> (data_out == {$past(data_out[2:0]), 1'b0})
    );

// Bit 3 follows bit 2 when not loading.
    check_bit3_follows_bit2: assert property (
        @(posedge clk) !load |=> (data_out[3] == $past(data_out[2]))
    );

// Bit 2 follows bit 1 when not loading.
    check_bit2_follows_bit1: assert property (
        @(posedge clk) !load |=> (data_out[2] == $past(data_out[1]))
    );

// Bit 1 follows bit 0 when not loading.
    check_bit1_follows_bit0: assert property (
        @(posedge clk) !load |=> (data_out[1] == $past(data_out[0]))
    );

// Bit 0 is cleared when not loading.
    check_bit0_is_zero: assert property (
        @(posedge clk) !load |=> (data_out[0] == 1'b0)
    );

// Y matches the implemented NOR-of-AND function.
    check_function_equivalence: assert property (
        @(posedge clk) Y == ~((A1 & A2 & A3) | B1 | C1)
    );

// A high B1 forces Y low.
    check_b1_forces_low: assert property (
        @(posedge clk) B1 |-> !Y
    );

// A high C1 forces Y low.
    check_c1_forces_low: assert property (
        @(posedge clk) C1 |-> !Y
    );

// All three A inputs high force Y low.
    check_a_triplet_forces_low: assert property (
        @(posedge clk) (A1 & A2 & A3) |-> !Y
    );

// With B1 and C1 low, Y equals the inverted A-triplet AND.
    check_a_triplet_dominates_when_others_low: assert property (
        @(posedge clk) (!B1 && !C1) |-> (Y == ~(A1 & A2 & A3))
    );

// With the A-triplet low, Y equals the inverted OR of B1 and C1.
    check_or_term_dominates_when_a_triplet_low: assert property (
        @(posedge clk) !(A1 & A2 & A3) |-> (Y == ~(B1 | C1))
    );

// Reset drives count to zero on the next sampled cycle.
    check_reset_clears_count: assert property (
        @(posedge clk) rst |=> (count == 4'd0)
    );

// When not in reset, count increments by one on the next sampled cycle.
    check_count_increments: assert property (
        @(posedge clk) disable iff (rst) 1'b1 |=> (count == ($past(count) + 4'd1))
    );

// Count wraps from 15 back to 0 when not in reset.
    check_count_wraps: assert property (
        @(posedge clk) disable iff (rst) (count == 4'hF) |=> (count == 4'h0)
    );

// Y matches the implemented NOR/OR/BUF function.
    check_function_equivalence: assert property (
        @(posedge clk) Y == ((~(A1 | A2 | A3)) | (~(B1 | B2)))
    );

// All A inputs low with both B inputs low drive Y high.
    check_all_inputs_low_drive_high: assert property (
        @(posedge clk) (!A1 && !A2 && !A3 && !B1 && !B2) |-> Y
    );

// f4 is the sum of the three sub-module outputs.
    check_total_sum: assert property (
        @(posedge clk) f4_dotnamed == (Boo_ba1 << 1) + (Boo_ba2 + b) + (Boo_ba3 - c)
    );

// When EN is low, Y must be forced low.
    check_en_low_forces_zero: assert property (
        @(posedge clk) (EN == 1'b0) |-> (Y == 1'b0)
    );

// When EN is high and SEL==00, Y equals ABCD[0].
    check_sel00_routes_abcd0: assert property (
        @(posedge clk) (EN == 1'b1) && (SEL == 2'b00) |-> (Y == ABCD[0])
    );

// When EN is high and SEL==01, Y equals ABCD[1].
    check_sel01_routes_abcd1: assert property (
        @(posedge clk) (EN == 1'b1) && (SEL == 2'b01) |-> (Y == ABCD[1])
    );

// When EN is high and SEL==10, Y equals ABCD[2].
    check_sel10_routes_abcd2: assert property (
        @(posedge clk) (EN == 1'b1) && (SEL == 2'b10) |-> (Y == ABCD[2])
    );

// When EN is high and SEL==11, Y equals ABCD[3].
    check_sel11_routes_abcd3: assert property (
        @(posedge clk) (EN == 1'b1) && (SEL == 2'b11) |-> (Y == ABCD[3])
    );

// On reset, count is driven to 0 on the next clock.
    reset_clears_next: assert property (
        @(posedge clk) reset |=> (count == 4'd0)
    );

// When not in reset, count increments by 1 on the next clock.
    count_increments: assert property (
        @(posedge clk) disable iff (reset) 1'b1 |=> (count == ($past(count) + 4'd1))
    );

// When not in reset, count wraps from 15 back to 0.
    count_wraps_from_max: assert property (
        @(posedge clk) disable iff (reset) (count == 4'hF) |=> (count == 4'h0)
    );

// No reset in RTL; assertions are always active.

    // dir=0: out equals in shifted left by shift amount.
    check_left_shift_function: assert property (
        @(posedge CLK) (dir == 1'b0) |-> (out == (in << shift))
    );

// dir=1: out equals in shifted right by shift amount.
    check_right_shift_function: assert property (
        @(posedge CLK) (dir == 1'b1) |-> (out == (in >> shift))
    );

// Shift by 0 returns the input unchanged.
    check_shift_zero_passthrough: assert property (
        @(posedge CLK) (shift == 4'd0) |-> (out == in)
    );

// Left shift by 1: LSB becomes 0, upper bits shift up by 1.
    check_left_shift_by_one: assert property (
        @(posedge CLK) (dir == 1'b0 && shift == 4'd1) |-> (out == {in[14:0], 1'b0})
    );

// Right shift by 1: MSB becomes 0, lower bits shift down by 1.
    check_right_shift_by_one: assert property (
        @(posedge CLK) (dir == 1'b1 && shift == 4'd1) |-> (out == {1'b0, in[15:1]})
    );

// Reset clears count to zero on the next clock.
    check_reset_clears_count: assert property (
        @(posedge clk) rst |=> (count == 32'd0)
    );

// When enabled outside reset, count increments by one.
    check_count_increments_when_enabled: assert property (
        @(posedge clk) disable iff (rst) enable |=> (count == ($past(count) + 32'd1))
    );

// When not enabled outside reset, count holds its value.
    check_count_holds_when_disabled: assert property (
        @(posedge clk) disable iff (rst) !enable |=> (count == $past(count))
    );

// Reset drives reg_0x1F to 0 on the next clock.
    check_reset_clears_next: assert property (
        @(posedge clk) reset |=> (reg_0x1F == 8'h00)
    );

// Reset has priority over write enable when both are asserted.
    check_reset_priority_over_wenb: assert property (
        @(posedge clk) (reset && !wenb) |=> (reg_0x1F == 8'h00)
    );

// With wenb low, next value equals in_data.
    check_write_loads_data: assert property (
        @(posedge clk) disable iff (reset) (!wenb) |=> (reg_0x1F == $past(in_data))
    );

// With wenb high, next value holds its previous value.
    check_hold_when_wenb_high: assert property (
        @(posedge clk) disable iff (reset) wenb |=> (reg_0x1F == $past(reg_0x1F))
    );

// parity_error must equal the XOR reduction of data.
    check_parity_equation: assert property (
        @(posedge clk) parity_error == (^data)
    );

// A zero input must drive parity_error low.
    check_zero_input: assert property (
        @(posedge clk) (data == 8'h00) |-> (parity_error == 1'b0)
    );

// An input with even parity must drive parity_error low.
    check_even_parity: assert property (
        @(posedge clk) (^data == 1'b0) |-> (parity_error == 1'b0)
    );

// An input with odd parity must drive parity_error high.
    check_odd_parity: assert property (
        @(posedge clk) (^data == 1'b1) |-> (parity_error == 1'b1)
    );

// Reset drives Q to zero on the next sampled cycle.
    check_reset_clears_q: assert property (
        @(posedge clk) reset |=> (Q == 4'b0000)
    );

// With load high, Q captures data_in on the next sampled cycle.
    check_load_captures_data: assert property (
        @(posedge clk) disable iff (reset) load |=> (Q == $past(data_in))
    );

// With load low, Q holds its previous value on the next sampled cycle.
    check_hold_when_load_low: assert property (
        @(posedge clk) disable iff (reset) !load |=> (Q == $past(Q))
    );

// SUM equals A ^ B ^ CI.
    check_sum_function: assert property (
        @(posedge CLK) SUM == (A ^ B ^ CI)
    );

// COUT equals (A & B) | (B & CI) | (CI & A).
    check_cout_function: assert property (
        @(posedge CLK) COUT == ((A & B) | (B & CI) | (CI & A))
    );

// When A and B are equal, SUM equals CI.
    check_sum_when_ab_equal: assert property (
        @(posedge CLK) (A == B) |-> (SUM == CI)
    );

// When A and B differ, SUM equals ~CI.
    check_sum_when_ab_differs: assert property (
        @(posedge CLK) (A != B) |-> (SUM == ~CI)
    );

// When A and B differ, COUT equals CI.
    check_cout_when_ab_differs: assert property (
        @(posedge CLK) (A != B) |-> (COUT == CI)
    );

// When CI is 0, SUM equals A ^ B.
    check_sum_when_ci_zero: assert property (
        @(posedge CLK) (CI == 1'b0) |-> (SUM == (A ^ B))
    );

// When CI is 0, COUT equals A & B.
    check_cout_when_ci_zero: assert property (
        @(posedge CLK) (CI == 1'b0) |-> (COUT == (A & B))
    );

// When CI is 1, SUM equals ~(A ^ B).
    check_sum_when_ci_one: assert property (
        @(posedge CLK) (CI == 1'b1) |-> (SUM == ~(A ^ B))
    );

// When CI is 1, COUT equals A | B.
    check_cout_when_ci_one: assert property (
        @(posedge CLK) (CI == 1'b1) |-> (COUT == (A | B))
    );

// Load captures input_data on the next cycle.
    check_load_captures_input: assert property (
        @(posedge clk) load |=> (Q == $past(input_data))
    );

// When not loading, Q increments by one when up_down is high.
    check_increment_when_up: assert property (
        @(posedge clk) (!load && up_down) |=> (Q == ($past(Q) + 4'd1))
    );

// When not loading, Q decrements by one when up_down is low.
    check_decrement_when_down: assert property (
        @(posedge clk) (!load && !up_down) |=> (Q == ($past(Q) - 4'd1))
    );

// Incrementing from 4'hF wraps Q to 4'h0.
    check_increment_wrap: assert property (
        @(posedge clk) (!load && up_down && (Q == 4'hF)) |=> (Q == 4'h0)
    );

// Decrementing from 4'h0 wraps Q to 4'hF.
    check_decrement_wrap: assert property (
        @(posedge clk) (!load && !up_down && (Q == 4'h0)) |=> (Q == 4'hF)
    );

// Both A inputs low and at least one B input high drive X high.
    check_inputs_enable_x: assert property (
        @(posedge clk) ((~A1_N) & (~A2_N) & (B1 | B2)) |-> X
    );

// C must equal the bitwise AND of A and B.
    check_output_matches_and: assert property (
        @(posedge clk) C == (A & B)
    );

// A low bit forces the corresponding C bit low.
    check_a_low_sets_c_low: assert property (
        @(posedge clk) (A[7] == 1'b0) |-> (C[7] == 1'b0)
    );

// B low bit forces the corresponding C bit low.
    check_b_low_sets_c_low: assert property (
        @(posedge clk) (B[7] == 1'b0) |-> (C[7] == 1'b0)
    );

// A high C bit requires both A and B high at that bit.
    check_c_high_requires_a_and_b_high: assert property (
        @(posedge clk) (C[7] == 1'b1) |-> ((A[7] == 1'b1) && (B[7] == 1'b1))
    );

// Coin high forces change high and all products low.
    check_coin_forces_change: assert property (
        @(posedge clk) coin |-> (change == 1'b1) && (product1 == 1'b0) && (product2 == 1'b0) && (product3 == 1'b0)
    );

// No coin with button1 selects product1 and no change.
    check_button1_selects_product1: assert property (
        @(posedge clk) (!coin && button1 && !button2 && !button3) |-> (change == 1'b0) && (product1 == 1'b1) && (product2 == 1'b0) && (product3 == 1'b0)
    );

// No coin with button2 selects product2 and no change.
    check_button2_selects_product2: assert property (
        @(posedge clk) (!coin && !button1 && button2 && !button3) |-> (change == 1'b0) && (product1 == 1'b0) && (product2 == 1'b1) && (product3 == 1'b0)
    );

// No coin with button3 selects product3 and no change.
    check_button3_selects_product3: assert property (
        @(posedge clk) (!coin && !button1 && !button2 && button3) |-> (change == 1'b0) && (product1 == 1'b0) && (product2 == 1'b0) && (product3 == 1'b1)
    );

// No coin with no buttons selected drives no products and no change.
    check_no_buttons_selects_none: assert property (
        @(posedge clk) (!coin && !button1 && !button2 && !button3) |-> (change == 1'b0) && (product1 == 1'b0) && (product2 == 1'b0) && (product3 == 1'b0)
    );

// With coin and any button selected, change is high and products are low.
    check_coin_with_any_button_forces_change: assert property (
        @(posedge clk) (coin && (button1 || button2 || button3)) |-> (change == 1'b1) && (product1 == 1'b0) && (product2 == 1'b0) && (product3 == 1'b0)
    );

// With coin and no button selected, change is high and products are low.
    check_coin_without_buttons_forces_change: assert property (
        @(posedge clk) (coin && !button1 && !button2 && !button3) |-> (change == 1'b1) && (product1 == 1'b0) && (product2 == 1'b0) && (product3 == 1'b0)
    );

// Reset low forces COUNT to zero.
    check_reset_clears_count: assert property (
        @(posedge clk) !RST |-> (COUNT == 4'b0000)
    );

// When enabled, COUNT increments by one on the next clock.
    check_count_increments_when_enabled: assert property (
        @(posedge clk) disable iff (!RST)
        EN |=> (COUNT == ($past(COUNT) + 4'd1))
    );

// When disabled, COUNT holds its previous value.
    check_count_holds_when_disabled: assert property (
        @(posedge clk) disable iff (!RST)
        !EN |=> (COUNT == $past(COUNT))
    );

// COUNT wraps from 15 back to 0 when enabled.
    check_count_wraps_from_max: assert property (
        @(posedge clk) disable iff (!RST)
        (EN && (COUNT == 4'hF)) |=> (COUNT == 4'h0)
    );

// Address 0000 with Q low drives ce_expnd_i_5 low.
    check_addr_0000_q0_low: assert property (
        @(posedge clk) (bus2ip_addr_i_reg == 5'd0 && Q == 1'b0) |-> (ce_expnd_i_5 == 1'b0)
    );

// Address 0000 with Q high drives ce_expnd_i_5 low.
    check_addr_0000_q1_low: assert property (
        @(posedge clk) (bus2ip_addr_i_reg == 5'd0 && Q == 1'b1) |-> (ce_expnd_i_5 == 1'b0)
    );

// Address 0001 drives ce_expnd_i_5 low.
    check_addr_0001_low: assert property (
        @(posedge clk) (bus2ip_addr_i_reg == 5'd1) |-> (ce_expnd_i_5 == 1'b0)
    );

// Address 0010 drives ce_expnd_i_5 low.
    check_addr_0010_low: assert property (
        @(posedge clk) (bus2ip_addr_i_reg == 5'd2) |-> (ce_expnd_i_5 == 1'b0)
    );

// Address 0011 drives ce_expnd_i_5 low.
    check_addr_0011_low: assert property (
        @(posedge clk) (bus2ip_addr_i_reg == 5'd3) |-> (ce_expnd_i_5 == 1'b0)
    );

// Address 0101 drives ce_expnd_i_5 low.
    check_addr_0101_low: assert property (
        @(posedge clk) (bus2ip_addr_i_reg == 5'd5) |-> (ce_expnd_i_5 == 1'b0)
    );

// Address 0110 drives ce_expnd_i_5 low.
    check_addr_0110_low: assert property (
        @(posedge clk) (bus2ip_addr_i_reg == 5'd6) |-> (ce_expnd_i_5 == 1'b0)
    );

// Address 0111 drives ce_expnd_i_5 low.
    check_addr_0111_low: assert property (
        @(posedge clk) (bus2ip_addr_i_reg == 5'd7) |-> (ce_expnd_i_5 == 1'b0)
    );

// Address 1001 drives ce_expnd_i_5 low.
    check_addr_1001_low: assert property (
        @(posedge clk) (bus2ip_addr_i_reg == 5'd9) |-> (ce_expnd_i_5 == 1'b0)
    );

// Address 1010 drives ce_expnd_i_5 low.
    check_addr_1010_low: assert property (
        @(posedge clk) (bus2ip_addr_i_reg == 5'd10) |-> (ce_expnd_i_5 == 1'b0)
    );

// Address 1011 drives ce_expnd_i_5 low.
    check_addr_1011_low: assert property (
        @(posedge clk) (bus2ip_addr_i_reg == 5'd11) |-> (ce_expnd_i_5 == 1'b0)
    );

// Address 1101 drives ce_expnd_i_5 low.
    check_addr_1101_low: assert property (
        @(posedge clk) (bus2ip_addr_i_reg == 5'd13) |-> (ce_expnd_i_5 == 1'b0)
    );

// Address 1110 drives ce_expnd_i_5 low.
    check_addr_1110_low: assert property (
        @(posedge clk) (bus2ip_addr_i_reg == 5'd14) |-> (ce_expnd_i_5 == 1'b0)
    );

// Address 1111 drives ce_expnd_i_5 low.
    check_addr_1111_low: assert property (
        @(posedge clk) (bus2ip_addr_i_reg == 5'd15) |-> (ce_expnd_i_5 == 1'b0)
    );

// Y must equal the AND of all five inputs.
    check_y_matches_and_function: assert property (
        @(posedge clk) Y == (A1 & A2 & A3 & B1 & C1)
    );

// A low on A1 forces Y low.
    check_a1_low_forces_y_low: assert property (
        @(posedge clk) !A1 |-> !Y
    );

// A low on A2 forces Y low.
    check_a2_low_forces_y_low: assert property (
        @(posedge clk) !A2 |-> !Y
    );

// A low on A3 forces Y low.
    check_a3_low_forces_y_low: assert property (
        @(posedge clk) !A3 |-> !Y
    );

// A low on B1 forces Y low.
    check_b1_low_forces_y_low: assert property (
        @(posedge clk) !B1 |-> !Y
    );

// A low on C1 forces Y low.
    check_c1_low_forces_y_low: assert property (
        @(posedge clk) !C1 |-> !Y
    );

// All five high inputs drive Y high.
    check_all_high_drives_y_high: assert property (
        @(posedge clk) (A1 & A2 & A3 & B1 & C1) |-> Y
    );

// mod 0x01 only occurs for addresses with upper bits 10xxxxxx.
    check_mod_01_mapping: assert property (
        @(posedge clk)
        (mod == 8'h01) == (addr[31:24] == 8'h10)
    );

// mod 0x02 only occurs for addresses with upper bits f00xxx.
    check_mod_02_mapping: assert property (
        @(posedge clk)
        (mod == 8'h02) == (addr[31:20] == 12'hf00)
    );

// mod 0x03 only occurs for addresses with upper bits f01xxx.
    check_mod_03_mapping: assert property (
        @(posedge clk)
        (mod == 8'h03) == (addr[31:20] == 12'hf01)
    );

// mod 0x04 only occurs for addresses with upper bits f02xxx.
    check_mod_04_mapping: assert property (
        @(posedge clk)
        (mod == 8'h04) == (addr[31:20] == 12'hf02)
    );

// mod 0x05 only occurs for addresses with upper bits f03xxx.
    check_mod_05_mapping: assert property (
        @(posedge clk)
        (mod == 8'h05) == (addr[31:20] == 12'hf03)
    );

// mod 0x06 only occurs for addresses with upper bits f04xxx.
    check_mod_06_mapping: assert property (
        @(posedge clk)
        (mod == 8'h06) == (addr[31:20] == 12'hf04)
    );

// mod 0x07 only occurs for addresses with upper bits f05xxx.
    check_mod_07_mapping: assert property (
        @(posedge clk)
        (mod == 8'h07) == (addr[31:20] == 12'hf05)
    );

// mod 0x08 only occurs for addresses with upper bits f06xxx.
    check_mod_08_mapping: assert property (
        @(posedge clk)
        (mod == 8'h08) == (addr[31:20] == 12'hf06)
    );

// mod 0x0a only occurs for addresses with upper bits f07xxx.
    check_mod_0a_mapping: assert property (
        @(posedge clk)
        (mod == 8'h0a) == (addr[31:20] == 12'hf07)
    );

// mod 0x0b only occurs for addresses with upper bits f08xxx.
    check_mod_0b_mapping: assert property (
        @(posedge clk)
        (mod == 8'h0b) == (addr[31:20] == 12'hf08)
    );

// mod 0x09 only occurs for addresses with upper bits f0axxx.
    check_mod_09_mapping: assert property (
        @(posedge clk)
        (mod == 8'h09) == (addr[31:20] == 12'hf0a)
    );

// eff_addr must match the RTL's full conditional expression.
    check_eff_addr_full_mapping: assert property (
        @(posedge clk)
        eff_addr == ((mod == 8'h01) ? {8'h00, addr[23:0]} : {12'h000, addr[19:0]})
    );

// For mod 0x01, eff_addr must have upper bits 00 and lower 24 bits of addr.
    check_eff_addr_mod_01: assert property (
        @(posedge clk)
        (mod == 8'h01) |-> (eff_addr == {8'h00, addr[23:0]})
    );

// For all other mods, eff_addr must have upper bits 000 and lower 20 bits of addr.
    check_eff_addr_other_mods: assert property (
        @(posedge clk)
        (mod != 8'h01) |-> (eff_addr == {12'h000, addr[19:0]})
    );

// X matches the RTL combinational equation.
    check_function_equivalence: assert property (
        @(posedge clk) X == ((A1 & A2 & ~B1_N) | (~A1 & (A2 | B1_N)))
    );

// When A1 and A2 are both high and B1_N is low, X must be high.
    check_select_high: assert property (
        @(posedge clk) (A1 && A2 && !B1_N) |-> X
    );

// When A1 is high and A2 is low, X must be low.
    check_a1_high_a2_low_forces_low: assert property (
        @(posedge clk) (A1 && !A2) |-> !X
    );

// A high on TE_B must drive Z low.
    check_te_b_high_forces_z_low: assert property (
        @(posedge clk) TE_B |-> (Z == 1'b0)
    );

// ECK must match the RTL combinational equation.
    check_function_equivalence: assert property (
        @(posedge CK) ECK == ((E & SE) | (!E & CK))
    );

// When E is low, ECK must follow CK.
    check_eck_follows_ck_when_e_low: assert property (
        @(posedge CK) !E |-> (ECK == CK)
    );

// When E is high, ECK must follow SE.
    check_eck_follows_se_when_e_high: assert property (
        @(posedge CK) E |-> (ECK == SE)
    );

// A low SE with low E must drive ECK low.
    check_se_low_drives_eck_low_when_e_low: assert property (
        @(posedge CK) (!SE && !E) |-> (ECK == 1'b0)
    );

// A high E with low SE must drive ECK low.
    check_e_high_se_low_drives_eck_low: assert property (
        @(posedge CK) (E && !SE) |-> (ECK == 1'b0)
    );

// A high E with high SE must drive ECK high.
    check_e_high_se_high_drives_eck_high: assert property (
        @(posedge CK) (E && SE) |-> (ECK == 1'b1)
    );

// No item selected forces vend low.
    check_no_item_selected_forces_vend_low: assert property (
        @(posedge clk) (item == 2'b00) |-> (vend == 1'b0)
    );

// Item A requires 5 cents and dispense.
    check_item_a_requires_5c_and_dispense: assert property (
        @(posedge clk) (item == 2'b01) |-> ((coin >= 2'b01) && dispense) == vend
    );

// Item B requires 10 cents and dispense.
    check_item_b_requires_10c_and_dispense: assert property (
        @(posedge clk) (item == 2'b10) |-> ((coin >= 2'b10) && dispense) == vend
    );

// Item C requires 15 cents and dispense.
    check_item_c_requires_15c_and_dispense: assert property (
        @(posedge clk) (item == 2'b11) |-> ((coin >= 2'b11) && dispense) == vend
    );

// vend high implies the selected item's cost and dispense are met.
    check_vend_high_implies_required_inputs: assert property (
        @(posedge clk) vend |-> ((item != 2'b00) && (coin >= item) && dispense)
    );

// With item A selected, 5 cents and dispense together drive vend high.
    check_item_a_grants_vend_when_5c_and_dispense: assert property (
        @(posedge clk) (item == 2'b01 && coin == 2'b01 && dispense) |-> (vend == 1'b1)
    );

// With item B selected, 10 cents and dispense together drive vend high.
    check_item_b_grants_vend_when_10c_and_dispense: assert property (
        @(posedge clk) (item == 2'b10 && coin == 2'b10 && dispense) |-> (vend == 1'b1)
    );

// With item C selected, 15 cents and dispense together drive vend high.
    check_item_c_grants_vend_when_15c_and_dispense: assert property (
        @(posedge clk) (item == 2'b11 && coin == 2'b11 && dispense) |-> (vend == 1'b1)
    );

// select 0000 routes data_i00 to data_o.
    check_select_0000_routes_data_i00: assert property (
        @(posedge clk) (select == 4'b0000) |-> (data_o == data_i00)
    );

// select 0001 routes data_i01 to data_o.
    check_select_0001_routes_data_i01: assert property (
        @(posedge clk) (select == 4'b0001) |-> (data_o == data_i01)
    );

// select 0010 routes data_i02 to data_o.
    check_select_0010_routes_data_i02: assert property (
        @(posedge clk) (select == 4'b0010) |-> (data_o == data_i02)
    );

// select 0011 routes data_i03 to data_o.
    check_select_0011_routes_data_i03: assert property (
        @(posedge clk) (select == 4'b0011) |-> (data_o == data_i03)
    );

// select 0100 routes data_i04 to data_o.
    check_select_0100_routes_data_i04: assert property (
        @(posedge clk) (select == 4'b0100) |-> (data_o == data_i04)
    );

// select 0101 routes data_i05 to data_o.
    check_select_0101_routes_data_i05: assert property (
        @(posedge clk) (select == 4'b0101) |-> (data_o == data_i05)
    );

// select 0110 routes data_i06 to data_o.
    check_select_0110_routes_data_i06: assert property (
        @(posedge clk) (select == 4'b0110) |-> (data_o == data_i06)
    );

// select 0111 routes data_i07 to data_o.
    check_select_0111_routes_data_i07: assert property (
        @(posedge clk) (select == 4'b0111) |-> (data_o == data_i07)
    );

// select 1000 routes data_i08 to data_o.
    check_select_1000_routes_data_i08: assert property (
        @(posedge clk) (select == 4'b1000) |-> (data_o == data_i08)
    );

// select 1001 routes data_i09 to data_o.
    check_select_1001_routes_data_i09: assert property (
        @(posedge clk) (select == 4'b1001) |-> (data_o == data_i09)
    );

// select 1010 routes data_i10 to data_o.
    check_select_1010_routes_data_i10: assert property (
        @(posedge clk) (select == 4'b1010) |-> (data_o == data_i10)
    );

// select 1011 routes data_i11 to data_o.
    check_select_1011_routes_data_i11: assert property (
        @(posedge clk) (select == 4'b1011) |-> (data_o == data_i11)
    );

// select 1100 routes data_i12 to data_o.
    check_select_1100_routes_data_i12: assert property (
        @(posedge clk) (select == 4'b1100) |-> (data_o == data_i12)
    );

// select 1101 routes data_i13 to data_o.
    check_select_1101_routes_data_i13: assert property (
        @(posedge clk) (select == 4'b1101) |-> (data_o == data_i13)
    );

// select 1110 routes data_i14 to data_o.
    check_select_1110_routes_data_i14: assert property (
        @(posedge clk) (select == 4'b1110) |-> (data_o == data_i14)
    );

// select 1111 routes data_i15 to data_o.
    check_select_1111_routes_data_i15: assert property (
        @(posedge clk) (select == 4'b1111) |-> (data_o == data_i15)
    );

// clk_gated must be low when clk is low.
    check_clk_low_forces_gated_low: assert property (
        @(posedge clk) (clk == 1'b0) |-> (clk_gated == 1'b0)
    );

// clk_gated must be low when active is low.
    check_active_low_forces_gated_low: assert property (
        @(posedge clk) (active == 1'b0) |-> (clk_gated == 1'b0)
    );

// clk_gated must be high when both clk and active are high.
    check_both_high_sets_gated_high: assert property (
        @(posedge clk) (clk == 1'b1 && active == 1'b1) |-> (clk_gated == 1'b1)
    );

// A high clk_gated implies both clk and active are high.
    check_gated_high_requires_both_high: assert property (
        @(posedge clk) (clk_gated == 1'b1) |-> (clk == 1'b1 && active == 1'b1)
    );

// Falling active with clk high must drive clk_gated low.
    check_active_fall_clears_gated_when_clk_high: assert property (
        @(posedge clk) (active == 1'b0 && $fell(active)) |-> (clk_gated == 1'b0)
    );

// phy0 MDC mirrors mdio_mdc.
    check_phy0_mdc_passthrough: assert property (
        @(posedge mdio_mdc) phy0_mdc == mdio_mdc
    );

// phy0 MDIO T mirrors mdio_t.
    check_phy0_mdio_t_passthrough: assert property (
        @(posedge mdio_mdc) phy0_mdio_t == mdio_t
    );

// phy0 MDIO O mirrors mdio_o.
    check_phy0_mdio_o_passthrough: assert property (
        @(posedge mdio_mdc) phy0_mdio_o == mdio_o
    );

// phy1 MDC mirrors mdio_mdc.
    check_phy1_mdc_passthrough: assert property (
        @(posedge mdio_mdc) phy1_mdc == mdio_mdc
    );

// phy1 MDIO T mirrors mdio_t.
    check_phy1_mdio_t_passthrough: assert property (
        @(posedge mdio_mdc) phy1_mdio_t == mdio_t
    );

// phy1 MDIO O mirrors mdio_o.
    check_phy1_mdio_o_passthrough: assert property (
        @(posedge mdio_mdc) phy1_mdio_o == mdio_o
    );

// mdio_i is the AND of the two PHY MDIO inputs.
    check_mdio_i_is_and_of_phy_inputs: assert property (
        @(posedge mdio_mdc) mdio_i == (phy0_mdio_i & phy1_mdio_i)
    );

// A high mdio_i requires both PHY inputs to be high.
    check_mdio_i_high_requires_both_phis_high: assert property (
        @(posedge mdio_mdc) mdio_i |-> (phy0_mdio_i && phy1_mdio_i)
    );

// Both PHY inputs high drives mdio_i high.
    check_both_phis_high_drive_mdio_i_high: assert property (
        @(posedge mdio_mdc) (phy0_mdio_i && phy1_mdio_i) |-> mdio_i
    );

// A1_N low forces OUT low.
    check_a1n_low_forces_out_low: assert property (
        @(posedge clk) !A1_N |-> !OUT
    );

// A2_N low forces OUT low.
    check_a2n_low_forces_out_low: assert property (
        @(posedge clk) !A2_N |-> !OUT
    );

// B1 low forces OUT low.
    check_b1_low_forces_out_low: assert property (
        @(posedge clk) !B1 |-> !OUT
    );

// B2 low forces OUT low.
    check_b2_low_forces_out_low: assert property (
        @(posedge clk) !B2 |-> !OUT
    );

// All inputs high drive OUT high.
    check_all_inputs_high_drive_out_high: assert property (
        @(posedge clk) (A1_N & A2_N & B1 & B2) |-> OUT
    );

// out1 equals the 9-input AND of all inputs.
    check_out_matches_and9: assert property (
        @(posedge clk) out1 == (in1 & in2 & in3 & in4 & in5 & in6 & in7 & in8 & in9)
    );

// If any input is 0, out1 must be 0.
    check_zero_if_any_input_zero: assert property (
        @(posedge clk) ((in1 == 1'b0) || (in2 == 1'b0) || (in3 == 1'b0) || (in4 == 1'b0) || (in5 == 1'b0) || (in6 == 1'b0) || (in7 == 1'b0) || (in8 == 1'b0) || (in9 == 1'b0)) |-> (out1 == 1'b0)
    );

// If all inputs are 1, out1 must be 1.
    check_one_if_all_inputs_one: assert property (
        @(posedge clk) (in1 && in2 && in3 && in4 && in5 && in6 && in7 && in8 && in9) |-> (out1 == 1'b1)
    );

// If out1 is 1, then all inputs must be 1.
    check_all_inputs_one_if_out_one: assert property (
        @(posedge clk) (out1 == 1'b1) |-> (in1 && in2 && in3 && in4 && in5 && in6 && in7 && in8 && in9)
    );

// If out1 is 0, then at least one input must be 0.
    check_any_input_zero_if_out_zero: assert property (
        @(posedge clk) (out1 == 1'b0) |-> ((in1 == 1'b0) || (in2 == 1'b0) || (in3 == 1'b0) || (in4 == 1'b0) || (in5 == 1'b0) || (in6 == 1'b0) || (in7 == 1'b0) || (in8 == 1'b0) || (in9 == 1'b0))
    );

// Active-low reset clears all port addresses to their default values.
    check_reset_defaults: assert property (
        @(posedge clk) !reset_b |-> (address_port_0 == 8'h00 &&
                                    address_port_1 == 8'h01 &&
                                    address_port_2 == 8'h02 &&
                                    address_port_3 == 8'h03)
    );

// Read address 0 returns port 0's value.
    check_read_addr_0: assert property (
        @(posedge clk) disable iff (!reset_b)
        (mem_addr == 2'd0) |-> (mem_rdata == address_port_0)
    );

// Read address 1 returns port 1's value.
    check_read_addr_1: assert property (
        @(posedge clk) disable iff (!reset_b)
        (mem_addr == 2'd1) |-> (mem_rdata == address_port_1)
    );

// Read address 2 returns port 2's value.
    check_read_addr_2: assert property (
        @(posedge clk) disable iff (!reset_b)
        (mem_addr == 2'd2) |-> (mem_rdata == address_port_2)
    );

// Read address 3 returns port 3's value.
    check_read_addr_3: assert property (
        @(posedge clk) disable iff (!reset_b)
        (mem_addr == 2'd3) |-> (mem_rdata == address_port_3)
    );

// Write to address 0 updates port 0 on the next cycle.
    check_write_addr_0: assert property (
        @(posedge clk) disable iff (!reset_b)
        (mem_en && mem_rd_wr && (mem_addr == 2'd0)) |=> (address_port_0 == $past(mem_wdata))
    );

// Write to address 1 updates port 1 on the next cycle.
    check_write_addr_1: assert property (
        @(posedge clk) disable iff (!reset_b)
        (mem_en && mem_rd_wr && (mem_addr == 2'd1)) |=> (address_port_1 == $past(mem_wdata))
    );

// Write to address 2 updates port 2 on the next cycle.
    check_write_addr_2: assert property (
        @(posedge clk) disable iff (!reset_b)
        (mem_en && mem_rd_wr && (mem_addr == 2'd2)) |=> (address_port_2 == $past(mem_wdata))
    );

// Write to address 3 updates port 3 on the next cycle.
    check_write_addr_3: assert property (
        @(posedge clk) disable iff (!reset_b)
        (mem_en && mem_rd_wr && (mem_addr == 2'd3)) |=> (address_port_3 == $past(mem_wdata))
    );

// Reset clears the output on the next clock.
    check_reset_clears_output: assert property (
        @(posedge clk) reset |=> (data_out == 8'h00)
    );

// With enable low, the next output passes the current input through.
    check_passthrough_when_disabled: assert property (
        @(posedge clk) disable iff (reset)
        !enable |=> (data_out == $past(data_in))
    );

// Clock: clk (posedge). Reset: rst active-low, asynchronous.
    // Behavior: 4-bit up-counter with async reset; count=0 on reset, else count+1.

    // When reset is LOW at a clock edge, count must be 0 on the next cycle.
    check_reset_forces_zero_next: assert property (
        @(posedge clk) !rst |=> (count == 4'd0)
    );

// If reset is LOW in consecutive cycles, count must be 0 in the current cycle.
    check_reset_holds_zero: assert property (
        @(posedge clk) (!rst && $past(!rst)) |-> (count == 4'd0)
    );

// If reset is LOW in the current cycle, next cycle's count is 0 (synchronous update).
    check_next_cycle_zero_after_reset: assert property (
        @(posedge clk) !rst |=> (count == 4'd0)
    );

// If reset is HIGH and count is 0, next cycle's count is 1 (synchronous update).
    check_count_increments_from_zero: assert property (
        @(posedge clk) disable iff (!rst) (count == 4'd0) |=> (count == 4'd1)
    );

// If reset is HIGH and count is 15, next cycle's count is 0 (synchronous wrap).
    check_count_wraps_from_max: assert property (
        @(posedge clk) disable iff (!rst) (count == 4'hF) |=> (count == 4'd0)
    );

// If reset is HIGH and count is not 0 or 15, next cycle's count is +1 (no wrap).
    check_count_increments_non_edge_cases: assert property (
        @(posedge clk) disable iff (!rst) (count != 4'd0 && count != 4'hF) |=> (count == $past(count) + 4'd1)
    );

// When disabled, the output must be zero.
    check_disabled_zero: assert property (
        @(posedge clk) !en |-> (out == 4'b0000)
    );

// When enabled and sel==00, out equals in0.
    check_sel00_enabled: assert property (
        @(posedge clk) en && (sel == 2'b00) |-> (out == in0)
    );

// When enabled and sel==01, out equals in1.
    check_sel01_enabled: assert property (
        @(posedge clk) en && (sel == 2'b01) |-> (out == in1)
    );

// When enabled and sel==10, out equals in2.
    check_sel10_enabled: assert property (
        @(posedge clk) en && (sel == 2'b10) |-> (out == in2)
    );

// When enabled and sel==11, out equals in3.
    check_sel11_enabled: assert property (
        @(posedge clk) en && (sel == 2'b11) |-> (out == in3)
    );

// Y matches the implemented OR-then-NAND function.
    check_function_equivalence: assert property (
        @(posedge clk) Y == ~(C1 & (A1 | A2) & B1)
    );

// With C1 and B1 low, Y is high.
    check_c1_b1_low_gives_high: assert property (
        @(posedge clk) (!C1 && !B1) |-> Y
    );

// With B1 and A1 low, Y is high.
    check_b1_a1_low_gives_high: assert property (
        @(posedge clk) (!B1 && !A1) |-> Y
    );

// With B1 and A2 low, Y is high.
    check_b1_a2_low_gives_high: assert property (
        @(posedge clk) (!B1 && !A2) |-> Y
    );

// With all three active inputs high, Y is low.
    check_all_active_inputs_low: assert property (
        @(posedge clk) (C1 && B1 && (A1 || A2)) |-> !Y
    );

// Reset drives q and carry low on the next clock.
    check_reset_clears_outputs: assert property (
        @(posedge clk) rst |=> (q == 4'b0000) && (carry == 1'b0)
    );

// Up counter increments q when not at max.
    check_up_increment: assert property (
        @(posedge clk) disable iff (rst)
        (up_down == 1'b0) && (q != 4'b1111) |=> (q == ($past(q) + 4'b0001)) && (carry == 1'b0)
    );

// Up counter wraps to zero when at max.
    check_up_wrap: assert property (
        @(posedge clk) disable iff (rst)
        (up_down == 1'b0) && (q == 4'b1111) |=> (q == 4'b0000) && (carry == 1'b1)
    );

// Down counter decrements q when not at zero.
    check_down_decrement: assert property (
        @(posedge clk) disable iff (rst)
        (up_down == 1'b1) && (q != 4'b0000) |=> (q == ($past(q) - 4'b0001)) && (carry == 1'b0)
    );

// Down counter wraps to max when at zero.
    check_down_wrap: assert property (
        @(posedge clk) disable iff (rst)
        (up_down == 1'b1) && (q == 4'b0000) |=> (q == 4'b1111) && (carry == 1'b1)
    );

// Active-low reset clears the counter to zero.
    check_reset_clears_count: assert property (
        @(posedge clk) !rst |-> (count == 4'b0000)
    );

// A load cycle captures data into the counter.
    check_load_captures_data: assert property (
        @(posedge clk) disable iff (!rst)
        load |=> (count == $past(data))
    );

// Without load, the counter increments by one on the next cycle.
    check_increment_when_not_loading: assert property (
        @(posedge clk) disable iff (!rst)
        !load |=> (count == ($past(count) + 4'd1))
    );

// Incrementing from 4'hF wraps the counter to zero.
    check_increment_wraps_from_max: assert property (
        @(posedge clk) disable iff (!rst)
        (!load && (count == 4'hF)) |=> (count == 4'h0)
    );

// Sector 1 maps to 000.
    check_sector1_maps_to_000: assert property (
        @(posedge clk) (sector == 3'd1) |-> (flash_sector == 3'b000)
    );

// Sector 2 maps to 001.
    check_sector2_maps_to_001: assert property (
        @(posedge clk) (sector == 3'd2) |-> (flash_sector == 3'b001)
    );

// Sector 3 maps to 010.
    check_sector3_maps_to_010: assert property (
        @(posedge clk) (sector == 3'd3) |-> (flash_sector == 3'b010)
    );

// Sector 4 maps to 011.
    check_sector4_maps_to_011: assert property (
        @(posedge clk) (sector == 3'd4) |-> (flash_sector == 3'b011)
    );

// Sector 5 maps to 100.
    check_sector5_maps_to_100: assert property (
        @(posedge clk) (sector == 3'd5) |-> (flash_sector == 3'b100)
    );

// Invalid sector IDs (6..7) map to 000.
    check_invalid_sectors_map_to_000: assert property (
        @(posedge clk) (sector >= 3'd6) |-> (flash_sector == 3'b000)
    );

// Output is always one of the five encoded values.
    check_output_encoding_legal: assert property (
        @(posedge clk) flash_sector inside {3'b000, 3'b001, 3'b010, 3'b011, 3'b100}
    );

// Clock: clk (posedge). Reset: rst_n active-low, asynchronous.
    // Behavior: 16-bit up-counter; synchronous reset clears to 0; else increments by 1.

    // On any cycle with rst_n LOW, count must be 0 on the next cycle.
    check_reset_clears_next: assert property (
        @(posedge clk) !rst_n |=> (count == 16'h0000)
    );

// If rst_n is LOW in consecutive cycles, count is 0 in the current cycle.
    check_reset_holds_zero: assert property (
        @(posedge clk) (!rst_n && $past(!rst_n)) |-> (count == 16'h0000)
    );

// Y matches the implemented NOR/NOT/AND logic.
    check_functional_equivalence: assert property (
        @(posedge clk) Y == ~((~B1_N) | (A1 & A2))
    );

// A low B1_N forces Y low.
    check_b1n_low_forces_y_low: assert property (
        @(posedge clk) (B1_N == 1'b0) |-> (Y == 1'b0)
    );

// A high A1 and A2 force Y low.
    check_a1_a2_high_force_y_low: assert property (
        @(posedge clk) ((A1 == 1'b1) && (A2 == 1'b1)) |-> (Y == 1'b0)
    );

// A low A1 with B1_N high forces Y high.
    check_a1_low_with_b1n_high_forces_y_high: assert property (
        @(posedge clk) ((A1 == 1'b0) && (B1_N == 1'b1)) |-> (Y == 1'b1)
    );

// A low A2 with B1_N high forces Y high.
    check_a2_low_with_b1n_high_forces_y_high: assert property (
        @(posedge clk) ((A2 == 1'b0) && (B1_N == 1'b1)) |-> (Y == 1'b1)
    );

// A low A1 and B1_N low forces Y low.
    check_a1_low_with_b1n_low_forces_y_low: assert property (
        @(posedge clk) ((A1 == 1'b0) && (B1_N == 1'b0)) |-> (Y == 1'b0)
    );

// A low A2 and B1_N low forces Y low.
    check_a2_low_with_b1n_low_forces_y_low: assert property (
        @(posedge clk) ((A2 == 1'b0) && (B1_N == 1'b0)) |-> (Y == 1'b0)
    );

// When disabled, data holds its previous value on the next clock.
    check_hold_when_disabled: assert property (
        @(posedge clk) !en |=> (data == $past(data))
    );

// Address 00000 loads 0010 on the next clock.
    check_addr_00000_maps_to_0010: assert property (
        @(posedge clk) en && (addr == 5'b00000) |=> (data == 4'b0010)
    );

// Address 00001 loads 0010 on the next clock.
    check_addr_00001_maps_to_0010: assert property (
        @(posedge clk) en && (addr == 5'b00001) |=> (data == 4'b0010)
    );

// Address 00010 loads 1110 on the next clock.
    check_addr_00010_maps_to_1110: assert property (
        @(posedge clk) en && (addr == 5'b00010) |=> (data == 4'b1110)
    );

// Address 00011 loads 0010 on the next clock.
    check_addr_00011_maps_to_0010: assert property (
        @(posedge clk) en && (addr == 5'b00011) |=> (data == 4'b0010)
    );

// Address 00100 loads 0100 on the next clock.
    check_addr_00100_maps_to_0100: assert property (
        @(posedge clk) en && (addr == 5'b00100) |=> (data == 4'b0100)
    );

// Address 00101 loads 1010 on the next clock.
    check_addr_00101_maps_to_1010: assert property (
        @(posedge clk) en && (addr == 5'b00101) |=> (data == 4'b1010)
    );

// Address 00110 loads 1100 on the next clock.
    check_addr_00110_maps_to_1100: assert property (
        @(posedge clk) en && (addr == 5'b00110) |=> (data == 4'b1100)
    );

// Address 00111 loads 0000 on the next clock.
    check_addr_00111_maps_to_0000: assert property (
        @(posedge clk) en && (addr == 5'b00111) |=> (data == 4'b0000)
    );

// Address 01000 loads 1010 on the next clock.
    check_addr_01000_maps_to_1010: assert property (
        @(posedge clk) en && (addr == 5'b01000) |=> (data == 4'b1010)
    );

// Address 01001 loads 0010 on the next clock.
    check_addr_01001_maps_to_0010: assert property (
        @(posedge clk) en && (addr == 5'b01001) |=> (data == 4'b0010)
    );

// Address 01010 loads 1110 on the next clock.
    check_addr_01010_maps_to_1110: assert property (
        @(posedge clk) en && (addr == 5'b01010) |=> (data == 4'b1110)
    );

// Address 01011 loads 0010 on the next clock.
    check_addr_01011_maps_to_0010: assert property (
        @(posedge clk) en && (addr == 5'b01011) |=> (data == 4'b0010)
    );

// Address 01100 loads 0100 on the next clock.
    check_addr_01100_maps_to_0100: assert property (
        @(posedge clk) en && (addr == 5'b01100) |=> (data == 4'b0100)
    );

// Address 01101 loads 1010 on the next clock.
    check_addr_01101_maps_to_1010: assert property (
        @(posedge clk) en && (addr == 5'b01101) |=> (data == 4'b1010)
    );

// Address 01110 loads 1100 on the next clock.
    check_addr_01110_maps_to_1100: assert property (
        @(posedge clk) en && (addr == 5'b01110) |=> (data == 4'b1100)
    );

// Address 01111 loads 0000 on the next clock.
    check_addr_01111_maps_to_0000: assert property (
        @(posedge clk) en && (addr == 5'b01111) |=> (data == 4'b0000)
    );

// Reset clears count to zero on the next clock.
    check_reset_clears_count: assert property (
        @(posedge clk) rst |=> (count == 32'd0)
    );

// When enabled outside reset, count increments by one.
    check_count_increments_when_enabled: assert property (
        @(posedge clk) disable iff (rst) en |=> (count == ($past(count) + 32'd1))
    );

// When not enabled outside reset, count holds its value.
    check_count_holds_when_disabled: assert property (
        @(posedge clk) disable iff (rst) !en |=> (count == $past(count))
    );

// o_bus equals bitwise AND of i_bus1 and i_bus2.
    check_and_function: assert property (
        @(posedge clk) o_bus == (i_bus1 & i_bus2)
    );

// If i_bus1 is all zeros, o_bus must be all zeros.
    check_zero_when_i1_zero: assert property (
        @(posedge clk) (i_bus1 == 8'h00) |-> (o_bus == 8'h00)
    );

// If i_bus2 is all zeros, o_bus must be all zeros.
    check_zero_when_i2_zero: assert property (
        @(posedge clk) (i_bus2 == 8'h00) |-> (o_bus == 8'h00)
    );

// If i_bus1 is all ones, o_bus equals i_bus2.
    check_passthrough_when_i1_all_ones: assert property (
        @(posedge clk) (i_bus1 == 8'hFF) |-> (o_bus == i_bus2)
    );

// If i_bus2 is all ones, o_bus equals i_bus1.
    check_passthrough_when_i2_all_ones: assert property (
        @(posedge clk) (i_bus2 == 8'hFF) |-> (o_bus == i_bus1)
    );

// If o_bus is all ones, both inputs must be all ones.
    check_all_ones_implies_inputs_all_ones: assert property (
        @(posedge clk) (o_bus == 8'hFF) |-> ((i_bus1 == 8'hFF) && (i_bus2 == 8'hFF))
    );

// 0 maps to 00000000.
    check_bcd_0_maps_to_0: assert property (
        @(posedge clk) (bcd_in == 4'd0) |-> (bin_out == 8'b00000000)
    );

// 1 maps to 00000001.
    check_bcd_1_maps_to_1: assert property (
        @(posedge clk) (bcd_in == 4'd1) |-> (bin_out == 8'b00000001)
    );

// 2 maps to 00000010.
    check_bcd_2_maps_to_2: assert property (
        @(posedge clk) (bcd_in == 4'd2) |-> (bin_out == 8'b00000010)
    );

// 3 maps to 00000011.
    check_bcd_3_maps_to_3: assert property (
        @(posedge clk) (bcd_in == 4'd3) |-> (bin_out == 8'b00000011)
    );

// 4 maps to 00000100.
    check_bcd_4_maps_to_4: assert property (
        @(posedge clk) (bcd_in == 4'd4) |-> (bin_out == 8'b00000100)
    );

// 5 maps to 00000101.
    check_bcd_5_maps_to_5: assert property (
        @(posedge clk) (bcd_in == 4'd5) |-> (bin_out == 8'b00000101)
    );

// 6 maps to 00000110.
    check_bcd_6_maps_to_6: assert property (
        @(posedge clk) (bcd_in == 4'd6) |-> (bin_out == 8'b00000110)
    );

// 7 maps to 00000111.
    check_bcd_7_maps_to_7: assert property (
        @(posedge clk) (bcd_in == 4'd7) |-> (bin_out == 8'b00000111)
    );

// 8 maps to 00001000.
    check_bcd_8_maps_to_8: assert property (
        @(posedge clk) (bcd_in == 4'd8) |-> (bin_out == 8'b00001000)
    );

// 9 maps to 00001001.
    check_bcd_9_maps_to_9: assert property (
        @(posedge clk) (bcd_in == 4'd9) |-> (bin_out == 8'b00001001)
    );

// Values 10..15 map to 00000000 (default).
    check_bcd_default_maps_to_0: assert property (
        @(posedge clk) (bcd_in >= 4'd10) |-> (bin_out == 8'b00000000)
    );

// Load captures data into q on the next cycle.
    check_load_captures_data: assert property (
        @(posedge clk) load |=> (q == $past(data))
    );

// With ena == 2'b00, q holds its previous value on the next cycle.
    check_hold_when_ena_zero: assert property (
        @(posedge clk) disable iff (load) (ena == 2'b00) |=> (q == $past(q))
    );

// out_if_else is high exactly when q differs from data.
    check_out_if_else_matches_xor: assert property (
        @(posedge clk) out_if_else == (q != data)
    );

// X must match the implemented AND/NOT/AND logic.
    check_functional_equivalence: assert property (
        @(posedge clk) X == ((A1 & A2) & ~(B1 & B2))
    );

// A high X requires both A inputs to be high.
    check_x_requires_a_high: assert property (
        @(posedge clk) X |-> (A1 && A2)
    );

// Both A inputs high with both B inputs low must drive X high.
    check_a_high_b_low_sets_x: assert property (
        @(posedge clk) (A1 && A2 && !B1 && !B2) |-> X
    );

// Any low A input must force X low.
    check_a_low_clears_x: assert property (
        @(posedge clk) (!A1 || !A2) |-> !X
    );

// sel=00 routes a to o.
    check_sel_00_routes_a: assert property (
        @(posedge clk) (sel == 2'b00) |-> (o == a)
    );

// sel=01 routes b to o.
    check_sel_01_routes_b: assert property (
        @(posedge clk) (sel == 2'b01) |-> (o == b)
    );

// sel=10 routes c to o.
    check_sel_10_routes_c: assert property (
        @(posedge clk) (sel == 2'b10) |-> (o == c)
    );

// sel=11 routes d to o.
    check_sel_11_routes_d: assert property (
        @(posedge clk) (sel == 2'b11) |-> (o == d)
    );

// X equals (A1|A2|A3)&B1.
    check_function_equivalence: assert property (
        @(posedge clk) X == ((A1 | A2 | A3) & B1)
    );

// B1 low forces X low.
    check_b1_low_forces_x_low: assert property (
        @(posedge clk) !B1 |-> !X
    );

// Any A high with B1 high forces X high.
    check_any_a_with_b1_high_forces_x_high: assert property (
        @(posedge clk) (B1 && (A1 || A2 || A3)) |-> X
    );

// X high implies B1 is high.
    check_x_high_implies_b1_high: assert property (
        @(posedge clk) X |-> B1
    );

// X high implies at least one A is high.
    check_x_high_implies_any_a_high: assert property (
        @(posedge clk) X |-> (A1 || A2 || A3)
    );

// With B1 high, X equals (A1|A2|A3).
    check_b1_high_makes_x_equal_or: assert property (
        @(posedge clk) B1 |-> (X == (A1 | A2 | A3))
    );

// With B1 high, X low implies all A are low.
    check_b1_high_and_x_low_implies_all_a_low: assert property (
        @(posedge clk) (B1 && !X) |-> (!A1 && !A2 && !A3)
    );

// in[3] has highest priority and drives out to 00.
    check_in3_priority: assert property (
        @(posedge clk) disable iff (1'b0)
        (in == 4'b1110) |-> (out == 2'b00)
    );

// Default case with no asserted inputs drives out to 00.
    check_default_zero: assert property (
        @(posedge clk) disable iff (1'b0)
        (in == 4'b0000) |-> (out == 2'b00)
    );

// Y must equal the 4-input NOR of A, B, C, and D_N.
    check_y_matches_nor4: assert property (
        @(posedge clk) Y == ~(A | B | C | D_N)
    );

// A high must force Y low.
    check_a_high_forces_y_low: assert property (
        @(posedge clk) A |-> !Y
    );

// B high must force Y low.
    check_b_high_forces_y_low: assert property (
        @(posedge clk) B |-> !Y
    );

// C high must force Y low.
    check_c_high_forces_y_low: assert property (
        @(posedge clk) C |-> !Y
    );

// D_N high must force Y low.
    check_d_n_high_forces_y_low: assert property (
        @(posedge clk) D_N |-> !Y
    );

// All inputs low must drive Y high.
    check_all_inputs_low_drives_y_high: assert property (
        @(posedge clk) (!A && !B && !C && !D_N) |-> Y
    );

// X must equal A & ~SLEEP.
    check_function_equivalence: assert property (
        @(posedge clk) X == (A & ~SLEEP)
    );

// A LOW forces X LOW regardless of SLEEP.
    check_a_low_forces_x_low: assert property (
        @(posedge clk) (A == 1'b0) |-> (X == 1'b0)
    );

// Reset clears the counter and sets precharge_safe high.
    check_reset_clears_state: assert property (
        @(posedge sys_clk) sdram_rst |=> (counter == 3'd0) && (precharge_safe == 1'b1)
    );

// Y matches the implemented OR-then-NAND function.
    check_functional_equivalence: assert property (
        @(posedge clk) Y == ~(B1 & (A1 | A2))
    );

// B1 low forces Y high.
    check_b1_low_forces_y_high: assert property (
        @(posedge clk) !B1 |-> Y
    );

// A1 high with B1 high forces Y low.
    check_a1_high_with_b1_high_forces_y_low: assert property (
        @(posedge clk) (B1 && A1) |-> !Y
    );

// A2 high with B1 high forces Y low.
    check_a2_high_with_b1_high_forces_y_low: assert property (
        @(posedge clk) (B1 && A2) |-> !Y
    );

// Y high implies B1 is low or both A inputs are low.
    check_y_high_implies_cause: assert property (
        @(posedge clk) Y |-> (!B1 || (!A1 && !A2))
    );

// Y low implies B1 is high and at least one A input is high.
    check_y_low_implies_cause: assert property (
        @(posedge clk) !Y |-> (B1 && (A1 || A2))
    );

// Y must match the RTL mux equation.
    check_mux_equation: assert property (
        @(posedge clk) Y == (EN ? A : B)
    );

// When EN is high, Y must follow A.
    check_select_a_when_en_high: assert property (
        @(posedge clk) EN |-> (Y == A)
    );

// When EN is low, Y must follow B.
    check_select_b_when_en_low: assert property (
        @(posedge clk) !EN |-> (Y == B)
    );

// X must equal the OR of the two AND terms.
    check_function_equivalence: assert property (
        @(posedge clk) X == ((A1 & A2) | (B1 & B2))
    );

// A high A pair must drive X high.
    check_a_pair_forces_x_high: assert property (
        @(posedge clk) (A1 & A2) |-> X
    );

// A high B pair must drive X high.
    check_b_pair_forces_x_high: assert property (
        @(posedge clk) (B1 & B2) |-> X
    );

// A high X must come from at least one input pair.
    check_x_high_has_a_pair: assert property (
        @(posedge clk) X |-> (A1 & A2) || (B1 & B2)
    );

// pwrgood_pp0_out_X must equal X.
    check_pwrgood_equals_x: assert property (
        @(posedge clk) pwrgood_pp0_out_X == X
    );

// X must equal pwrgood_pp0_out_X.
    check_x_equals_pwrgood: assert property (
        @(posedge clk) X == pwrgood_pp0_out_X
    );

// X must equal the AND of not(A_N), B, C, D, VPWR, and VGND.
    check_x_function: assert property (
        @(posedge clk) X == (~A_N & B & C & D & VPWR & VGND)
    );

// A_N high forces X low.
    check_a_n_high_forces_x_low: assert property (
        @(posedge clk) A_N |-> !X
    );

// B low forces X low.
    check_b_low_forces_x_low: assert property (
        @(posedge clk) !B |-> !X
    );

// C low forces X low.
    check_c_low_forces_x_low: assert property (
        @(posedge clk) !C |-> !X
    );

// D low forces X low.
    check_d_low_forces_x_low: assert property (
        @(posedge clk) !D |-> !X
    );

// VPWR low forces X low.
    check_vpwr_low_forces_x_low: assert property (
        @(posedge clk) !VPWR |-> !X
    );

// VGND low forces X low.
    check_vgnd_low_forces_x_low: assert property (
        @(posedge clk) !VGND |-> !X
    );

// All required inputs high drive X high.
    check_all_inputs_high_drive_x_high: assert property (
        @(posedge clk) (!A_N && B && C && D && VPWR && VGND) |-> X
    );

// When sel is high, OUT selects the twos complement of A.
    check_sel_high_selects_twos_comp: assert property (
        @(posedge clk) sel |-> (OUT == ~A + 4'd1)
    );

// With sel high, OUT equals ~A + 4'd1.
    check_out_equals_twos_comp_when_sel_high: assert property (
        @(posedge clk) sel |-> (OUT == ~A + 4'd1)
    );

// With sel high, OUT equals A when A is zero.
    check_out_equals_a_when_sel_high_and_a_zero: assert property (
        @(posedge clk) sel && (A == 4'd0) |-> (OUT == A)
    );

// out[0] is a direct copy of in[0].
    check_out0_is_in0: assert property (
        @(posedge clk) out[0] == in[0]
    );

// out[1] is in[0] XOR in[1].
    check_out1_is_in0_xor_in1: assert property (
        @(posedge clk) out[1] == (in[0] ^ in[1])
    );

// out[2] is in[1] XOR in[2] XOR in[0].
    check_out2_is_in1_xor_in2_xor_in0: assert property (
        @(posedge clk) out[2] == (in[1] ^ in[2] ^ in[0])
    );

// out[3] is in[2] XOR in[3] XOR in[1].
    check_out3_is_in2_xor_in3_xor_in1: assert property (
        @(posedge clk) out[3] == (in[2] ^ in[3] ^ in[1])
    );

// When sel is 0, out must equal a.
    check_sel0_routes_a: assert property (
        @(posedge clk) (sel == 1'b0) |-> (out == a)
    );

// When sel is 1, out must equal b.
    check_sel1_routes_b: assert property (
        @(posedge clk) (sel == 1'b1) |-> (out == b)
    );

// When a and b are equal, out must equal that value regardless of sel.
    check_equal_inputs_passthrough: assert property (
        @(posedge clk) (a == b) |-> (out == a)
    );

// Next-cycle out equals previous-cycle in.
    check_out_follows_prev_in: assert property (
        @(posedge clk) 1'b1 |=> (out == $past(in))
    );

// If out is 1 now, previous cycle's in was 1.
    check_prev_in_high_when_out_high: assert property (
        @(posedge clk) 1'b1 |=> (out == 1'b1) |-> $past(in) == 1'b1
    );

// If out is 0 now, previous cycle's in was 0.
    check_prev_in_low_when_out_low: assert property (
        @(posedge clk) 1'b1 |=> (out == 1'b0) |-> !$past(in)
    );

// X equals (A1 ^ A2) & B1.
    check_function_equivalence: assert property (
        @(posedge clk) X == ((A1 ^ A2) & B1)
    );

// B1 low forces X low.
    check_b1_low_forces_x_low: assert property (
        @(posedge clk) !B1 |-> !X
    );

// Equal A1/A2 inputs force X low.
    check_equal_inputs_force_x_low: assert property (
        @(posedge clk) (A1 == A2) |-> !X
    );

// Different A1/A2 inputs with B1 high drive X high.
    check_different_inputs_with_b1_high_drive_x_high: assert property (
        @(posedge clk) (A1 != A2) && B1 |-> X
    );

// X high implies B1 is high.
    check_x_high_implies_b1_high: assert property (
        @(posedge clk) X |-> B1
    );

// X high implies A1 and A2 differ.
    check_x_high_implies_inputs_different: assert property (
        @(posedge clk) X |-> (A1 != A2)
    );

// X matches the implemented combinational function.
    check_functional_equivalence: assert property (
        @(posedge clk) X == (SLEEP_B & A)
    );

// A low forces X low.
    check_a_low_forces_x_low: assert property (
        @(posedge clk) !A |-> !X
    );

// SLEEP_B low forces X low.
    check_sleepb_low_forces_x_low: assert property (
        @(posedge clk) !SLEEP_B |-> !X
    );

// With both inputs high, X must be high.
    check_both_inputs_high_drive_x_high: assert property (
        @(posedge clk) (A && SLEEP_B) |-> X
    );

// X high implies both inputs are high.
    check_x_high_requires_both_inputs_high: assert property (
        @(posedge clk) X |-> (A && SLEEP_B)
    );

// Reset clears the accumulator on the next clock.
    check_reset_clears_out: assert property (
        @(posedge clk) rst |=> (out == 8'h00)
    );

// With reset low, the next output equals the previous input plus the previous output.
    check_accumulation: assert property (
        @(posedge clk) disable iff (rst) 1'b1 |=> (out == ($past(data_in) + $past(out)))
    );

// Adding zero leaves the accumulator unchanged.
    check_zero_input_holds_value: assert property (
        @(posedge clk) disable iff (rst) (data_in == 8'h00) |=> (out == $past(out))
    );

// Addition mode drives result to a + b.
    check_add_result: assert property (
        @(posedge clk) (ctrl == 2'b00) |-> (result == (a + b))
    );

// Subtraction mode drives result to a - b.
    check_sub_result: assert property (
        @(posedge clk) (ctrl == 2'b01) |-> (result == (a - b))
    );

// XOR mode drives result to a ^ b.
    check_xor_result: assert property (
        @(posedge clk) (ctrl == 2'b10) |-> (result == (a ^ b))
    );

// Invalid control values drive result to zero.
    check_default_zero: assert property (
        @(posedge clk) (ctrl == 2'b11) |-> (result == 8'h00)
    );

// Zero on b passes a through for addition.
    check_add_zero_b_passthrough: assert property (
        @(posedge clk) (ctrl == 2'b00 && b == 8'h00) |-> (result == a)
    );

// Zero on b passes a through for subtraction.
    check_sub_zero_b_passthrough: assert property (
        @(posedge clk) (ctrl == 2'b01 && b == 8'h00) |-> (result == a)
    );

// Zero on a and b produce zero for XOR.
    check_xor_zero_inputs: assert property (
        @(posedge clk) (ctrl == 2'b10 && a == 8'h00 && b == 8'h00) |-> (result == 8'h00)
    );

// Zero on a and b produce zero for addition.
    check_add_zero_inputs: assert property (
        @(posedge clk) (ctrl == 2'b00 && a == 8'h00 && b == 8'h00) |-> (result == 8'h00)
    );

// Zero on a and b produce zero for subtraction.
    check_sub_zero_inputs: assert property (
        @(posedge clk) (ctrl == 2'b01 && a == 8'h00 && b == 8'h00) |-> (result == 8'h00)
    );

// X matches the implemented 3-input OR of the three AND terms.
    check_function_equivalence: assert property (
        @(posedge clk) X == ((A1 & A2) | (B1 & B2) | (C1 & C2))
    );

// A1 and A2 high together force X high.
    check_a_pair_forces_x_high: assert property (
        @(posedge clk) (A1 & A2) |-> X
    );

// B1 and B2 high together force X high.
    check_b_pair_forces_x_high: assert property (
        @(posedge clk) (B1 & B2) |-> X
    );

// C1 and C2 high together force X high.
    check_c_pair_forces_x_high: assert property (
        @(posedge clk) (C1 & C2) |-> X
    );

// X high implies at least one input pair is high together.
    check_x_high_implies_pair_high: assert property (
        @(posedge clk) X |-> (A1 & A2) || (B1 & B2) || (C1 & C2)
    );

// Sum bit 0 matches the first full-adder XOR.
    check_sum_bit0: assert property (
        @(posedge clk) S[0] == (A[0] ^ B[0] ^ Cin)
    );

// Sum bit 1 uses the carry generated from bit 0.
    check_sum_bit1: assert property (
        @(posedge clk) S[1] == (A[1] ^ B[1] ^ ((A[0] & B[0]) | (A[0] & Cin) | (B[0] & Cin)))
    );

// Sum bit 2 uses the carry generated from bit 1.
    check_sum_bit2: assert property (
        @(posedge clk) S[2] == (A[2] ^ B[2] ^ (
            (A[1] & B[1]) |
            ((A[1] & (A[0] & B[0])) | (A[1] & (A[0] & Cin)) | (A[1] & (B[0] & Cin))) |
            ((B[1] & (A[0] & B[0])) | (B[1] & (A[0] & Cin)) | (B[1] & (B[0] & Cin)))
        ))
    );

// The 5-bit output matches the 4-bit A + 4-bit B + Cin.
    check_total_sum: assert property (
        @(posedge clk) {Cout, S} == ({1'b0, A} + {1'b0, B} + Cin)
    );

// Output is bitwise complement of input.
    check_output_complement: assert property (
        @(posedge clk) o == ~x
    );

// Carry flag is forced low.
    check_cfo_low: assert property (
        @(posedge clk) cfo == 1'b0
    );

// Overflow flag is forced low.
    check_ofo_low: assert property (
        @(posedge clk) ofo == 1'b0
    );

// out must be 00 when inputs are equal.
    check_equal_maps_zero: assert property (
        @(posedge clk) (in1 == in2) |-> (out == 2'b00)
    );

// out must be 01 when in1 is greater than in2.
    check_greater_maps_one: assert property (
        @(posedge clk) (in1 > in2) |-> (out == 2'b01)
    );

// out must be 10 when in1 is less than in2.
    check_less_maps_two: assert property (
        @(posedge clk) (in1 < in2) |-> (out == 2'b10)
    );

// out must never be 11.
    check_no_invalid_code: assert property (
        @(posedge clk) (out != 2'b11)
    );

// out must always match the RTL comparison result.
    check_full_functional_equivalence: assert property (
        @(posedge clk) out == ((in1 > in2) ? 2'b01 : ((in1 == in2) ? 2'b00 : 2'b10))
    );

// Reset clears the counter on the next clock.
    check_reset_clears_count: assert property (
        @(posedge CLK) reset |=> (count == 4'b0000)
    );

// When enabled, the counter increments by one on the next clock.
    check_count_increments_when_enabled: assert property (
        @(posedge CLK) disable iff (reset)
        enable |=> (count == ($past(count) + 4'd1))
    );

// When not enabled, the counter holds its value on the next clock.
    check_count_holds_when_disabled: assert property (
        @(posedge CLK) disable iff (reset)
        !enable |=> (count == $past(count))
    );

// The 4-bit counter wraps from 15 back to 0 when enabled.
    check_count_wraps_from_max: assert property (
        @(posedge CLK) disable iff (reset)
        (enable && (count == 4'hF)) |=> (count == 4'h0)
    );

// Reset clears the stored data and output valid flag on the next cycle.
    check_reset_clears_outputs: assert property (
        @(posedge clk) reset |=> (out_data == 32'h0000_0000) && (out_valid == 1'b0)
    );

// A valid input updates the output data and raises the output valid flag on the next cycle.
    check_valid_input_updates_output: assert property (
        @(posedge clk) disable iff (reset)
        in_valid |=> (out_data == $past(in_data)) && (out_valid == 1'b1)
    );

// Without a valid input, the output valid flag is cleared on the next cycle.
    check_no_valid_input_clears_valid: assert property (
        @(posedge clk) disable iff (reset)
        !in_valid |=> (out_valid == 1'b0)
    );

// Output data holds its value when no valid input is received.
    check_no_valid_input_holds_data: assert property (
        @(posedge clk) disable iff (reset)
        !in_valid |=> (out_data == $past(out_data))
    );

// Reset clears the shift register and output.
    check_reset_clears_state: assert property (
        @(posedge clk) rst |-> (shiftreg == 64'h0) && (out == 1'b0)
    );

// With no control asserted, the output holds its value.
    check_out_hold_when_idle: assert property (
        @(posedge clk) disable iff (rst) (!ld && !shift) |=> (out == $past(out))
    );

// Addition opcode drives out to a + b.
    check_addition_result: assert property (
        @(posedge clk) (op == 3'b000) |-> (out == (a + b))
    );

// Subtraction opcode drives out to a - b.
    check_subtraction_result: assert property (
        @(posedge clk) (op == 3'b001) |-> (out == (a - b))
    );

// AND opcode drives out to a & b.
    check_and_result: assert property (
        @(posedge clk) (op == 3'b010) |-> (out == (a & b))
    );

// OR opcode drives out to a | b.
    check_or_result: assert property (
        @(posedge clk) (op == 3'b011) |-> (out == (a | b))
    );

// XOR opcode drives out to a ^ b.
    check_xor_result: assert property (
        @(posedge clk) (op == 3'b100) |-> (out == (a ^ b))
    );

// Shift-left opcode drives out to {a[2:0], 1'b0}.
    check_shift_left_result: assert property (
        @(posedge clk) (op == 3'b101) |-> (out == {a[2:0], 1'b0})
    );

// Default opcode drives out to 4'b0.
    check_default_zero: assert property (
        @(posedge clk) (op == 3'b110) |-> (out == 4'b0000)
    );

// Default opcode drives out to 4'b0.
    check_default_zero_111: assert property (
        @(posedge clk) (op == 3'b111) |-> (out == 4'b0000)
    );

// Reset clears the output on the next clock.
    check_reset_clears_c: assert property (
        @(posedge CLK) RST |=> (C == 8'h00)
    );

// When OP is 1, C captures A - B on the next clock.
    check_subtract_result: assert property (
        @(posedge CLK) disable iff (RST)
        (OP == 1'b1) |=> (C == ($past(A) - $past(B)))
    );

// When OP is 0, C captures A + B on the next clock.
    check_add_result: assert property (
        @(posedge CLK) disable iff (RST)
        (OP == 1'b0) |=> (C == ($past(A) + $past(B)))
    );

// With B==0, add returns A unchanged.
    check_add_zero_rhs: assert property (
        @(posedge CLK) disable iff (RST)
        (OP == 1'b0 && B == 8'h00) |=> (C == $past(A))
    );

// EQ must match the equality comparison of A and B.
    check_eq_definition: assert property (
        @(posedge clk) EQ == (A == B)
    );

// GT must match the greater-than comparison of A and B.
    check_gt_definition: assert property (
        @(posedge clk) GT == (A > B)
    );

// LT must match the less-than comparison of A and B.
    check_lt_definition: assert property (
        @(posedge clk) LT == (A < B)
    );

// Exactly one of EQ, GT, or LT must be HIGH.
    check_outputs_onehot: assert property (
        @(posedge clk) $onehot({EQ, GT, LT})
    );

// When A equals B, only EQ can be HIGH.
    check_eq_when_equal: assert property (
        @(posedge clk) (A == B) |-> (EQ && !GT && !LT)
    );

// When A is greater than B, only GT can be HIGH.
    check_gt_when_greater: assert property (
        @(posedge clk) (A > B) |-> (GT && !EQ && !LT)
    );

// When A is less than B, only LT can be HIGH.
    check_lt_when_less: assert property (
        @(posedge clk) (A < B) |-> (LT && !EQ && !GT)
    );

// When both select inputs are high, b is selected and pos is added.
    check_select_b_path: assert property (
        @(posedge clk) (sel_b1 && sel_b2) |-> (out_sum == (b + pos))
    );

// When no input bit is high, pos must be zero.
    check_pos_zero_when_no_high_bit: assert property (
        @(posedge clk) !in[7:0] |-> (pos == 3'd0)
    );

// When only the LSB is high, pos must be zero.
    check_pos_zero_when_only_lsb: assert property (
        @(posedge clk) (in == 8'h01) |-> (pos == 3'd0)
    );

// When only the MSB is high, pos must be seven.
    check_pos_seven_when_only_msb: assert property (
        @(posedge clk) (in == 8'h80) |-> (pos == 3'd7)
    );

// Shift-left moves the previous data_in value into the register.
    check_shift_left_moves_data: assert property (
        @(posedge clk) (!load && !shift_right) |=> (data_out == $past(data_in))
    );

// Four consecutive loads return the input value four cycles later.
    check_four_loads_return_input: assert property (
        @(posedge clk) (load[*4]) |=> (data_out == $past(data_in, 4))
    );

// Four consecutive shift-right operations return the value four cycles later.
    check_four_shift_right_return_value: assert property (
        @(posedge clk) (!load && shift_right[*4]) |=> (data_out == $past(data_out, 4))
    );

// y equals d0 OR d1 every cycle.
    check_y_matches_or: assert property (
        @(posedge clk) disable iff (clr) y == (d0 | d1)
    );

// If d0 is 1, y must be 1.
    check_y_high_when_d0_high: assert property (
        @(posedge clk) disable iff (clr) d0 |-> y
    );

// If d1 is 1, y must be 1.
    check_y_high_when_d1_high: assert property (
        @(posedge clk) disable iff (clr) d1 |-> y
    );

// If both d0 and d1 are 0, y must be 0.
    check_y_low_when_both_zero: assert property (
        @(posedge clk) disable iff (clr) (!d0 && !d1) |-> !y
    );

// If y is 0, both d0 and d1 must be 0.
    check_inputs_zero_when_y_zero: assert property (
        @(posedge clk) disable iff (clr) !y |-> (!d0 && !d1)
    );

// If y is 1, at least one of d0 or d1 must be 1.
    check_inputs_nonzero_when_y_one: assert property (
        @(posedge clk) disable iff (clr) y |-> (d0 || d1)
    );

// Y matches the implemented AOI3 logic.
    check_y_matches_a221oi_function: assert property (
        @(posedge clk) Y == ~(B1 & B2 | C1 | A1 & A2)
    );

// A high C1 forces Y low.
    check_c1_forces_y_low: assert property (
        @(posedge clk) C1 |-> !Y
    );

// A high A1 and A2 force Y low.
    check_a_pair_forces_y_low: assert property (
        @(posedge clk) (A1 && A2) |-> !Y
    );

// A high B1 and B2 force Y low.
    check_b_pair_forces_y_low: assert property (
        @(posedge clk) (B1 && B2) |-> !Y
    );

// With no asserted OR/AND path, Y must be high.
    check_no_active_path_sets_y_high: assert property (
        @(posedge clk) (!C1 && !(A1 && A2) && !(B1 && B2)) |-> Y
    );

// A high Y requires all OR/AND paths to be inactive.
    check_y_high_requires_all_paths_inactive: assert property (
        @(posedge clk) Y |-> (!C1 && !(A1 && A2) && !(B1 && B2))
    );

// No reset in RTL; sample combinational behavior on clk.

    // out must match the RTL mux expression.
    check_mux_function: assert property (
        @(posedge clk) out == (Sel[1] ? (Sel[0] ? S3 : S2) : (Sel[0] ? S1 : S0))
    );

// When Sel==00, out must select S0.
    check_sel_00_selects_S0: assert property (
        @(posedge clk) (Sel == 2'b00) |-> (out == S0)
    );

// When Sel==01, out must select S1.
    check_sel_01_selects_S1: assert property (
        @(posedge clk) (Sel == 2'b01) |-> (out == S1)
    );

// When Sel==10, out must select S2.
    check_sel_10_selects_S2: assert property (
        @(posedge clk) (Sel == 2'b10) |-> (out == S2)
    );

// When Sel==11, out must select S3.
    check_sel_11_selects_S3: assert property (
        @(posedge clk) (Sel == 2'b11) |-> (out == S3)
    );

// Reset clears both count and overflow on the next cycle.
    check_reset_clears_outputs: assert property (
        @(posedge clk) reset |=> (count == 4'h0) && (overflow == 1'b0)
    );

// When enabled below max, count increments by one.
    check_count_increments: assert property (
        @(posedge clk) disable iff (reset)
        (enable && (count != 4'hF)) |=> (count == ($past(count) + 4'd1))
    );

// When enabled at max, count wraps to zero.
    check_count_wraps: assert property (
        @(posedge clk) disable iff (reset)
        (enable && (count == 4'hF)) |=> (count == 4'h0)
    );

// When enabled below max, overflow is cleared.
    check_overflow_clears: assert property (
        @(posedge clk) disable iff (reset)
        (enable && (count != 4'hF)) |=> (overflow == 1'b0)
    );

// When enabled at max, overflow is asserted.
    check_overflow_asserts: assert property (
        @(posedge clk) disable iff (reset)
        (enable && (count == 4'hF)) |=> (overflow == 1'b1)
    );

// When not enabled, count holds its value.
    check_count_holds_when_disabled: assert property (
        @(posedge clk) disable iff (reset)
        (!enable) |=> (count == $past(count))
    );

// When not enabled, overflow holds its value.
    check_overflow_holds_when_disabled: assert property (
        @(posedge clk) disable iff (reset)
        (!enable) |=> (overflow == $past(overflow))
    );

// Reset clears the counter and value on the next cycle.
    check_reset_clears_state: assert property (
        @(posedge clk) rst |=> (ctr_q == 27'd0 && value == 8'd0)
    );

// Z must match the RTL mux equation.
    check_mux_equation: assert property (
        @(posedge clk) Z == (TE_B ? A : 1'b0)
    );

// When TE_B is low, Z must be forced low.
    check_te_b_low_forces_z_low: assert property (
        @(posedge clk) !TE_B |-> (Z == 1'b0)
    );

// When TE_B is high, Z must follow A.
    check_te_b_high_passes_a: assert property (
        @(posedge clk) TE_B |-> (Z == A)
    );

// A falling edge on TE_B must drive Z low.
    check_te_b_fall_clears_z: assert property (
        @(posedge clk) $fell(TE_B) |-> (Z == 1'b0)
    );

// A rising edge on A must be reflected on Z when TE_B is high.
    check_a_rise_sets_z_when_te_b_high: assert property (
        @(posedge clk) TE_B && $rose(A) |-> (Z == 1'b1)
    );

// A falling edge on A must be reflected on Z when TE_B is high.
    check_a_fall_clears_z_when_te_b_high: assert property (
        @(posedge clk) TE_B && $fell(A) |-> (Z == 1'b0)
    );

// Q captures SCE ? SCD : D on the next clock.
    check_q_captures_muxed_input: assert property (
        @(posedge CLK) 1'b1 |=> (Q == ($past(SCE) ? $past(SCD) : $past(D)))
    );

// Q_N is the complement of Q on the next clock.
    check_qn_complements_q: assert property (
        @(posedge CLK) 1'b1 |=> (Q_N == ~Q)
    );

// With SCE low, Q captures D on the next clock.
    check_q_captures_d_when_sce_low: assert property (
        @(posedge CLK) !SCE |=> (Q == $past(D))
    );

// With SCE high, Q captures SCD on the next clock.
    check_q_captures_scd_when_sce_high: assert property (
        @(posedge CLK) SCE |=> (Q == $past(SCD))
    );

// A rising edge on SCE causes Q to capture SCD on the next clock.
    check_q_captures_scd_on_sce_rise: assert property (
        @(posedge CLK) $rose(SCE) |=> (Q == $past(SCD))
    );

// A falling edge on SCE causes Q to capture D on the next clock.
    check_q_captures_d_on_sce_fall: assert property (
        @(posedge CLK) $fell(SCE) |=> (Q == $past(D))
    );

// A rising edge on SCD causes Q to capture SCD on the next clock when SCE is high.
    check_q_captures_scd_on_scd_rise_when_sce_high: assert property (
        @(posedge CLK) SCE && $rose(SCD) |=> (Q == $past(SCD))
    );

// X matches the implemented O2111A Boolean function.
    check_functional_equivalence: assert property (
        @(posedge clk) X == (B1 & C1 & D1 & (A1 | A2))
    );

// A high X requires all four AND inputs to be high.
    check_x_high_requires_and_inputs: assert property (
        @(posedge clk) X |-> (B1 & C1 & D1)
    );

// A high X requires at least one OR input to be high.
    check_x_high_requires_or_input: assert property (
        @(posedge clk) X |-> (A1 | A2)
    );

// All four AND inputs high with at least one OR input high drive X high.
    check_all_conditions_drive_x_high: assert property (
        @(posedge clk) (B1 & C1 & D1 & (A1 | A2)) |-> X
    );

// A low B1 forces X low.
    check_b1_low_forces_x_low: assert property (
        @(posedge clk) !B1 |-> !X
    );

// A low C1 forces X low.
    check_c1_low_forces_x_low: assert property (
        @(posedge clk) !C1 |-> !X
    );

// A low D1 forces X low.
    check_d1_low_forces_x_low: assert property (
        @(posedge clk) !D1 |-> !X
    );

// A low A1 with A2 low forces X low.
    check_a1_a2_low_forces_x_low: assert property (
        @(posedge clk) (!A1 && !A2) |-> !X
    );

// Up mode: 7 wraps to 0.
    check_up_wrap_from_max: assert property (
        @(posedge clk) (up_down == 1'b0) && (q == 3'd7) |=> (q == 3'd0)
    );

// Up mode: 0..6 increment by 1.
    check_up_increment: assert property (
        @(posedge clk) (up_down == 1'b0) && (q != 3'd7) |=> (q == ($past(q) + 3'd1))
    );

// Down mode: 0 wraps to 7.
    check_down_wrap_from_zero: assert property (
        @(posedge clk) (up_down == 1'b1) && (q == 3'd0) |=> (q == 3'd7)
    );

// Down mode: 1..7 decrement by 1.
    check_down_decrement: assert property (
        @(posedge clk) (up_down == 1'b1) && (q != 3'd0) |=> (q == ($past(q) - 3'd1))
    );

// When C is high, Q must be A minus B.
    check_subtract_result: assert property (
        @(posedge clk) (C == 1'b1) |-> (Q == (A - B))
    );

// When C is low, Q must be A plus B.
    check_add_result: assert property (
        @(posedge clk) (C == 1'b0) |-> (Q == (A + B))
    );

// Zero on B must pass A through unchanged regardless of C.
    check_b_zero_passthrough: assert property (
        @(posedge clk) (B == 16'h0000) |-> (Q == A)
    );

// Subtracting equal operands must produce zero.
    check_subtract_equal_operands_zero: assert property (
        @(posedge clk) (C == 1'b1) && (A == B) |-> (Q == 16'h0000)
    );

// Adding equal operands must produce double that value.
    check_add_equal_operands_double: assert property (
        @(posedge clk) (C == 1'b0) && (A == B) |-> (Q == (A << 1))
    );

// Y matches the implemented NOT/NOR/AND logic.
    check_y_matches_implemented_logic: assert property (
        @(posedge clk) Y == ~((~B1_N) | (A1 & A2))
    );

// A low B1_N with any A input high forces Y low.
    check_b1n_low_and_any_a_high_forces_y_low: assert property (
        @(posedge clk) (!B1_N && (A1 || A2)) |-> !Y
    );

// select 00 drives zero on data_out.
    check_select_zero_drives_zero: assert property (
        @(posedge clk) (select == 2'b00) |-> (data_out == 32'b0)
    );

// select 01 drives ch_0 on data_out.
    check_select_one_drives_ch0: assert property (
        @(posedge clk) (select == 2'b01) |-> (data_out == ch_0)
    );

// select 10 drives ch_1 on data_out.
    check_select_two_drives_ch1: assert property (
        @(posedge clk) (select == 2'b10) |-> (data_out == ch_1)
    );

// select 11 drives ch_2 on data_out.
    check_select_three_drives_ch2: assert property (
        @(posedge clk) (select == 2'b11) |-> (data_out == ch_2)
    );

// Y must match the RTL NAND equation.
    check_nand_equation: assert property (
        @(posedge clk) Y == ~(A_N & B)
    );

// Y must equal the AND of all five inputs.
    check_y_matches_and_function: assert property (
        @(posedge clk) Y == (A1 & A2 & B1 & C1 & D1)
    );

// A low A1 input forces Y low.
    check_a1_low_forces_y_low: assert property (
        @(posedge clk) !A1 |-> !Y
    );

// A low A2 input forces Y low.
    check_a2_low_forces_y_low: assert property (
        @(posedge clk) !A2 |-> !Y
    );

// A low B1 input forces Y low.
    check_b1_low_forces_y_low: assert property (
        @(posedge clk) !B1 |-> !Y
    );

// A low C1 input forces Y low.
    check_c1_low_forces_y_low: assert property (
        @(posedge clk) !C1 |-> !Y
    );

// A low D1 input forces Y low.
    check_d1_low_forces_y_low: assert property (
        @(posedge clk) !D1 |-> !Y
    );

// All five high inputs drive Y high.
    check_all_high_drives_y_high: assert property (
        @(posedge clk) (A1 & A2 & B1 & C1 & D1) |-> Y
    );

// X must match the implemented A22O logic.
    check_function_equivalence: assert property (
        @(posedge clk) X == ((A1 & A2) | (B1 & B2))
    );

// A high A pair must drive X high.
    check_a_pair_forces_x_high: assert property (
        @(posedge clk) (A1 & A2) |-> X
    );

// A high B pair must drive X high.
    check_b_pair_forces_x_high: assert property (
        @(posedge clk) (B1 & B2) |-> X
    );

// A high X must come from at least one input pair.
    check_x_high_has_active_pair: assert property (
        @(posedge clk) X |-> (A1 & A2) || (B1 & B2)
    );

// OUT equals 4-bit sum of A and B.
    check_total_sum: assert property (
        @(posedge clk) OUT == (A + B)
    );

// LSB sum is XOR of A[0] and B[0].
    check_lsb_sum: assert property (
        @(posedge clk) OUT[0] == (A[0] ^ B[0])
    );

// sel1=0, sel2=0 routes d0 to out.
    check_sel00_routes_d0: assert property (
        @(posedge clk) (!sel1 && !sel2) |-> (out == d0)
    );

// sel1=0, sel2=1 routes d1 to out.
    check_sel01_routes_d1: assert property (
        @(posedge clk) (!sel1 && sel2) |-> (out == d1)
    );

// sel1=1, sel2=0 routes d2 to out.
    check_sel10_routes_d2: assert property (
        @(posedge clk) (sel1 && !sel2) |-> (out == d2)
    );

// sel1=1, sel2=1 routes d3 to out.
    check_sel11_routes_d3: assert property (
        @(posedge clk) (sel1 && sel2) |-> (out == d3)
    );

// The 4-bit output matches A + B + Ci.
    check_total_sum: assert property (
        @(posedge clk) disable iff (1'b0)
        {Co, S} == ({1'b0, A} + {1'b0, B} + Ci)
    );

// Bit 0 sum is the XOR of A[0], B[0], and Ci.
    check_bit0_sum: assert property (
        @(posedge clk) disable iff (1'b0)
        S[0] == (A[0] ^ B[0] ^ Ci)
    );

// Bit 1 sum uses the carry generated from bit 0.
    check_bit1_sum: assert property (
        @(posedge clk) disable iff (1'b0)
        S[1] == (A[1] ^ B[1] ^ ((A[0] & B[0]) | ((A[0] ^ B[0]) & Ci)))
    );

// Bit 2 sum uses the carry generated from bit 1.
    check_bit2_sum: assert property (
        @(posedge clk) disable iff (1'b0)
        S[2] == (A[2] ^ B[2] ^ ((A[1] & B[1]) | ((A[1] ^ B[1]) & ((A[0] & B[0]) | ((A[0] ^ B[0]) & Ci)))))
    );

// Bit 3 sum uses the carry generated from bit 2.
    check_bit3_sum: assert property (
        @(posedge clk) disable iff (1'b0)
        S[3] == (A[3] ^ B[3] ^ ((A[2] & B[2]) | ((A[2] ^ B[2]) & ((A[1] & B[1]) | ((A[1] ^ B[1]) & ((A[0] & B[0]) | ((A[0] ^ B[0]) & Ci)))))))
    );

// Carry out is the final carry generated from bit 3.
    check_carry_out: assert property (
        @(posedge clk) disable iff (1'b0)
        Co == ((A[3] & B[3]) | ((A[3] ^ B[3]) & ((A[2] & B[2]) | ((A[2] ^ B[2]) & ((A[1] & B[1]) | ((A[1] ^ B[1]) & ((A[0] & B[0]) | ((A[0] ^ B[0]) & Ci))))))))
    );

// q captures d1 on the next falling edge when sel is low.
    check_capture_d1_when_sel_low: assert property (
        @(negedge clk) !sel |=> (q == $past(d1))
    );

// q captures d2 on the next falling edge when sel is high.
    check_capture_d2_when_sel_high: assert property (
        @(negedge clk) sel |=> (q == $past(d2))
    );

// out must be 1 when the magnitude of A is greater than the magnitude of B.
    check_out_high_when_a_greater: assert property (
        @(posedge clk) (|A > |B) |-> (out == 1'b1)
    );

// out must be 0 when the magnitude of A is less than or equal to the magnitude of B.
    check_out_low_when_a_not_greater: assert property (
        @(posedge clk) (|A <= |B) |-> (out == 1'b0)
    );

// out must match the RTL comparison result.
    check_out_matches_rtl_comparison: assert property (
        @(posedge clk) out == (|A > |B)
    );

// Reset clears dout on the next cycle.
    check_reset_clears_dout: assert property (
        @(posedge clk) reset |=> (dout == 32'd0)
    );

// With ce low, dout holds its value.
    check_hold_when_ce_low: assert property (
        @(posedge clk) disable iff (reset) !ce |=> (dout == $past(dout))
    );

// X equals A|B|C|D whenever any input changes.
    check_or_function_on_input_change: assert property (
        @(posedge clk) disable iff (1'b0)
        ($changed(A) || $changed(B) || $changed(C) || $changed(D)) |-> (X == (A | B | C | D))
    );

// X equals A|B|C|D whenever any power/gate input changes.
    check_or_function_on_power_change: assert property (
        @(posedge clk) disable iff (1'b0)
        ($changed(VPWR) || $changed(VGND) || $changed(VPB) || $changed(VNB)) |-> (X == (A | B | C | D))
    );

// X is 0 when all data inputs are 0.
    check_zero_when_all_zero: assert property (
        @(posedge clk) disable iff (1'b0)
        (!A && !B && !C && !D) |-> (X == 1'b0)
    );

// X is 1 when any data input is 1.
    check_one_when_any_one: assert property (
        @(posedge clk) disable iff (1'b0)
        (A || B || C || D) |-> (X == 1'b1)
    );

// A rising edge on X implies at least one data input is 1.
    check_x_rise_has_cause: assert property (
        @(posedge clk) disable iff (1'b0)
        $rose(X) |-> (A || B || C || D)
    );

// A falling edge on X implies all data inputs are 0.
    check_x_fall_has_cause: assert property (
        @(posedge clk) disable iff (1'b0)
        $fell(X) |-> (!A && !B && !C && !D)
    );

// sel=00 routes in0 to out.
    check_sel_00_routes_in0: assert property (
        @(posedge clk) (sel == 2'b00) |-> (out == in0)
    );

// sel=01 routes in1 to out.
    check_sel_01_routes_in1: assert property (
        @(posedge clk) (sel == 2'b01) |-> (out == in1)
    );

// sel=10 routes in2 to out.
    check_sel_10_routes_in2: assert property (
        @(posedge clk) (sel == 2'b10) |-> (out == in2)
    );

// sel=11 routes in3 to out.
    check_sel_11_routes_in3: assert property (
        @(posedge clk) (sel == 2'b11) |-> (out == in3)
    );

// and_res must equal A & B.
    check_and_result: assert property (
        @(posedge clk) and_res == (A & B)
    );

// or_res must equal A | B.
    check_or_result: assert property (
        @(posedge clk) or_res == (A | B)
    );

// xor_res must equal A ^ B.
    check_xor_result: assert property (
        @(posedge clk) xor_res == (A ^ B)
    );

// not_res must equal ~A.
    check_not_result: assert property (
        @(posedge clk) not_res == ~A
    );

// and_res must be a subset of A.
    check_and_subset_a: assert property (
        @(posedge clk) (and_res & ~A) == 4'b0000
    );

// and_res must be a subset of B.
    check_and_subset_b: assert property (
        @(posedge clk) (and_res & ~B) == 4'b0000
    );

// not_res must be the bitwise inverse of A.
    check_not_inverse: assert property (
        @(posedge clk) (not_res | A) == 4'b1111
    );

// Y matches the implemented NOR-AND function.
    check_functional_equivalence: assert property (
        @(posedge clk) Y == (C_N & ~(A | B))
    );

// A high forces Y low.
    check_a_high_forces_y_low: assert property (
        @(posedge clk) A |-> !Y
    );

// B high forces Y low.
    check_b_high_forces_y_low: assert property (
        @(posedge clk) B |-> !Y
    );

// C_N low forces Y low.
    check_c_n_low_forces_y_low: assert property (
        @(posedge clk) !C_N |-> !Y
    );

// With all three active inputs, Y is high.
    check_all_active_inputs_drive_y_high: assert property (
        @(posedge clk) (!A && !B && C_N) |-> Y
    );

// Y high implies all three active inputs are present.
    check_y_high_requires_all_active_inputs: assert property (
        @(posedge clk) Y |-> (!A && !B && C_N)
    );

// When a > b, comparison_result equals a and input_selected is 00.
    check_select_a_when_a_gt_b: assert property (
        @(posedge clk) (a > b) |-> (comparison_result == a) && (input_selected == 2'b00)
    );

// When b > a, comparison_result equals b and input_selected is 01.
    check_select_b_when_b_gt_a: assert property (
        @(posedge clk) (b > a) |-> (comparison_result == b) && (input_selected == 2'b01)
    );

// When a == b, comparison_result equals a and input_selected equals select.
    check_select_select_when_equal: assert property (
        @(posedge clk) (a == b) |-> (comparison_result == a) && (input_selected == select)
    );

// comparison_result always matches the RTL's selected input.
    check_result_matches_selected_input: assert property (
        @(posedge clk) (comparison_result == ((a > b) ? a : b))
    );

// input_selected is 10 or 11 only when a == b.
    check_input_selected_high_only_when_equal: assert property (
        @(posedge clk) ((input_selected == 2'b10) || (input_selected == 2'b11)) |-> (a == b)
    );

// When a > b, input_selected is 00.
    check_input_selected_00_when_a_gt_b: assert property (
        @(posedge clk) (a > b) |-> (input_selected == 2'b00)
    );

// When b > a, input_selected is 01.
    check_input_selected_01_when_b_gt_a: assert property (
        @(posedge clk) (b > a) |-> (input_selected == 2'b01)
    );

// When a == b, input_selected equals select.
    check_input_selected_matches_select_when_equal: assert property (
        @(posedge clk) (a == b) |-> (input_selected == select)
    );

// When sel_b1 is low, parity matches the XOR of data_in bits.
    check_sel_low_function: assert property (
        @(posedge clk) !sel_b1 |-> (parity == data_in[0] ^ data_in[1] ^ data_in[2] ^ data_in[3] ^ data_in[4] ^ data_in[5] ^ data_in[6] ^ data_in[7])
    );

// When sel_b1 is high, parity is the inverted XOR of data_in bits.
    check_sel_high_function: assert property (
        @(posedge clk) sel_b1 |-> (parity == ~(data_in[0] ^ data_in[1] ^ data_in[2] ^ data_in[3] ^ data_in[4] ^ data_in[5] ^ data_in[6] ^ data_in[7]))
    );

// Parity is always the selected parity function of the input bits.
    check_selected_parity_function: assert property (
        @(posedge clk) parity == (sel_b1 ? ~(data_in[0] ^ data_in[1] ^ data_in[2] ^ data_in[3] ^ data_in[4] ^ data_in[5] ^ data_in[6] ^ data_in[7]) : (data_in[0] ^ data_in[1] ^ data_in[2] ^ data_in[3] ^ data_in[4] ^ data_in[5] ^ data_in[6] ^ data_in[7]))
    );

// Scan mode loads q from si on the next cycle.
    check_scan_loads_q: assert property (
        @(posedge clk) se |=> (q == $past(si))
    );

// Scan mode has priority over reset when both are asserted.
    check_scan_priority_over_reset: assert property (
        @(posedge clk) (se && rst) |=> (q == $past(si))
    );

// Scan mode has priority over enable when both are asserted.
    check_scan_priority_over_enable: assert property (
        @(posedge clk) (se && en) |=> (q == $past(si))
    );

// Reset drives q low when scan and enable are both low.
    check_reset_clears_q: assert property (
        @(posedge clk) (!se && rst) |=> (q == 1'b0)
    );

// Enable loads q from din when scan and reset are both low.
    check_enable_loads_q: assert property (
        @(posedge clk) (!se && !rst && en) |=> (q == $past(din))
    );

// With no control active, q holds its previous value.
    check_hold_when_idle: assert property (
        @(posedge clk) (!se && !rst && !en) |=> (q == $past(q))
    );

// so is a direct copy of q.
    check_so_follows_q: assert property (
        @(posedge clk) (so == q)
    );

// Full 5-bit result matches 4-bit A + 4-bit B + CI.
    check_full_add: assert property (
        @(posedge clk) disable iff (1'b0)
        {CO, S} == ({1'b0, A} + {1'b0, B} + CI)
    );

// Sum bit 0 is the XOR of A[0], B[0], and CI.
    check_sum_bit0: assert property (
        @(posedge clk) disable iff (1'b0)
        S[0] == (A[0] ^ B[0] ^ CI)
    );

// Sum bit 1 uses the carry generated from bit 0.
    check_sum_bit1: assert property (
        @(posedge clk) disable iff (1'b0)
        S[1] == (A[1] ^ B[1] ^ ((A[0] & B[0]) | (B[0] & CI) | (A[0] & CI)))
    );

// Sum bit 2 uses the carry generated from bit 1.
    check_sum_bit2: assert property (
        @(posedge clk) disable iff (1'b0)
        S[2] == (A[2] ^ B[2] ^ (
            (A[1] & B[1]) |
            (B[1] & ((A[0] & B[0]) | (B[0] & CI) | (A[0] & CI))) |
            (A[1] & ((A[0] & B[0]) | (B[0] & CI) | (A[0] & CI)))
        ))
    );

// Y matches the implemented NOR-of-ANDs function.
    check_functional_equivalence: assert property (
        @(posedge clk) Y == ~((B1 & B2) | C1 | (A1 & A2))
    );

// C1 high forces Y low.
    check_c1_forces_low: assert property (
        @(posedge clk) C1 |-> !Y
    );

// A1 and A2 high together force Y low.
    check_a_pair_forces_low: assert property (
        @(posedge clk) (A1 && A2) |-> !Y
    );

// B1 and B2 high together force Y low.
    check_b_pair_forces_low: assert property (
        @(posedge clk) (B1 && B2) |-> !Y
    );

// With no asserted NOR inputs, Y must be high.
    check_no_active_input_sets_high: assert property (
        @(posedge clk) (!C1 && !(A1 && A2) && !(B1 && B2)) |-> Y
    );

// A high Y requires all NOR inputs to be inactive.
    check_high_output_requires_all_inputs_inactive: assert property (
        @(posedge clk) Y |-> (!C1 && !(A1 && A2) && !(B1 && B2))
    );

// X must match the RTL AND equation.
    check_output_equation: assert property (
        @(posedge clk) X == (A1 & ~A2 & ~A3 & ~B1 & ~B2 & ~VPWR & ~VGND & ~VPB & ~VNB)
    );

// A2 high forces X low.
    check_a2_high_clears_x: assert property (
        @(posedge clk) A2 |-> ~X
    );

// A3 high forces X low.
    check_a3_high_clears_x: assert property (
        @(posedge clk) A3 |-> ~X
    );

// B1 high forces X low.
    check_b1_high_clears_x: assert property (
        @(posedge clk) B1 |-> ~X
    );

// B2 high forces X low.
    check_b2_high_clears_x: assert property (
        @(posedge clk) B2 |-> ~X
    );

// VPWR high forces X low.
    check_vpwr_high_clears_x: assert property (
        @(posedge clk) VPWR |-> ~X
    );

// VGND high forces X low.
    check_vgnd_high_clears_x: assert property (
        @(posedge clk) VGND |-> ~X
    );

// VPB high forces X low.
    check_vpb_high_clears_x: assert property (
        @(posedge clk) VPB |-> ~X
    );

// VNB high forces X low.
    check_vnb_high_clears_x: assert property (
        @(posedge clk) VNB |-> ~X
    );

// When sel is 0, out must equal a.
    check_sel0_routes_a: assert property (
        @(posedge clk) (sel == 1'b0) |-> (out == a)
    );

// When sel is 1, out must equal b.
    check_sel1_routes_b: assert property (
        @(posedge clk) (sel == 1'b1) |-> (out == b)
    );

// When a and b are equal, out must equal that value regardless of sel.
    check_equal_inputs_passthrough: assert property (
        @(posedge clk) (a == b) |-> (out == a)
    );

// If a and b differ and sel is 0, out must differ from b.
    check_sel0_differs_from_b: assert property (
        @(posedge clk) (a != b && sel == 1'b0) |-> (out != b)
    );

// If a and b differ and sel is 1, out must differ from a.
    check_sel1_differs_from_a: assert property (
        @(posedge clk) (a != b && sel == 1'b1) |-> (out != a)
    );

// twos_comp equals bitwise NOT of binary plus 1 (4-bit wrap).
    check_twos_comp_definition: assert property (
        @(posedge clk) twos_comp == ((~binary) + 4'b0001)
    );

// Bit1 of twos_comp equals XOR of binary bit1 and carry from bit0.
    check_bit1_xor_with_carry: assert property (
        @(posedge clk) twos_comp[1] == (binary[1] ^ (binary[0] & 1'b1))
    );

// Bit2 of twos_comp equals XOR of binary bit2 and carry from bit1.
    check_bit2_xor_with_carry: assert property (
        @(posedge clk) twos_comp[2] == (binary[2] ^ ((binary[1] & 1'b1) | (binary[0] & 1'b1)))
    );

// Bit3 of twos_comp equals XOR of binary bit3 and carry from bit2.
    check_bit3_xor_with_carry: assert property (
        @(posedge clk) twos_comp[3] == (binary[3] ^ ((binary[2] & 1'b1) | (binary[1] & 1'b1) | (binary[0] & 1'b1)))
    );

// A zero input must produce zero outputs.
    check_zero_input_produces_zero_outputs: assert property (
        @(posedge clk) (in == 16'h0000) |-> ({out_hi, out_lo} == 16'h0000)
    );

// A zero upper byte must produce zero out_hi.
    check_zero_upper_byte_produces_zero_out_hi: assert property (
        @(posedge clk) (in[15:8] == 8'h00) |-> (out_hi == 8'h00)
    );

// A zero lower byte must produce zero out_lo.
    check_zero_lower_byte_produces_zero_out_lo: assert property (
        @(posedge clk) (in[7:0] == 8'h00) |-> (out_lo == 8'h00)
    );

// X must equal the AND of A_N, B_N, C, and D.
    check_function_equivalence: assert property (
        @(posedge clk) X == (A_N & B_N & C & D)
    );

// A_N low forces X low.
    check_a_n_low_forces_x_low: assert property (
        @(posedge clk) !A_N |-> !X
    );

// B_N low forces X low.
    check_b_n_low_forces_x_low: assert property (
        @(posedge clk) !B_N |-> !X
    );

// C low forces X low.
    check_c_low_forces_x_low: assert property (
        @(posedge clk) !C |-> !X
    );

// D low forces X low.
    check_d_low_forces_x_low: assert property (
        @(posedge clk) !D |-> !X
    );

// All inputs high drive X high.
    check_all_inputs_high_drive_x_high: assert property (
        @(posedge clk) (A_N && B_N && C && D) |-> X
    );

// X high implies all inputs are high.
    check_x_high_implies_all_inputs_high: assert property (
        @(posedge clk) X |-> (A_N && B_N && C && D)
    );

// When sel is 0, out captures in1 on the next clock.
    check_sel0_captures_in1: assert property (
        @(posedge clk) (sel == 1'b0) |=> (out == $past(in1))
    );

// When sel is 1, out captures in2 on the next clock.
    check_sel1_captures_in2: assert property (
        @(posedge clk) (sel == 1'b1) |=> (out == $past(in2))
    );

// If both inputs are equal, out matches that value on the next clock.
    check_equal_inputs_match: assert property (
        @(posedge clk) (in1 == in2) |=> (out == $past(in1))
    );

// If sel toggles between consecutive clocks, out follows the current select.
    check_toggle_follows_sel: assert property (
        @(posedge clk) $past(sel) != sel |=> (out == ($past(sel) ? $past(in2) : $past(in1)))
    );

// No RTL clock or reset; sample this combinational logic on clk.

    // When sel1 and sel0 are both high, out must equal in3.
    check_sel3_path: assert property (
        @(posedge clk) (sel1 && sel0) |-> (out == in3)
    );

// When sel1 is high and sel0 is low, out must equal in2.
    check_sel2_path: assert property (
        @(posedge clk) (sel1 && !sel0) |-> (out == in2)
    );

// When sel1 is low and sel0 is high, out must equal in1.
    check_sel1_path: assert property (
        @(posedge clk) (!sel1 && sel0) |-> (out == in1)
    );

// When both select bits are low, out must equal in0.
    check_sel0_path: assert property (
        @(posedge clk) (!sel1 && !sel0) |-> (out == in0)
    );

// Out must always match the RTL's full combinational equation.
    check_full_equation: assert property (
        @(posedge clk) out == (sel1 & sel0 ? in3 : sel1 & ~sel0 ? in2 : ~sel1 & sel0 ? in1 : in0)
    );

// ge3_free and input_tm_cnt==3 select 3.
    check_ge3_selects_3: assert property (
        @(posedge clk) (ge3_free && (input_tm_cnt == 2'd3)) |-> (fifo_wrptr_inc == 4'd3)
    );

// When ge3_free and input_tm_cnt==3, ge2_free has no effect.
    check_ge3_overrides_ge2: assert property (
        @(posedge clk) (ge3_free && (input_tm_cnt == 2'd3) && ge2_free) |-> (fifo_wrptr_inc == 4'd3)
    );

// When ge2_free and input_tm_cnt>=2, input_tm_cnt==1 selects 1.
    check_ge2_overrides_tm1: assert property (
        @(posedge clk) (ge2_free && (input_tm_cnt >= 2'd2) && (input_tm_cnt == 2'd1)) |-> (fifo_wrptr_inc == 4'd1)
    );

// input_tm_cnt>=1 selects 1 when neither ge2_free nor ge3_free is asserted.
    check_tm1_selects_1_without_ge: assert property (
        @(posedge clk) ((input_tm_cnt >= 2'd1) && !ge2_free && !ge3_free) |-> (fifo_wrptr_inc == 4'd1)
    );

// input_tm_cnt==0 selects 0 when neither ge2_free nor ge3_free is asserted.
    check_tm0_selects_0_without_ge: assert property (
        @(posedge clk) ((input_tm_cnt == 2'd0) && !ge2_free && !ge3_free) |-> (fifo_wrptr_inc == 4'd0)
    );

// When neither ge2_free nor ge3_free is asserted, output is 0 or 1.
    check_without_ge_is_0_or_1: assert property (
        @(posedge clk) (!ge2_free && !ge3_free) |-> (fifo_wrptr_inc == 4'd0 || fifo_wrptr_inc == 4'd1)
    );

// When ge3_free is asserted, output is 0, 1, 2, or 3.
    check_ge3_bounds: assert property (
        @(posedge clk) ge3_free |-> (fifo_wrptr_inc == 4'd0 || fifo_wrptr_inc == 4'd1 || fifo_wrptr_inc == 4'd2 || fifo_wrptr_inc == 4'd3)
    );

// The upper 16 bits of sum match the selected upper 16-bit adder result.
    check_upper_half_sum: assert property (
        @(posedge clk) sum[31:16] == (a[31:16] + b[31:16])
    );

// When the lower half carry is zero, the upper half uses the zero-carry adder.
    check_upper_half_zero_carry: assert property (
        @(posedge clk) !((a[15:0] + b[15:0]) >= 16'h10000) |-> (sum[31:16] == (a[31:16] + b[31:16]))
    );

// Adding equal 16-bit operands with zero carry-out produces a doubled value.
    check_equal_operands_no_carry: assert property (
        @(posedge clk) ((a[15:0] == b[15:0]) && ((a[15:0] + b[15:0]) < 16'h10000)) |-> (sum == {16'h0, (a[15:0] + b[15:0]) << 1})
    );

// When a > b, outputs must be gt=1, lt=0, eq=0.
    check_gt_when_a_gt_b: assert property (
        @(posedge clk) (a > b) |-> (gt == 1'b1 && lt == 1'b0 && eq == 1'b0)
    );

// When a < b, outputs must be gt=0, lt=1, eq=0.
    check_lt_when_a_lt_b: assert property (
        @(posedge clk) (a < b) |-> (gt == 1'b0 && lt == 1'b1 && eq == 1'b0)
    );

// When a == b, outputs must be gt=0, lt=0, eq=1.
    check_eq_when_a_eq_b: assert property (
        @(posedge clk) (a == b) |-> (gt == 1'b0 && lt == 1'b0 && eq == 1'b1)
    );

// gt can only be 1 when a > b.
    check_gt_only_when_a_gt_b: assert property (
        @(posedge clk) (gt == 1'b1) |-> (a > b)
    );

// lt can only be 1 when a < b.
    check_lt_only_when_a_lt_b: assert property (
        @(posedge clk) (lt == 1'b1) |-> (a < b)
    );

// eq can only be 1 when a == b.
    check_eq_only_when_a_eq_b: assert property (
        @(posedge clk) (eq == 1'b1) |-> (a == b)
    );

// Exactly one of {gt,lt,eq} is 1 at all times.
    check_onehot_outputs: assert property (
        @(posedge clk) $onehot({gt, lt, eq})
    );

// Reset clears result on the next clock.
    check_reset_clears_result: assert property (
        @(posedge clk) !reset |=> (result == 4'b0000)
    );

// In add mode, result captures A + B on the next clock.
    check_add_mode_result: assert property (
        @(posedge clk) disable iff (!reset)
        (operation == 1'b0) |=> (result == ($past(A) + $past(B)))
    );

// In subtract mode, result captures A - B on the next clock.
    check_sub_mode_result: assert property (
        @(posedge clk) disable iff (!reset)
        (operation == 1'b1) |=> (result == ($past(A) - $past(B)))
    );

// In add mode with B == 0, result holds A on the next clock.
    check_add_identity: assert property (
        @(posedge clk) disable iff (!reset)
        (operation == 1'b0 && B == 4'b0000) |=> (result == $past(A))
    );

// In subtract mode with B == 0, result holds A on the next clock.
    check_sub_identity: assert property (
        @(posedge clk) disable iff (!reset)
        (operation == 1'b1 && B == 4'b0000) |=> (result == $past(A))
    );

// In add mode with A == 0, result holds B on the next clock.
    check_add_zero_a: assert property (
        @(posedge clk) disable iff (!reset)
        (operation == 1'b0 && A == 4'b0000) |=> (result == $past(B))
    );

// In subtract mode with A == 0, result is -B (2's complement) on the next clock.
    check_sub_zero_a: assert property (
        @(posedge clk) disable iff (!reset)
        (operation == 1'b1 && A == 4'b0000) |=> (result == ~$past(B) + 4'b0001)
    );

// C must be 00 when A equals B.
    check_equal_maps_zero: assert property (
        @(posedge clk) (A == B) |-> (C == 2'b00)
    );

// C must be 01 when A is greater than B.
    check_greater_maps_one: assert property (
        @(posedge clk) (A > B) |-> (C == 2'b01)
    );

// C must be 10 when A is less than B.
    check_less_maps_two: assert property (
        @(posedge clk) (A < B) |-> (C == 2'b10)
    );

// C must never be 11.
    check_no_invalid_code: assert property (
        @(posedge clk) (C != 2'b11)
    );

// C must always match the RTL comparison result.
    check_functional_equivalence: assert property (
        @(posedge clk) C == (A == B ? 2'b00 : (A > B ? 2'b01 : 2'b10))
    );

// Reset clears the counter on the next cycle.
    check_reset_clears_count: assert property (
        @(posedge clk) reset |=> (count == 4'b0000)
    );

// Load captures the current count value.
    check_load_captures_count: assert property (
        @(posedge clk) disable iff (reset)
        load |=> (count == $past(count))
    );

// Up mode increments the counter by one.
    check_up_mode_increments: assert property (
        @(posedge clk) disable iff (reset)
        (!load && up_down) |=> (count == ($past(count) + 4'b0001))
    );

// Down mode decrements the counter by one.
    check_down_mode_decrements: assert property (
        @(posedge clk) disable iff (reset)
        (!load && !up_down) |=> (count == ($past(count) - 4'b0001))
    );

// The 4-bit counter wraps from 15 to 0 in up mode.
    check_up_wraparound: assert property (
        @(posedge clk) disable iff (reset)
        (!load && up_down && (count == 4'hF)) |=> (count == 4'h0)
    );

// The 4-bit counter wraps from 0 to 15 in down mode.
    check_down_wraparound: assert property (
        @(posedge clk) disable iff (reset)
        (!load && !up_down && (count == 4'h0)) |=> (count == 4'hF)
    );

// Result equals the selected operation (add/sub) when sampled on clk.
    check_result_function: assert property (
        @(posedge clk) result == (op ? (a - b) : (a + b))
    );

// Overflow is 0 on the next clock when the RTL does not detect an overflow condition.
    check_overflow_clear_when_no_overflow: assert property (
        @(posedge clk) disable iff (1'b0)
            !((result[7] == 1 && op == 1'b0 && a[7] == 1'b1 && b[7] == 1'b1) ||
              (result[7] == 1'b1 && op == 1'b1 && a[7] == 1'b0 && b[7] == 1'b1) ||
              (result[7] == 1'b0 && op == 1'b1 && a[7] == 1'b1 && b[7] == 1'b0))
            |=> (overflow == 1'b0)
    );

// Overflow is 1 on the next clock when the RTL detects an overflow condition.
    check_overflow_set_when_overflow: assert property (
        @(posedge clk) disable iff (1'b0)
            ((result[7] == 1 && op == 1'b0 && a[7] == 1'b1 && b[7] == 1'b1) ||
             (result[7] == 1'b1 && op == 1'b1 && a[7] == 1'b0 && b[7] == 1'b1) ||
             (result[7] == 1'b0 && op == 1'b1 && a[7] == 1'b1 && b[7] == 1'b0))
            |=> (overflow == 1'b1)
    );

// Reset clears the register on the next sampled cycle.
    check_reset_clears_out: assert property (
        @(posedge CLK) reset |=> (out == 4'd0)
    );

// When not in reset, the next sampled output equals the previous cycle's inputs.
    check_addition_when_not_reset: assert property (
        @(posedge CLK) disable iff (reset) 1'b1 |=> (out == ($past(in1) + $past(in2)))
    );

// Zero on in1 passes in2 through on the next sampled cycle.
    check_zero_in1_passthrough: assert property (
        @(posedge CLK) disable iff (reset) (in1 == 4'd0) |=> (out == $past(in2))
    );

// Zero on in2 passes in1 through on the next sampled cycle.
    check_zero_in2_passthrough: assert property (
        @(posedge CLK) disable iff (reset) (in2 == 4'd0) |=> (out == $past(in1))
    );

// Mode 00 shifts left by 1 and inserts 0 in bit 0.
    check_mode_00_shift_left: assert property (
        @(posedge clk) (mode == 2'b00) |-> (out == {in[2:0], 1'b0})
    );

// Mode 01 shifts right by 1 and inserts 0 in bit 3.
    check_mode_01_shift_right: assert property (
        @(posedge clk) (mode == 2'b01) |-> (out == {1'b0, in[3:1]})
    );

// Mode 10 inverts all four input bits.
    check_mode_10_invert: assert property (
        @(posedge clk) (mode == 2'b10) |-> (out == ~in)
    );

// Mode 11 passes the input through unchanged.
    check_mode_11_passthrough: assert property (
        @(posedge clk) (mode == 2'b11) |-> (out == in)
    );

// Default case (invalid mode) drives zero.
    check_default_zero: assert property (
        @(posedge clk) (mode != 2'b00 && mode != 2'b01 && mode != 2'b10 && mode != 2'b11) |-> (out == 4'b0000)
    );

// X matches the implemented OR-then-AND function.
    check_function_equivalence: assert property (
        @(posedge clk) X == (B1 & (A1 | A2 | A3))
    );

// B1 low forces X low.
    check_b1_low_forces_x_low: assert property (
        @(posedge clk) !B1 |-> !X
    );

// Any asserted A input with B1 high drives X high.
    check_any_a_with_b1_high_drives_x_high: assert property (
        @(posedge clk) (B1 & (A1 | A2 | A3)) |-> X
    );

// X high requires B1 to be high.
    check_x_high_requires_b1_high: assert property (
        @(posedge clk) X |-> B1
    );

// X high requires at least one A input to be high.
    check_x_high_requires_any_a_high: assert property (
        @(posedge clk) X |-> (A1 | A2 | A3)
    );

// Reset drives count to zero on the next clock.
    check_reset_clears_count: assert property (
        @(posedge clk) rst |=> (count == 4'b0000)
    );

// When not in reset, count increments by one each cycle.
    check_count_increments: assert property (
        @(posedge clk) disable iff (rst) 1'b1 |=> (count == ($past(count) + 4'd1))
    );

// Count wraps from 15 back to 0 when not in reset.
    check_count_wraps: assert property (
        @(posedge clk) disable iff (rst) (count == 4'hF) |=> (count == 4'h0)
    );

// S captures the upper nibble of m_payload_i_reg on the next cycle.
    check_s_capture: assert property (
        @(posedge aclk) si_rs_awvalid |=> (S == $past(m_payload_i_reg[47:44]))
    );

// S holds its value when si_rs_awvalid is low.
    check_s_hold: assert property (
        @(posedge aclk) !si_rs_awvalid |=> (S == $past(S))
    );

// next_pending_r_reg is set to 1 on the next cycle when next is high.
    check_next_pending_set: assert property (
        @(posedge aclk) next |=> (next_pending_r_reg == 1'b1)
    );

// m_axi_awaddr increments by axaddr_incr on the next cycle when axaddr_incr is non-zero.
    check_awaddr_increment: assert property (
        @(posedge aclk) (axaddr_incr != 12'h000) |=> (m_axi_awaddr == ($past(m_axi_awaddr) + $past(axaddr_incr)))
    );

// m_axi_awaddr holds its value when axaddr_incr is zero.
    check_awaddr_hold: assert property (
        @(posedge aclk) (axaddr_incr == 12'h000) |=> (m_axi_awaddr == $past(m_axi_awaddr))
    );

// X equals A | B | C.
    check_or_function: assert property (
        @(posedge clk) X == (A | B | C)
    );

// If all inputs are 0, X must be 0.
    check_all_zero_implies_x_zero: assert property (
        @(posedge clk) (!A && !B && !C) |-> (X == 1'b0)
    );

// If any input is 1, X must be 1.
    check_any_one_implies_x_one: assert property (
        @(posedge clk) (A || B || C) |-> (X == 1'b1)
    );

// A rising edge on X implies at least one input is 1.
    check_x_rise_requires_any_one: assert property (
        @(posedge clk) $rose(X) |-> (A || B || C)
    );

// A falling edge on X implies all inputs are 0.
    check_x_fall_requires_all_zero: assert property (
        @(posedge clk) $fell(X) |-> (!A && !B && !C)
    );

// d_out_1 is the registered input on the next clock.
    check_d_out_1_captures_d_in: assert property (
        @(posedge clk) disable iff (!reset) 1'b1 |=> (d_out_1 == $past(d_in))
    );

// d_out_2 is the registered toggle of the previous d_out_1 and current d_in.
    check_d_out_2_captures_toggle: assert property (
        @(posedge clk) disable iff (!reset) 1'b1 |=> (d_out_2 == ($past(d_out_1) ^ d_in))
    );

// A low reset keeps both outputs low on the next clock.
    check_reset_clears_outputs: assert property (
        @(posedge clk) !reset |=> (d_out_1 == 1'b0) && (d_out_2 == 1'b0)
    );

// A high d_out_2 indicates the previous d_out_1 and current d_in differ.
    check_d_out_2_high_means_toggle: assert property (
        @(posedge clk) disable iff (!reset) 1'b1 |=> (d_out_2 == 1'b1) |-> ($past(d_out_1) != d_in)
    );

// A low d_out_2 indicates the previous d_out_1 and current d_in are equal.
    check_d_out_2_low_means_no_toggle: assert property (
        @(posedge clk) disable iff (!reset) 1'b1 |=> (d_out_2 == 1'b0) |-> ($past(d_out_1) == d_in)
    );

// Sum must match the 5-bit addition of a, b, and cin.
    check_full_sum: assert property (
        @(posedge clk) {cout, s} == ({1'b0, a} + {1'b0, b} + cin)
    );

// s must match the lower 4 bits of the addition result.
    check_sum_bits: assert property (
        @(posedge clk) s == (({1'b0, a} + {1'b0, b} + cin) & 4'hF)
    );

// cout must match the carry-out bit of the addition.
    check_carry_out: assert property (
        @(posedge clk) cout == (({1'b0, a} + {1'b0, b} + cin) > 5'd15)
    );

// Zero inputs must produce a zero sum and no carry.
    check_zero_case: assert property (
        @(posedge clk) (a == 4'h0 && b == 4'h0 && cin == 1'b0) |-> (s == 4'h0 && cout == 1'b0)
    );

// Maximum inputs must produce 4'hF with carry-out asserted.
    check_max_case: assert property (
        @(posedge clk) (a == 4'hF && b == 4'hF && cin == 1'b1) |-> (s == 4'hF && cout == 1'b1)
    );

// sum[7:0] equals A + B (8-bit wrap).
    check_sum_low_byte: assert property (
        @(posedge clk) sum[7:0] == (A + B)
    );

// sum equals {carry, A + B} (8-bit plus 1-bit).
    check_sum_vector: assert property (
        @(posedge clk) sum == {carry, (A + B)}
    );

// When A + B < 256, carry is 0 and sum equals A + B.
    check_no_carry_case: assert property (
        @(posedge clk) (A + B) < 8'h100 |-> (carry == 1'b0 && sum == (A + B))
    );

// If A is 0, sum equals B and carry is 0.
    check_zero_a_case: assert property (
        @(posedge clk) (A == 8'h00) |-> (sum == B && carry == 1'b0)
    );

// If B is 0, sum equals A and carry is 0.
    check_zero_b_case: assert property (
        @(posedge clk) (B == 8'h00) |-> (sum == A && carry == 1'b0)
    );

// out_bit_def is high when the upper nibble has 4 or more ones.
    check_def_high_when_upper_nibble_ge4: assert property (
        @(posedge clk) (|data[7:4] >= 4'b1000) |-> (out_bit_def == 1'b1)
    );

// out_bit_ovr follows data[4].
    check_ovr_follows_data4: assert property (
        @(posedge clk) (out_bit_ovr == data[4])
    );

// A low out_bit_def requires the upper nibble to have fewer than 4 ones.
    check_def0_implies_upper_nibble_lt4: assert property (
        @(posedge clk) (out_bit_def == 1'b0) |-> (|data[7:4] < 4'b1000)
    );

// A high out_bit_ovr requires data[4] to be high.
    check_ovr1_implies_data4: assert property (
        @(posedge clk) (out_bit_ovr == 1'b1) |-> (data[4] == 1'b1)
    );

// A low out_bit_ovr requires data[4] to be low.
    check_ovr0_implies_data4: assert property (
        @(posedge clk) (out_bit_ovr == 1'b0) |-> (data[4] == 1'b0)
    );

// A and B high with EN high drive Z high.
    check_ab_high_with_en_high_drives_z_high: assert property (
        @(posedge clk) (A && B && EN) |-> (Z == 1'b1)
    );

// A low forces Z low.
    check_a_low_forces_z_low: assert property (
        @(posedge clk) !A |-> (Z == 1'b0)
    );

// B low forces Z low.
    check_b_low_forces_z_low: assert property (
        @(posedge clk) !B |-> (Z == 1'b0)
    );

// With EN high, Z equals A & B.
    check_en_high_reduces_to_and: assert property (
        @(posedge clk) EN |-> (Z == (A & B))
    );

// With EN high, a high Z requires A and B high.
    check_en_high_and_z_high_requires_ab_high: assert property (
        @(posedge clk) (EN && Z) |-> (A && B)
    );

// Sum output matches the three-input XOR of the inputs.
    check_sum_function: assert property (
        @(posedge clk) S == (A ^ B ^ Ci)
    );

// Carry output matches the implemented carry equation.
    check_carry_function: assert property (
        @(posedge clk) Co == ((A & B) | ((A ^ B) & Ci))
    );

// All-zero inputs produce zero sum and zero carry.
    check_zero_case: assert property (
        @(posedge clk) (!A && !B && !Ci) |-> (!S && !Co)
    );

// Any single high input produces sum high and carry low.
    check_single_high_case: assert property (
        @(posedge clk)
        ((A && !B && !Ci) || (!A && B && !Ci) || (!A && !B && Ci))
        |-> (S && !Co)
    );

// Any two high inputs produce sum low and carry high.
    check_two_high_case: assert property (
        @(posedge clk)
        ((A && B && !Ci) || (A && !B && Ci) || (!A && B && Ci))
        |-> (!S && Co)
    );

// All-high inputs produce sum high and carry high.
    check_all_high_case: assert property (
        @(posedge clk) (A && B && Ci) |-> (S && Co)
    );

// Reset clears the counter on the next clock.
    check_reset_clears_count: assert property (
        @(posedge clk) reset |=> (count == 4'b0000)
    );

// When enabled, the counter increments by one on the next clock.
    check_count_increments_when_enabled: assert property (
        @(posedge clk) disable iff (reset)
        enable |=> (count == ($past(count) + 4'd1))
    );

// When not enabled, the counter holds its value on the next clock.
    check_count_holds_when_disabled: assert property (
        @(posedge clk) disable iff (reset)
        !enable |=> (count == $past(count))
    );

// The 4-bit counter wraps from 15 back to 0 when enabled.
    check_count_wraps_from_max: assert property (
        @(posedge clk) disable iff (reset)
        (enable && (count == 4'hF)) |=> (count == 4'h0)
    );

// Clear low forces the counter to zero.
    check_clear_forces_zero: assert property (
        @(posedge clk) !clear |-> (count_out == 4'b0000)
    );

// Load captures data_in when clear is high and load is high.
    check_load_captures_data: assert property (
        @(posedge clk) disable iff (!clear) (load == 1'b1) |=> (count_out == $past(data_in))
    );

// Up mode increments the counter when clear and load are high.
    check_up_mode_increments: assert property (
        @(posedge clk) disable iff (!clear) (load == 1'b0) && (up_down == 1'b1) |=> (count_out == ($past(count_out) + 4'b0001))
    );

// Down mode decrements the counter when clear and load are high.
    check_down_mode_decrements: assert property (
        @(posedge clk) disable iff (!clear) (load == 1'b0) && (up_down == 1'b0) |=> (count_out == ($past(count_out) - 4'b0001))
    );

// Incrementing from 4'hF wraps to 4'h0.
    check_up_wrap_from_max: assert property (
        @(posedge clk) disable iff (!clear) (load == 1'b0) && (up_down == 1'b1) && (count_out == 4'hF) |=> (count_out == 4'h0)
    );

// Decrementing from 4'h0 wraps to 4'hF.
    check_down_wrap_from_zero: assert property (
        @(posedge clk) disable iff (!clear) (load == 1'b0) && (up_down == 1'b0) && (count_out == 4'h0) |=> (count_out == 4'hF)
    );

// Clock: C (posedge). Reset: R (active-low, asynchronous). Sequential DFF with reset.

    // When reset is asserted low at a clock edge, Q must be 0 on the next clock.
    reset_clears_next: assert property (
        @(posedge C) !R |=> (Q == 1'b0)
    );

// If reset is low in consecutive cycles, Q is 0 in the later cycle.
    reset_holds_zero: assert property (
        @(posedge C) (!R && $past(!R)) |=> (Q == 1'b0)
    );

// With reset high, Q captures D on the next clock.
    capture_d_when_reset_high: assert property (
        @(posedge C) disable iff (!R) 1'b1 |=> (Q == $past(D))
    );

// With reset high, Q holds its value when D equals current Q.
    hold_when_d_equals_q: assert property (
        @(posedge C) disable iff (!R) (D == Q) |=> (Q == $past(Q))
    );

// With reset high, Q changes to D when D differs from current Q.
    change_when_d_differs: assert property (
        @(posedge C) disable iff (!R) (D != Q) |=> (Q == $past(D))
    );

// Reset drives the counter to 000 on the next clock.
    check_reset_clears_to_zero: assert property (
        @(posedge clk) reset |=> (out == 3'b000)
    );

// With reset low, the counter rotates left by one bit.
    check_rotate_left_when_not_reset: assert property (
        @(posedge clk) disable iff (reset)
        1'b1 |=> (out == {$past(out[1:0]), $past(out[2])})
    );

// The full 3-bit vector rotates left by one bit.
    check_vector_rotate_left: assert property (
        @(posedge clk) disable iff (reset)
        1'b1 |=> (out == {$past(out[1:0]), $past(out[2])})
    );

// Reset clears all ME stage registers and sets me_instr to 32'b100000.
    check_reset_clears_outputs: assert property (
        @(posedge clk) rst |-> (me_aluresult == 32'h0) &&
                             (me_d2 == 32'h0) &&
                             (me_td == 5'h0) &&
                             (me_WREG == 1'b0) &&
                             (me_WMEM == 1'b0) &&
                             (me_LW == 1'b0) &&
                             (me_instr == 32'h100000)
    );

// me_aluresult captures ex_aluresult on the next cycle.
    check_aluresult_pipeline: assert property (
        @(posedge clk) disable iff (rst) 1'b1 |=> (me_aluresult == $past(ex_aluresult))
    );

// me_d2 captures ex_d2 on the next cycle.
    check_d2_pipeline: assert property (
        @(posedge clk) disable iff (rst) 1'b1 |=> (me_d2 == $past(ex_d2))
    );

// me_td captures ex_td on the next cycle.
    check_td_pipeline: assert property (
        @(posedge clk) disable iff (rst) 1'b1 |=> (me_td == $past(ex_td))
    );

// me_WREG captures ex_WREG on the next cycle.
    check_wreg_pipeline: assert property (
        @(posedge clk) disable iff (rst) 1'b1 |=> (me_WREG == $past(ex_WREG))
    );

// me_WMEM captures ex_WMEM on the next cycle.
    check_wmem_pipeline: assert property (
        @(posedge clk) disable iff (rst) 1'b1 |=> (me_WMEM == $past(ex_WMEM))
    );

// me_LW captures ex_LW on the next cycle.
    check_lw_pipeline: assert property (
        @(posedge clk) disable iff (rst) 1'b1 |=> (me_LW == $past(ex_LW))
    );

// me_instr captures ex_instr on the next cycle.
    check_instr_pipeline: assert property (
        @(posedge clk) disable iff (rst) 1'b1 |=> (me_instr == $past(ex_instr))
    );

// Sum bits match the low 8 bits of A+B.
    check_sum_bits: assert property (
        @(posedge CLK) S == (A + B)
    );

// Zero plus zero produces zero with no carry.
    check_zero_plus_zero: assert property (
        @(posedge CLK) (A == 8'h00 && B == 8'h00) |-> (S == 8'h00 && C_out == 1'b0)
    );

// Adding zero on A passes B through with no carry.
    check_zero_on_a: assert property (
        @(posedge CLK) (A == 8'h00) |-> (S == B && C_out == 1'b0)
    );

// Adding zero on B passes A through with no carry.
    check_zero_on_b: assert property (
        @(posedge CLK) (B == 8'h00) |-> (S == A && C_out == 1'b0)
    );

// X matches the implemented OR-of-NAND function.
    check_functional_equivalence: assert property (
        @(posedge clk) X == (A | B | ~(C_N & D_N))
    );

// A high forces X high.
    check_a_forces_x_high: assert property (
        @(posedge clk) A |-> X
    );

// B high forces X high.
    check_b_forces_x_high: assert property (
        @(posedge clk) B |-> X
    );

// C_N low with D_N low forces X high.
    check_c_n_and_d_n_low_force_x_high: assert property (
        @(posedge clk) (!C_N && !D_N) |-> X
    );

// With A and B low, X reduces to the NAND term.
    check_ab_low_reduces_to_nand_term: assert property (
        @(posedge clk) (!A && !B) |-> (X == ~(C_N & D_N))
    );

// With C_N and D_N high, X reduces to A OR B.
    check_cd_n_high_reduces_to_or: assert property (
        @(posedge clk) (C_N && D_N) |-> (X == (A | B))
    );

// A high C_N and D_N force X low when A and B are low.
    check_cd_n_high_and_ab_low_force_x_low: assert property (
        @(posedge clk) (C_N && D_N && !A && !B) |-> (!X)
    );

// A low C_N forces X high when A and B are low.
    check_c_n_low_forces_x_high_when_ab_low: assert property (
        @(posedge clk) (!C_N && !A && !B) |-> X
    );

// A low D_N forces X high when A and B are low.
    check_d_n_low_forces_x_high_when_ab_low: assert property (
        @(posedge clk) (!D_N && !A && !B) |-> X
    );

// Reset forces ENCLK low on the next clock.
    check_reset_clears_enclk: assert property (
        @(posedge CLK) RST |=> (ENCLK == 1'b0)
    );

// TE high with EN high loads ENCLK high on the next clock.
    check_enable_loads_high: assert property (
        @(posedge CLK) disable iff (RST) TE && EN |=> (ENCLK == 1'b1)
    );

// TE high with EN low loads ENCLK low on the next clock.
    check_enable_loads_low: assert property (
        @(posedge CLK) disable iff (RST) TE && !EN |=> (ENCLK == 1'b0)
    );

// TE low holds ENCLK high when it was high.
    check_hold_high_when_te_low: assert property (
        @(posedge CLK) disable iff (RST) !TE && ENCLK |=> (ENCLK == 1'b1)
    );

// TE low holds ENCLK low when it was low.
    check_hold_low_when_te_low: assert property (
        @(posedge CLK) disable iff (RST) !TE && !ENCLK |=> (ENCLK == 1'b0)
    );

// Sum is the 4-bit result of A + B + Cin from the previous cycle.
    check_sum_registered: assert property (
        @(posedge Clock) 1'b1 |=> (Sum == ($past(A) + $past(B) + $past(Cin)))
    );

// Cout is the carry-out from the previous cycle's addition.
    check_cout_registered: assert property (
        @(posedge Clock) 1'b1 |=> (Cout == (({1'b0, $past(A)} + {1'b0, $past(B)} + $past(Cin)) >= 5'd16))
    );

// Zero inputs produce zero outputs on the next cycle.
    check_zero_case: assert property (
        @(posedge Clock) (A == 4'h0 && B == 4'h0 && Cin == 1'b0) |=> (Sum == 4'h0 && Cout == 1'b0)
    );

// Maximum inputs produce 4'hF and carry-out on the next cycle.
    check_max_case: assert property (
        @(posedge Clock) (A == 4'hF && B == 4'hF && Cin == 1'b1) |=> (Sum == 4'hF && Cout == 1'b1)
    );

// B1 high forces Y low.
    check_b1_forces_low: assert property (
        @(posedge clk) B1 |-> !Y
    );

// A1 and A2 high together force Y low.
    check_a1_a2_high_force_low: assert property (
        @(posedge clk) (A1 && A2) |-> !Y
    );

// A low Y requires B1 high or A1 and A2 high.
    check_low_output_has_cause: assert property (
        @(posedge clk) !Y |-> (B1 || (A1 && A2))
    );

// sel=00 routes in[0] to out.
    check_sel_00_routes_in0: assert property (
        @(posedge clk) (sel == 2'b00) |-> (out == in[0])
    );

// sel=01 routes in[1] to out.
    check_sel_01_routes_in1: assert property (
        @(posedge clk) (sel == 2'b01) |-> (out == in[1])
    );

// sel=10 routes in[2] to out.
    check_sel_10_routes_in2: assert property (
        @(posedge clk) (sel == 2'b10) |-> (out == in[2])
    );

// sel=11 routes in[3] to out.
    check_sel_11_routes_in3: assert property (
        @(posedge clk) (sel == 2'b11) |-> (out == in[3])
    );

// Z must equal the AND of A, B, and C.
    check_and_function: assert property (
        @(posedge clk) Z == (A & B & C)
    );

// A high, B high, and C high must drive Z high.
    check_all_high_drives_z_high: assert property (
        @(posedge clk) (A && B && C) |-> Z
    );

// A low must force Z low.
    check_a_low_forces_z_low: assert property (
        @(posedge clk) !A |-> !Z
    );

// B low must force Z low.
    check_b_low_forces_z_low: assert property (
        @(posedge clk) !B |-> !Z
    );

// C low must force Z low.
    check_c_low_forces_z_low: assert property (
        @(posedge clk) !C |-> !Z
    );

// Z high implies all three inputs are high.
    check_z_high_requires_all_high: assert property (
        @(posedge clk) Z |-> (A && B && C)
    );

// out_mux selects data0 when sel==0.
    check_mux_sel_0: assert property (
        @(posedge clk) (sel == 3'd0) |-> (out_mux == data0)
    );

// out_mux selects data1 when sel==1.
    check_mux_sel_1: assert property (
        @(posedge clk) (sel == 3'd1) |-> (out_mux == data1)
    );

// out_mux selects data2 when sel==2.
    check_mux_sel_2: assert property (
        @(posedge clk) (sel == 3'd2) |-> (out_mux == data2)
    );

// out_mux selects data3 when sel==3.
    check_mux_sel_3: assert property (
        @(posedge clk) (sel == 3'd3) |-> (out_mux == data3)
    );

// out_mux selects data4 when sel==4.
    check_mux_sel_4: assert property (
        @(posedge clk) (sel == 3'd4) |-> (out_mux == data4)
    );

// out_mux selects data5 when sel==5.
    check_mux_sel_5: assert property (
        @(posedge clk) (sel == 3'd5) |-> (out_mux == data5)
    );

// out_mux is zero when sel is 6 or 7.
    check_mux_default_zero: assert property (
        @(posedge clk) (sel >= 3'd6) |-> (out_mux == 4'b0000)
    );

// out_3bit mirrors sel.
    check_out_3bit_passthrough: assert property (
        @(posedge clk) out_3bit == sel
    );

// o2 is the MSB of sel.
    check_o2_passthrough: assert property (
        @(posedge clk) o2 == sel[2]
    );

// o1 is the middle bit of sel.
    check_o1_passthrough: assert property (
        @(posedge clk) o1 == sel[1]
    );

// o0 is the LSB of sel.
    check_o0_passthrough: assert property (
        @(posedge clk) o0 == sel[0]
    );

// final_out lower bits are the sum of mux_out and sel.
    check_final_out_sum: assert property (
        @(posedge clk) final_out[5:0] == (({1'b0, out_mux} + {1'b0, sel}) & 6'h3f)
    );

// S must match the RTL mux expression.
    check_mux_function: assert property (
        @(posedge clk) S == ((ctrl == 2'b00) ? D0 :
                             (ctrl == 2'b01) ? D1 :
                             (ctrl == 2'b10) ? D2 :
                             (ctrl == 2'b11) ? D3 :
                             1'bx)
    );

// ctrl==00 selects D0.
    check_select_00: assert property (
        @(posedge clk) (ctrl == 2'b00) |-> (S == D0)
    );

// ctrl==01 selects D1.
    check_select_01: assert property (
        @(posedge clk) (ctrl == 2'b01) |-> (S == D1)
    );

// ctrl==10 selects D2.
    check_select_10: assert property (
        @(posedge clk) (ctrl == 2'b10) |-> (S == D2)
    );

// ctrl==11 selects D3.
    check_select_11: assert property (
        @(posedge clk) (ctrl == 2'b11) |-> (S == D3)
    );

// Any ctrl value other than 00/01/10/11 drives S to x.
    check_default_x: assert property (
        @(posedge clk) !((ctrl == 2'b00) || (ctrl == 2'b01) || (ctrl == 2'b10) || (ctrl == 2'b11)) |-> (S == 1'bx)
    );

// Load captures in on the next cycle.
    check_load_captures_input: assert property (
        @(posedge clk) load |=> (out == $past(in))
    );

// When not loading, out rotates left by one bit.
    check_shift_left_when_not_loading: assert property (
        @(posedge clk) !load |=> (out == {$past(out[2:0]), $past(out[3])})
    );

// ser_out reflects the previous cycle's MSB.
    check_ser_out_follows_msb: assert property (
        @(posedge clk) 1'b1 |=> (ser_out == $past(out[3]))
    );

// X matches the implemented combinational equation.
    check_function_equivalence: assert property (
        @(posedge clk) X == ((A1 & A2 & ~B1 & ~B2) | (~A1 & ~A2 & B1 & B2))
    );

// When both A inputs are high and both B inputs are low, X must be high.
    check_a_high_b_low_sets_x: assert property (
        @(posedge clk) (A1 & A2 & ~B1 & ~B2) |-> X
    );

// When both A inputs are low and both B inputs are high, X must be high.
    check_a_low_b_high_sets_x: assert property (
        @(posedge clk) (~A1 & ~A2 & B1 & B2) |-> X
    );

// Any mismatch between A and B inputs forces X low.
    check_mismatch_clears_x: assert property (
        @(posedge clk) ((A1 == B1) || (A2 == B2)) |-> !X
    );

// X high implies the implemented input pattern is present.
    check_x_high_has_valid_cause: assert property (
        @(posedge clk) X |-> ((A1 & A2 & ~B1 & ~B2) | (~A1 & ~A2 & B1 & B2))
    );

// out is the registered input value from two cycles ago.
    check_out_registered_two_cycle_delay: assert property (
        @(posedge clk) 1'b1 |=> ##2 (out == $past(in, 2))
    );

// falling and rising are never asserted together.
    check_edge_mutex: assert property (
        @(posedge clk) 1'b1 |=> ##2 !(falling && rising)
    );

// When SEL==00, Y equals A.
    check_sel00_routes_a: assert property (
        @(posedge clk) (SEL == 2'b00) |-> (Y == A)
    );

// When SEL==01, Y equals B.
    check_sel01_routes_b: assert property (
        @(posedge clk) (SEL == 2'b01) |-> (Y == B)
    );

// When SEL==10, Y equals C.
    check_sel10_routes_c: assert property (
        @(posedge clk) (SEL == 2'b10) |-> (Y == C)
    );

// When SEL==11, Y equals D.
    check_sel11_routes_d: assert property (
        @(posedge clk) (SEL == 2'b11) |-> (Y == D)
    );

// Y always matches the selected input.
    check_mux_function: assert property (
        @(posedge clk) Y == ((SEL == 2'b00) ? A :
                             (SEL == 2'b01) ? B :
                             (SEL == 2'b10) ? C : D)
    );

// Q captures SE on the next clock when EN is high.
    check_capture_when_en: assert property (
        @(posedge CK) EN |=> (Q == $past(SE))
    );

// Q holds its value on the next clock when EN is low.
    check_hold_when_en_low: assert property (
        @(posedge CK) !EN |=> (Q == $past(Q))
    );

// Q reflects the previous cycle's SE value when EN is high.
    check_q_matches_prev_se_when_en: assert property (
        @(posedge CK) EN |=> (Q == $past(SE))
    );

// Q reflects the previous cycle's Q value when EN is low.
    check_q_matches_prev_q_when_en_low: assert property (
        @(posedge CK) !EN |=> (Q == $past(Q))
    );

// Reset drives count to zero on the next clock.
    check_reset_clears_count: assert property (
        @(posedge clk) rst |=> (count == 8'h00)
    );

// When not in reset, count increments by one on the next clock.
    check_count_increments: assert property (
        @(posedge clk) disable iff (rst) 1'b1 |=> (count == ($past(count) + 8'd1))
    );

// Count wraps from 255 back to 0 when not in reset.
    check_count_wraps: assert property (
        @(posedge clk) disable iff (rst) (count == 8'hFF) |=> (count == 8'h00)
    );

// out_valid is a direct copy of en.
    check_out_valid_matches_en: assert property (
        @(posedge clk) out_valid == en
    );

// When en is low, out must be low.
    check_out_low_when_en_low: assert property (
        @(posedge clk) !en |-> !out
    );

// When en is high, out equals in1 AND in2.
    check_out_equals_and_when_en_high: assert property (
        @(posedge clk) en |-> (out == (in1 & in2))
    );

// A high out requires both inputs high and en high.
    check_out_high_requires_en_and_inputs: assert property (
        @(posedge clk) out |-> (en && in1 && in2)
    );

// A high en with both inputs high drives out high.
    check_out_high_when_en_and_inputs_high: assert property (
        @(posedge clk) (en && in1 && in2) |-> out
    );

// X must match the RTL combinational equation.
    check_functional_equivalence: assert property (
        @(posedge clk) X == ((A1 | (A2 & ~A3)) & B1)
    );

// A1 high with B1 high must drive X high.
    check_a1_path: assert property (
        @(posedge clk) (A1 && B1) |-> X
    );

// A2 high and A3 low with B1 high must drive X high.
    check_a2_a3_path: assert property (
        @(posedge clk) (A2 && !A3 && B1) |-> X
    );

// B1 low must force X low.
    check_b1_low_forces_x_low: assert property (
        @(posedge clk) !B1 |-> !X
    );

// O matches the implemented sum equation.
    check_o_function: assert property (
        @(posedge clk) O == ((S & DI) | (~S & CI))
    );

// CO matches the implemented carry equation.
    check_co_function: assert property (
        @(posedge clk) CO == (((CI & S) | (DI & (CI | S))))
    );

// When S is low, O follows CI.
    check_o_follows_ci_when_s_low: assert property (
        @(posedge clk) !S |-> (O == CI)
    );

// When S is high, O follows DI.
    check_o_follows_di_when_s_high: assert property (
        @(posedge clk) S |-> (O == DI)
    );

// With S low, CO is the AND of CI and DI.
    check_co_is_and_when_s_low: assert property (
        @(posedge clk) !S |-> (CO == (CI & DI))
    );

// With S high, CO is the OR of CI and DI.
    check_co_is_or_when_s_high: assert property (
        @(posedge clk) S |-> (CO == (CI | DI))
    );

// ENCLK is 0 on the cycle after RESET is asserted.
    check_reset_clears_enclk: assert property (
        @(posedge CLK) RESET |=> (ENCLK == 1'b0)
    );

// ENCLK is 0 on the cycle after EN is deasserted.
    check_en_low_clears_enclk: assert property (
        @(posedge CLK) disable iff (RESET) !EN |=> (ENCLK == 1'b0)
    );

// ENCLK is 0 on the cycle after TE is asserted when EN is high.
    check_te_high_clears_enclk_when_en: assert property (
        @(posedge CLK) disable iff (RESET) (EN && TE) |=> (ENCLK == 1'b0)
    );

// ENCLK is 1 on the cycle after TE is deasserted when EN is high.
    check_te_low_sets_enclk_when_en: assert property (
        @(posedge CLK) disable iff (RESET) (EN && !TE) |=> (ENCLK == 1'b1)
    );

// ENCLK is 0 on the cycle after EN is asserted with TE high.
    check_en_high_te_high_clears_enclk: assert property (
        @(posedge CLK) disable iff (RESET) (EN && TE) |=> (ENCLK == 1'b0)
    );

// ENCLK is 1 on the cycle after EN is asserted with TE low.
    check_en_high_te_low_sets_enclk: assert property (
        @(posedge CLK) disable iff (RESET) (EN && !TE) |=> (ENCLK == 1'b1)
    );

// No RTL reset; assertions are always active.

    // When SUB is low, OUT equals A + B.
    check_add_mode_result: assert property (
        @(posedge clk) !SUB |-> (OUT == (A + B))
    );

// 000 decodes to bit 0.
    check_decode_000: assert property (
        @(posedge clk) (in == 3'b000) |-> (out == 8'b00000001)
    );

// 001 decodes to bit 1.
    check_decode_001: assert property (
        @(posedge clk) (in == 3'b001) |-> (out == 8'b00000010)
    );

// 010 decodes to bit 2.
    check_decode_010: assert property (
        @(posedge clk) (in == 3'b010) |-> (out == 8'b00000100)
    );

// 011 decodes to bit 3.
    check_decode_011: assert property (
        @(posedge clk) (in == 3'b011) |-> (out == 8'b00001000)
    );

// 100 decodes to bit 4.
    check_decode_100: assert property (
        @(posedge clk) (in == 3'b100) |-> (out == 8'b00010000)
    );

// 101 decodes to bit 5.
    check_decode_101: assert property (
        @(posedge clk) (in == 3'b101) |-> (out == 8'b00100000)
    );

// 110 decodes to bit 6.
    check_decode_110: assert property (
        @(posedge clk) (in == 3'b110) |-> (out == 8'b01000000)
    );

// 111 decodes to bit 7.
    check_decode_111: assert property (
        @(posedge clk) (in == 3'b111) |-> (out == 8'b10000000)
    );

// Any unknown input value drives zero.
    check_default_zero: assert property (
        @(posedge clk) (in != 3'b000 && in != 3'b001 && in != 3'b010 && in != 3'b011 &&
                        in != 3'b100 && in != 3'b101 && in != 3'b110 && in != 3'b111)
        |-> (out == 8'b00000000)
    );

// Output is always one-hot.
    check_onehot_output: assert property (
        @(posedge clk) $onehot(out)
    );

// A1, A2, and A3 high force X high.
    check_a1_a2_a3_triplet_sets_x: assert property (
        @(posedge clk)
        (A1 & A2 & A3) |-> X
    );

// A1, A2, and A4 high force X high.
    check_a1_a2_a4_triplet_sets_x: assert property (
        @(posedge clk)
        (A1 & A2 & A4) |-> X
    );

// A1, A3, and A4 high force X high.
    check_a1_a3_a4_triplet_sets_x: assert property (
        @(posedge clk)
        (A1 & A3 & A4) |-> X
    );

// A2, A3, and A4 high force X high.
    check_a2_a3_a4_triplet_sets_x: assert property (
        @(posedge clk)
        (A2 & A3 & A4) |-> X
    );

// A1, A2, and B1 high force X high.
    check_a1_a2_b1_pair_sets_x: assert property (
        @(posedge clk)
        (A1 & A2 & B1) |-> X
    );

// A1, A3, and B1 high force X high.
    check_a1_a3_b1_pair_sets_x: assert property (
        @(posedge clk)
        (A1 & A3 & B1) |-> X
    );

// A1, A4, and B1 high force X high.
    check_a1_a4_b1_pair_sets_x: assert property (
        @(posedge clk)
        (A1 & A4 & B1) |-> X
    );

// A2, A3, and B1 high force X high.
    check_a2_a3_b1_pair_sets_x: assert property (
        @(posedge clk)
        (A2 & A3 & B1) |-> X
    );

// A2, A4, and B1 high force X high.
    check_a2_a4_b1_pair_sets_x: assert property (
        @(posedge clk)
        (A2 & A4 & B1) |-> X
    );

// A3, A4, and B1 high force X high.
    check_a3_a4_b1_pair_sets_x: assert property (
        @(posedge clk)
        (A3 & A4 & B1) |-> X
    );

// Reset clears q on the next clock.
    check_reset_clears_q: assert property (
        @(posedge clk) rst |=> (q == 64'h0)
    );

// Reset has priority over load when both are asserted.
    check_reset_priority_over_load: assert property (
        @(posedge clk) (rst && ld) |=> (q == 64'h0)
    );

// Load captures d when reset is low.
    check_load_captures_d: assert property (
        @(posedge clk) disable iff (rst) ld |=> (q == $past(d))
    );

// When neither reset nor load is asserted, q holds its value.
    check_hold_when_idle: assert property (
        @(posedge clk) disable iff (rst) (!ld) |=> (q == $past(q))
    );

// Reset drives both outputs to zero.
    check_reset_clears_outputs: assert property (
        @(posedge clk) !jrst_n |-> (atm == 36'h0) && (dtm == 36'h0)
    );

// A read cycle captures the address and read data into atm and dtm.
    check_read_captures_data: assert property (
        @(posedge clk) disable iff (!jrst_n)
        cpu_d_read |=> (atm == {21'h0, $past(cpu_d_address)}) &&
                      (dtm == {32'h0, $past(cpu_d_readdata)})
    );

// Without any active cycle, the outputs hold their previous values.
    check_idle_holds_outputs: assert property (
        @(posedge clk) disable iff (!jrst_n)
        !(cpu_d_read || cpu_d_write || cpu_d_wait) |=> (atm == $past(atm)) &&
                                                       (dtm == $past(dtm))
    );

// A read cycle has priority over a write cycle when both are asserted.
    check_read_overrides_write: assert property (
        @(posedge clk) disable iff (!jrst_n)
        (cpu_d_read && cpu_d_write) |=> (atm == {21'h0, $past(cpu_d_address)}) &&
                                      (dtm == {32'h0, $past(cpu_d_readdata)})
    );

// A read cycle has priority over a wait cycle when both are asserted.
    check_read_overrides_wait: assert property (
        @(posedge clk) disable iff (!jrst_n)
        (cpu_d_read && cpu_d_wait) |=> (atm == {21'h0, $past(cpu_d_address)}) &&
                                      (dtm == {32'h0, $past(cpu_d_readdata)})
    );

// A high d with a low q drives q low on the next clock.
    check_q_low_when_d_high_and_q_low: assert property (
        @(posedge clk) (d && !q) |=> !q
    );

// A low d with a low q leaves q low on the next clock.
    check_q_low_when_d_low_and_q_low: assert property (
        @(posedge clk) (!d && !q) |=> !q
    );

// Clock: CK (posedge). Reset: RST synchronous active-high. Logic: sequential 4-bit counter.

    // When RST is HIGH at a clock edge, Q must be 0 on the next clock.
    reset_clears_next: assert property (
        @(posedge CK) RST |=> (Q == 4'b0000)
    );

// If RST is HIGH in consecutive cycles, Q must be 0 in the current cycle.
    reset_holds_zero: assert property (
        @(posedge CK) RST && $past(RST) |-> (Q == 4'b0000)
    );

// When not in reset, Q increments by 1 modulo 16 each cycle.
    count_increments_mod16: assert property (
        @(posedge CK) disable iff (RST) 1'b1 |=> (Q == ($past(Q) + 4'd1))
    );

// When not in reset, Q never holds its previous value.
    count_never_holds: assert property (
        @(posedge CK) disable iff (RST) 1'b1 |=> (Q != $past(Q))
    );

// When not in reset, Q wraps from 15 back to 0.
    count_wraps_from_max: assert property (
        @(posedge CK) disable iff (RST) (Q == 4'hF) |=> (Q == 4'h0)
    );

// fill must match the RTL combinational equation.
    check_fill_equation: assert property (
        @(posedge clk) fill == ((VPWR & !VGND) | (!VPB & VNB))
    );

// VPWR high and VGND low must drive fill high.
    check_vpwr_high_vgnd_low: assert property (
        @(posedge clk) (VPWR & !VGND) |-> fill
    );

// VPB low and VNB high must drive fill high.
    check_vpb_low_vnb_high: assert property (
        @(posedge clk) (!VPB & VNB) |-> fill
    );

// Any low-to-high transition on VPWR with VGND low must set fill high.
    check_vpwr_rise_with_vgnd_low: assert property (
        @(posedge clk) $rose(VPWR) && !VGND |-> fill
    );

// Any low-to-high transition on VNB with VPB low must set fill high.
    check_vnb_rise_with_vpb_low: assert property (
        @(posedge clk) $rose(VNB) && !VPB |-> fill
    );

// EQ must equal the bitwise AND of the inverted difference.
    check_eq_definition: assert property (
        @(posedge clk) EQ == (&(~(A - B)))
    );

// When A equals B, EQ must be high and GT must be low.
    check_equal_case: assert property (
        @(posedge clk) (A == B) |-> (EQ && !GT)
    );

// When A is less than B, neither EQ nor GT can be high.
    check_less_case: assert property (
        @(posedge clk) (A < B) |-> (!EQ && !GT)
    );

// EQ can only be high when A equals B.
    check_eq_only_on_equal: assert property (
        @(posedge clk) EQ |-> (A == B)
    );

// GT can only be high when A is greater than B.
    check_gt_only_on_greater: assert property (
        @(posedge clk) GT |-> (A > B)
    );

// EQ and GT cannot be high at the same time.
    check_mutex_eq_gt: assert property (
        @(posedge clk) !(EQ && GT)
    );

// ALU opcode 0000 selects addition.
    check_add_result: assert property (
        @(posedge clk) (aluc == 4'b0000) |-> (result == (a + b))
    );

// ALU opcode 1000 selects addition.
    check_add_result_alt: assert property (
        @(posedge clk) (aluc == 4'b1000) |-> (result == (a + b))
    );

// ALU opcode 0100 selects subtraction.
    check_sub_result: assert property (
        @(posedge clk) (aluc == 4'b0100) |-> (result == (a - b))
    );

// ALU opcode 1100 selects subtraction.
    check_sub_result_alt: assert property (
        @(posedge clk) (aluc == 4'b1100) |-> (result == (a - b))
    );

// ALU opcode 0001 selects bitwise AND.
    check_and_result: assert property (
        @(posedge clk) (aluc == 4'b0001) |-> (result == (a & b))
    );

// ALU opcode 1001 selects bitwise AND.
    check_and_result_alt: assert property (
        @(posedge clk) (aluc == 4'b1001) |-> (result == (a & b))
    );

// ALU opcode 0101 selects bitwise OR.
    check_or_result: assert property (
        @(posedge clk) (aluc == 4'b0101) |-> (result == (a | b))
    );

// ALU opcode 1101 selects bitwise OR.
    check_or_result_alt: assert property (
        @(posedge clk) (aluc == 4'b1101) |-> (result == (a | b))
    );

// ALU opcode 1010 selects bitwise XOR.
    check_xor_result: assert property (
        @(posedge clk) (aluc == 4'b1010) |-> (result == (a ^ b))
    );

// ALU opcode 0010 selects bitwise XOR.
    check_xor_result_alt: assert property (
        @(posedge clk) (aluc == 4'b0010) |-> (result == (a ^ b))
    );

// ALU opcode 0110 selects zero-extended b.
    check_lui_result: assert property (
        @(posedge clk) (aluc == 4'b0110) |-> (result == {16'b0, b[15:0]})
    );

// ALU opcode 1110 selects zero-extended b.
    check_lui_result_alt: assert property (
        @(posedge clk) (aluc == 4'b1110) |-> (result == {16'b0, b[15:0]})
    );

// ALU opcode 0011 selects logical left shift by a.
    check_sll_result: assert property (
        @(posedge clk) (aluc == 4'b0011) |-> (result == (b << a))
    );

// ALU opcode 0111 selects logical right shift by a.
    check_srl_result: assert property (
        @(posedge clk) (aluc == 4'b0111) |-> (result == (b >> a))
    );

// When OE is high, Z10[1:0] must be 10.
    check_oe_high_swaps_low_pair: assert property (
        @(posedge clk) OE |-> (Z10[1:0] == 2'b10)
    );

// When OE is low, Z10[1:0] must be 01.
    check_oe_low_keeps_low_pair: assert property (
        @(posedge clk) !OE |-> (Z10[1:0] == 2'b01)
    );

// In add mode, result equals A + B (4-bit wrap).
    check_add_result: assert property (
        @(posedge CLK) (SUB == 1'b0) |-> (result == (A + B))
    );

// In subtract mode, result equals A - B (4-bit wrap).
    check_sub_result: assert property (
        @(posedge CLK) (SUB == 1'b1) |-> (result == (A - B))
    );

// OVFL is 0 when result[3] is 0 (no 4-bit carry).
    check_ovfl_low_when_no_carry: assert property (
        @(posedge CLK) (result[3] == 1'b0) |-> (OVFL == 1'b0)
    );

// OVFL is 1 when result[3] is 1 (4-bit carry).
    check_ovfl_high_when_carry: assert property (
        @(posedge CLK) (result[3] == 1'b1) |-> (OVFL == 1'b1)
    );

// OVFL is 0 when adding two 4-bit zeros.
    check_add_zero_case: assert property (
        @(posedge CLK) (SUB == 1'b0 && A == 4'd0 && B == 4'd0) |-> (OVFL == 1'b0)
    );

// In subtract mode, A - 0 equals A (mod 16).
    check_sub_a_minus_zero: assert property (
        @(posedge CLK) (SUB == 1'b1 && B == 4'd0) |-> (result == A)
    );

// In add mode, C equals A + B (4-bit wrap).
    check_add_mode_result: assert property (
        @(posedge clk) (CTRL == 1'b0) |-> (C == (A + B))
    );

// In shift mode, C equals {1'b0, A[3:1]} + {1'b0, B[3:1]} (4-bit wrap).
    check_shift_mode_result: assert property (
        @(posedge clk) (CTRL == 1'b1) |-> (C == ({1'b0, A[3:1]} + {1'b0, B[3:1]}))
    );

// In add mode, 0 + 0 yields 0.
    check_add_zero_plus_zero: assert property (
        @(posedge clk) (CTRL == 1'b0 && A == 4'h0 && B == 4'h0) |-> (C == 4'h0)
    );

// In add mode, 0 + 15 yields 15.
    check_add_zero_plus_max: assert property (
        @(posedge clk) (CTRL == 1'b0 && A == 4'h0 && B == 4'hF) |-> (C == 4'hF)
    );

// In add mode, 15 + 0 yields 15.
    check_add_max_plus_zero: assert property (
        @(posedge clk) (CTRL == 1'b0 && A == 4'hF && B == 4'h0) |-> (C == 4'hF)
    );

// In shift mode, 0 + 0 yields 0.
    check_shift_zero_plus_zero: assert property (
        @(posedge clk) (CTRL == 1'b1 && A == 4'h0 && B == 4'h0) |-> (C == 4'h0)
    );

// A=00 passes D through unchanged.
    check_a00_passthrough: assert property (
        @(posedge clk) (A == 2'b00) |-> (S == D)
    );

// A=01 shifts left by 1 with zero fill.
    check_a01_shift1: assert property (
        @(posedge clk) (A == 2'b01) |-> (S == {D[2:0], 1'b0})
    );

// A=10 shifts left by 2 with zero fill.
    check_a10_shift2: assert property (
        @(posedge clk) (A == 2'b10) |-> (S == {D[1:0], 2'b00})
    );

// A=11 shifts left by 3 with zero fill.
    check_a11_shift3: assert property (
        @(posedge clk) (A == 2'b11) |-> (S == {D[0], 3'b000})
    );

// Y must be the bitwise inversion of A.
    check_inversion: assert property (
        @(posedge clk) Y == ~A
    );

// A high input must drive Y low.
    check_a_high_drives_y_low: assert property (
        @(posedge clk) A |-> !Y
    );

// A low input must drive Y high.
    check_a_low_drives_y_high: assert property (
        @(posedge clk) !A |-> Y
    );

// Z[0] is the NAND of Z[1] with itself.
    check_z0_function: assert property (
        @(posedge clk) Z[0] == ~(Z[1] & Z[1])
    );

// sel=00 routes in0 to out.
    check_sel_00_routes_in0: assert property (
        @(posedge clk) (sel == 2'b00) |-> (out == in0)
    );

// sel=01 routes in1 to out.
    check_sel_01_routes_in1: assert property (
        @(posedge clk) (sel == 2'b01) |-> (out == in1)
    );

// sel=10 routes in2 to out.
    check_sel_10_routes_in2: assert property (
        @(posedge clk) (sel == 2'b10) |-> (out == in2)
    );

// sel=11 routes in3 to out.
    check_sel_11_routes_in3: assert property (
        @(posedge clk) (sel == 2'b11) |-> (out == in3)
    );

// Reset drives count to zero on the next clock.
    check_reset_clears_count: assert property (
        @(posedge clk) reset |=> (count == 4'b0000)
    );

// When enabled, count increments by one on the next clock.
    check_count_increments_when_enabled: assert property (
        @(posedge clk) disable iff (reset)
        enable |=> (count == ($past(count) + 4'd1))
    );

// When not enabled, count holds its previous value on the next clock.
    check_count_holds_when_disabled: assert property (
        @(posedge clk) disable iff (reset)
        !enable |=> (count == $past(count))
    );

// Count wraps from 15 back to 0 when enabled.
    check_count_wraps_from_max: assert property (
        @(posedge clk) disable iff (reset)
        (enable && (count == 4'hF)) |=> (count == 4'h0)
    );

// Upper 6 bits of shifted_data are the previous lower 6 bits.
    check_upper_bits_preserved: assert property (
        @(posedge clk) 1'b1 |=> (shifted_data[7:2] == $past(shifted_data[6:1]))
    );

// Y matches the implemented OR-NAND function.
    check_functional_equivalence: assert property (
        @(posedge clk) Y == ~(B1 & (A1 | A2 | A3))
    );

// A high A1 forces Y low when B1 is high.
    check_a1_high_forces_y_low_when_b1_high: assert property (
        @(posedge clk) (B1 && A1) |-> !Y
    );

// A high A2 forces Y low when B1 is high.
    check_a2_high_forces_y_low_when_b1_high: assert property (
        @(posedge clk) (B1 && A2) |-> !Y
    );

// A high A3 forces Y low when B1 is high.
    check_a3_high_forces_y_low_when_b1_high: assert property (
        @(posedge clk) (B1 && A3) |-> !Y
    );

// With all A inputs low, Y is high.
    check_y_high_when_all_a_low: assert property (
        @(posedge clk) (!A1 && !A2 && !A3) |-> Y
    );

// When EN is low, Y must be 0.
    check_disable_clears_output: assert property (
        @(posedge clk) !EN |-> (Y == 4'b0000)
    );

// When EN is high and A=0, B=0, Y must be 0001.
    check_enable_a0_b0: assert property (
        @(posedge clk) (EN && !A && !B) |-> (Y == 4'b0001)
    );

// When EN is high and A=0, B=1, Y must be 0010.
    check_enable_a0_b1: assert property (
        @(posedge clk) (EN && !A && B) |-> (Y == 4'b0010)
    );

// When EN is high and A=1, B=0, Y must be 0100.
    check_enable_a1_b0: assert property (
        @(posedge clk) (EN && A && !B) |-> (Y == 4'b0100)
    );

// When EN is high and A=1, B=1, Y must be 1000.
    check_enable_a1_b1: assert property (
        @(posedge clk) (EN && A && B) |-> (Y == 4'b1000)
    );

// Y can only be one of the four enabled encodings or zero.
    check_output_legal_values: assert property (
        @(posedge clk) Y inside {4'b0000, 4'b0001, 4'b0010, 4'b0100, 4'b1000}
    );

// If Y is non-zero, EN must be high.
    check_nonzero_output_requires_enable: assert property (
        @(posedge clk) (Y != 4'b0000) |-> EN
    );

// If Y is 0001, A=0, B=0, and EN=1.
    check_decode_0001: assert property (
        @(posedge clk) (Y == 4'b0001) |-> (EN && !A && !B)
    );

// If Y is 0010, A=0, B=1, and EN=1.
    check_decode_0010: assert property (
        @(posedge clk) (Y == 4'b0010) |-> (EN && !A && B)
    );

// If Y is 0100, A=1, B=0, and EN=1.
    check_decode_0100: assert property (
        @(posedge clk) (Y == 4'b0100) |-> (EN && A && !B)
    );

// If Y is 1000, A=1, B=1, and EN=1.
    check_decode_1000: assert property (
        @(posedge clk) (Y == 4'b1000) |-> (EN && A && B)
    );

// out0 is high only when the select code is 000.
    check_out0_decode: assert property (
        @(posedge clk) out0 == ((sel2 == 1'b0) && (sel1 == 1'b0) && (sel0 == 1'b0) ? in : 1'b0)
    );

// out1 is high only when the select code is 001.
    check_out1_decode: assert property (
        @(posedge clk) out1 == ((sel2 == 1'b0) && (sel1 == 1'b0) && (sel0 == 1'b1) ? in : 1'b0)
    );

// out2 is high only when the select code is 010.
    check_out2_decode: assert property (
        @(posedge clk) out2 == ((sel2 == 1'b0) && (sel1 == 1'b1) && (sel0 == 1'b0) ? in : 1'b0)
    );

// out3 is high only when the select code is 011.
    check_out3_decode: assert property (
        @(posedge clk) out3 == ((sel2 == 1'b0) && (sel1 == 1'b1) && (sel0 == 1'b1) ? in : 1'b0)
    );

// out4 is high only when the select code is 100.
    check_out4_decode: assert property (
        @(posedge clk) out4 == ((sel2 == 1'b1) && (sel1 == 1'b0) && (sel0 == 1'b0) ? in : 1'b0)
    );

// out5 is high only when the select code is 101.
    check_out5_decode: assert property (
        @(posedge clk) out5 == ((sel2 == 1'b1) && (sel1 == 1'b0) && (sel0 == 1'b1) ? in : 1'b0)
    );

// out6 is high only when the select code is 110.
    check_out6_decode: assert property (
        @(posedge clk) out6 == ((sel2 == 1'b1) && (sel1 == 1'b1) && (sel0 == 1'b0) ? in : 1'b0)
    );

// out7 is high only when the select code is 111.
    check_out7_decode: assert property (
        @(posedge clk) out7 == ((sel2 == 1'b1) && (sel1 == 1'b1) && (sel0 == 1'b1) ? in : 1'b0)
    );

// When in is 0, all outputs are 0.
    check_zero_input_clears_outputs: assert property (
        @(posedge clk) (in == 1'b0) |-> (out0 == 1'b0 && out1 == 1'b0 && out2 == 1'b0 && out3 == 1'b0 && out4 == 1'b0 && out5 == 1'b0 && out6 == 1'b0 && out7 == 1'b0)
    );

// Reset clears C on the next clock.
    check_reset_clears_c: assert property (
        @(posedge clk) rst |=> (C == 8'h00)
    );

// With reset low, C captures A + B on the next clock.
    check_addition_update: assert property (
        @(posedge clk) disable iff (rst) 1'b1 |=> (C == ($past(A) + $past(B)))
    );

// When A is zero, C captures B on the next clock.
    check_zero_a_passthrough: assert property (
        @(posedge clk) disable iff (rst) (A == 8'h00) |=> (C == $past(B))
    );

// When B is zero, C captures A on the next clock.
    check_zero_b_passthrough: assert property (
        @(posedge clk) disable iff (rst) (B == 8'h00) |=> (C == $past(A))
    );

// When A and B are equal, C captures A + B with no carry.
    check_equal_operands_no_carry: assert property (
        @(posedge clk) disable iff (rst) (A == B) |=> (C == ($past(A) + $past(B)))
    );

// When A is 8'hFF and B is 1, C wraps to 0 on the next clock.
    check_ff_plus_one_wraps_to_zero: assert property (
        @(posedge clk) disable iff (rst) ((A == 8'hFF) && (B == 8'h01)) |=> (C == 8'h00)
    );

// When A=0 and B=0, O must be 0000_0000_0000_0001.
    check_decode_00: assert property (
        @(posedge clk) (A == 1'b0 && B == 1'b0) |-> (O == 16'h0001)
    );

// When A=0 and B=1, O must be 0000_0000_0000_0010.
    check_decode_01: assert property (
        @(posedge clk) (A == 1'b0 && B == 1'b1) |-> (O == 16'h0002)
    );

// When A=1 and B=0, O must be 0000_0000_0000_0100.
    check_decode_10: assert property (
        @(posedge clk) (A == 1'b1 && B == 1'b0) |-> (O == 16'h0004)
    );

// When A=1 and B=1, O must be 0000_0000_0000_1000.
    check_decode_11: assert property (
        @(posedge clk) (A == 1'b1 && B == 1'b1) |-> (O == 16'h0008)
    );

// When A=0 and B=0, only O0 can be high.
    check_onehot_00: assert property (
        @(posedge clk) (A == 1'b0 && B == 1'b0) |-> (O == 16'h0001)
    );

// When A=0 and B=1, only O1 can be high.
    check_onehot_01: assert property (
        @(posedge clk) (A == 1'b0 && B == 1'b1) |-> (O == 16'h0002)
    );

// When A=1 and B=0, only O2 can be high.
    check_onehot_10: assert property (
        @(posedge clk) (A == 1'b1 && B == 1'b0) |-> (O == 16'h0004)
    );

// When A=1 and B=1, only O3 can be high.
    check_onehot_11: assert property (
        @(posedge clk) (A == 1'b1 && B == 1'b1) |-> (O == 16'h0008)
    );

// O must always be one of the four allowed patterns.
    check_valid_output_pattern: assert property (
        @(posedge clk) (O == 16'h0001) || (O == 16'h0002) || (O == 16'h0004) || (O == 16'h0008)
    );

// ENCLK is low on the next clock when TE was high and EN was low.
    check_enclk_clear_on_te_high_en_low: assert property (
        @(posedge CLK) (TE && !EN) |=> (ENCLK == 1'b0)
    );

// ENCLK holds its value on the next clock when TE was low.
    check_enclk_holds_when_te_low: assert property (
        @(posedge CLK) !TE |=> $stable(ENCLK)
    );

// Reset low forces q to zero on the next clock.
    check_reset_clears_q: assert property (
        @(posedge clk) !resetn |=> (q == 26'h0)
    );

// Squash low forces q to zero on the next clock.
    check_squash_clears_q: assert property (
        @(posedge clk) !squashn |=> (q == 26'h0)
    );

// When enabled and not in reset/squash, q captures d on the next clock.
    check_capture_when_enabled: assert property (
        @(posedge clk) disable iff (!resetn || !squashn) en |=> (q == $past(d))
    );

// When not enabled and not in reset/squash, q holds its previous value.
    check_hold_when_disabled: assert property (
        @(posedge clk) disable iff (!resetn || !squashn) !en |=> (q == $past(q))
    );

// Reset drives the next state to 0.
    check_reset_clears_state: assert property (
        @(posedge clk) rst |=> (out == 4'd0)
    );

// State 0 maps to 0 on the next cycle.
    check_state_0_maps_to_0: assert property (
        @(posedge clk) disable iff (rst) (out == 4'd0) |=> (out == 4'd0)
    );

// State 1 maps to 1 on the next cycle.
    check_state_1_maps_to_1: assert property (
        @(posedge clk) disable iff (rst) (out == 4'd1) |=> (out == 4'd1)
    );

// State 2 maps to 3 on the next cycle.
    check_state_2_maps_to_3: assert property (
        @(posedge clk) disable iff (rst) (out == 4'd2) |=> (out == 4'd3)
    );

// State 3 maps to 2 on the next cycle.
    check_state_3_maps_to_2: assert property (
        @(posedge clk) disable iff (rst) (out == 4'd3) |=> (out == 4'd2)
    );

// State 4 maps to 6 on the next cycle.
    check_state_4_maps_to_6: assert property (
        @(posedge clk) disable iff (rst) (out == 4'd4) |=> (out == 4'd6)
    );

// State 5 maps to 7 on the next cycle.
    check_state_5_maps_to_7: assert property (
        @(posedge clk) disable iff (rst) (out == 4'd5) |=> (out == 4'd7)
    );

// State 6 maps to 5 on the next cycle.
    check_state_6_maps_to_5: assert property (
        @(posedge clk) disable iff (rst) (out == 4'd6) |=> (out == 4'd5)
    );

// State 7 maps to 4 on the next cycle.
    check_state_7_maps_to_4: assert property (
        @(posedge clk) disable iff (rst) (out == 4'd7) |=> (out == 4'd4)
    );

// Active-low reset forces q to zero.
    check_reset_clears_q: assert property (
        @(posedge clk) !areset |-> (q == 4'b0000)
    );

// Load captures data when enabled.
    check_load_captures_data: assert property (
        @(posedge clk) disable iff (!areset)
        (load && !ena) |=> (q == $past(data))
    );

// Load has priority over enable when both are high.
    check_load_priority_over_enable: assert property (
        @(posedge clk) disable iff (!areset)
        (load && ena) |=> (q == $past(data))
    );

// Enable rotates q left by one bit when load is low.
    check_enable_rotates_q: assert property (
        @(posedge clk) disable iff (!areset)
        (!load && ena) |=> (q == {$past(q[2:0]), $past(q[3])})
    );

// With no load or enable, q holds its value.
    check_hold_when_idle: assert property (
        @(posedge clk) disable iff (!areset)
        (!load && !ena) |=> (q == $past(q))
    );

// When not enabled, next cycle out is zero.
    clear_when_disabled: assert property (
        @(posedge clk) !en |=> (out == 8'h00)
    );

// When enabled and carrier is low, next cycle out is zero.
    clear_when_carrier_low: assert property (
        @(posedge clk) (en && !carrier) |=> (out == 8'h00)
    );

// Output is 01 when LSB is 1.
    check_output_01_when_lsb1: assert property (
        @(posedge clk) input_bits[0] |-> (output_bits == 2'b01)
    );

// Output is 10 when LSB is 0.
    check_output_10_when_lsb0: assert property (
        @(posedge clk) !input_bits[0] |-> (output_bits == 2'b10)
    );

// Output is always one-hot.
    check_output_onehot: assert property (
        @(posedge clk) $onehot(output_bits)
    );

// Output never equals 00.
    check_output_not_zero: assert property (
        @(posedge clk) output_bits != 2'b00
    );

// Output must match the RTL mux expression.
    check_mux_function: assert property (
        @(posedge clk) out == ((sel == 1'b1) ? b : a)
    );

// When select is low, output must follow input a.
    check_select_a: assert property (
        @(posedge clk) (sel == 1'b0) |-> (out == a)
    );

// When select is high, output must follow input b.
    check_select_b: assert property (
        @(posedge clk) (sel == 1'b1) |-> (out == b)
    );

// Equal inputs must force the same value on the output.
    check_equal_inputs: assert property (
        @(posedge clk) (a == b) |-> (out == a)
    );

// Output MSB is the bitwise inversion of the input MSB.
    check_msb_inversion: assert property (
        @(posedge clk) o_inverted[3] == ~i_binary[3]
    );

// Output bits [2:0] pass through the input bits [2:0].
    check_lsb_passthrough: assert property (
        @(posedge clk) o_inverted[2:0] == i_binary[2:0]
    );

// The full output bus matches the RTL concatenation.
    check_full_output: assert property (
        @(posedge clk) o_inverted == {~i_binary[3], i_binary[2:0]}
    );

// In add mode, Y equals A + B.
    check_add_mode_result: assert property (
        @(posedge clk) (mode == 1'b0) |-> (Y == (A + B))
    );

// In subtract mode, Y equals A + (~B + 1).
    check_sub_mode_result: assert property (
        @(posedge clk) (mode == 1'b1) |-> (Y == (A + ((~B) + 4'b0001)))
    );

// In subtract mode, Y equals A - B.
    check_sub_mode_equivalence: assert property (
        @(posedge clk) (mode == 1'b1) |-> (Y == (A - B))
    );

// In add mode, 0 on B passes A through.
    check_add_zero_b_passthrough: assert property (
        @(posedge clk) (mode == 1'b0 && B == 4'h0) |-> (Y == A)
    );

// In subtract mode, 0 on B passes A through.
    check_sub_zero_b_passthrough: assert property (
        @(posedge clk) (mode == 1'b1 && B == 4'h0) |-> (Y == A)
    );

// In add mode, 0 on A passes B through.
    check_add_zero_a_passthrough: assert property (
        @(posedge clk) (mode == 1'b0 && A == 4'h0) |-> (Y == B)
    );

// In subtract mode, 0 on A equals ~B + 1.
    check_sub_zero_a_result: assert property (
        @(posedge clk) (mode == 1'b1 && A == 4'h0) |-> (Y == ((~B) + 4'b0001))
    );

// In add mode, 4'hF on B equals A + 4'hF.
    check_add_all_ones_b_result: assert property (
        @(posedge clk) (mode == 1'b0 && B == 4'hF) |-> (Y == (A + 4'hF))
    );

// X must match the implemented combinational function.
    check_functional_equivalence: assert property (
        @(posedge clk)
        X == ((A0 & ~S0 & ~S1) | (A1 & S0 & ~S1) | (A2 & ~S0 & S1) | (A3 & S0 & S1))
    );

// When S1 is low, X must select between A0 and A1 based on S0.
    check_select_low: assert property (
        @(posedge clk)
        !S1 |-> (X == ((A0 & ~S0) | (A1 & S0)))
    );

// When S1 is high, X must select between A2 and A3 based on S0.
    check_select_high: assert property (
        @(posedge clk)
        S1 |-> (X == ((A2 & ~S0) | (A3 & S0)))
    );

// With S1 low and S0 low, X must follow A0.
    check_select_low_low: assert property (
        @(posedge clk)
        (!S1 && !S0) |-> (X == A0)
    );

// With S1 low and S0 high, X must follow A1.
    check_select_low_high: assert property (
        @(posedge clk)
        (!S1 && S0) |-> (X == A1)
    );

// With S1 high and S0 low, X must follow A2.
    check_select_high_low: assert property (
        @(posedge clk)
        (S1 && !S0) |-> (X == A2)
    );

// With S1 high and S0 high, X must follow A3.
    check_select_high_high: assert property (
        @(posedge clk)
        (S1 && S0) |-> (X == A3)
    );

// Q captures D on the next clock when E is high.
    check_capture_when_enabled: assert property (
        @(posedge C) E |=> (Q == $past(D))
    );

// Q holds its value on the next clock when E is low.
    check_hold_when_disabled: assert property (
        @(posedge C) !E |=> (Q == $past(Q))
    );

// A high D is captured into Q on the next clock when E is high.
    check_capture_high: assert property (
        @(posedge C) (E && D) |=> (Q == 1'b1)
    );

// A low D is captured into Q on the next clock when E is high.
    check_capture_low: assert property (
        @(posedge C) (E && !D) |=> (Q == 1'b0)
    );

// Reset clears the entire 4-stage shift register.
    check_reset_clears_out: assert property (
        @(posedge CLK) RST |=> (OUT == 4'b0000)
    );

// Without load, the register holds its value.
    check_hold_when_not_load: assert property (
        @(posedge CLK) disable iff (RST) !LD |=> (OUT == $past(OUT))
    );

// Left shift mode produces in shifted left by shift_amt.
    check_left_shift_result: assert property (
        @(posedge clk) shift_left |-> (out == (in << shift_amt))
    );

// Right shift mode produces in shifted right by shift_amt.
    check_right_shift_result: assert property (
        @(posedge clk) !shift_left |-> (out == (in >> shift_amt))
    );

// A zero shift amount passes the input through unchanged.
    check_zero_shift_passthrough: assert property (
        @(posedge clk) (shift_amt == 4'd0) |-> (out == in)
    );

// SUM is the XOR of A and B.
    check_sum_xor: assert property (
        @(posedge clk) SUM == (A ^ B)
    );

// COUT is the AND of A and B.
    check_cout_and: assert property (
        @(posedge clk) COUT == (A & B)
    );

// When A and B are equal, SUM must be 0.
    check_sum_zero_when_equal: assert property (
        @(posedge clk) (A == B) |-> (SUM == 1'b0)
    );

// When A and B differ, SUM must be 1.
    check_sum_one_when_different: assert property (
        @(posedge clk) (A != B) |-> (SUM == 1'b1)
    );

// When A is 0, SUM must equal B.
    check_sum_equals_b_when_a0: assert property (
        @(posedge clk) (A == 1'b0) |-> (SUM == B)
    );

// When A is 1, SUM must be the inverse of B.
    check_sum_inverts_b_when_a1: assert property (
        @(posedge clk) (A == 1'b1) |-> (SUM == ~B)
    );

// When B is 0, SUM must equal A.
    check_sum_equals_a_when_b0: assert property (
        @(posedge clk) (B == 1'b0) |-> (SUM == A)
    );

// When B is 1, SUM must be the inverse of A.
    check_sum_inverts_a_when_b1: assert property (
        @(posedge clk) (B == 1'b1) |-> (SUM == ~A)
    );

// When both inputs are 0, COUT must be 0.
    check_cout_zero_when_both_zero: assert property (
        @(posedge clk) ((A == 1'b0) && (B == 1'b0)) |-> (COUT == 1'b0)
    );

// When both inputs are 1, COUT must be 1.
    check_cout_one_when_both_one: assert property (
        @(posedge clk) ((A == 1'b1) && (B == 1'b1)) |-> (COUT == 1'b1)
    );

// When A is 0, COUT must be 0.
    check_cout_zero_when_a0: assert property (
        @(posedge clk) (A == 1'b0) |-> (COUT == 1'b0)
    );

// When A is 1, COUT must equal B.
    check_cout_equals_b_when_a1: assert property (
        @(posedge clk) (A == 1'b1) |-> (COUT == B)
    );

// When B is 0, COUT must be 0.
    check_cout_zero_when_b0: assert property (
        @(posedge clk) (B == 1'b0) |-> (COUT == 1'b0)
    );

// When B is 1, COUT must equal A.
    check_cout_equals_a_when_b1: assert property (
        @(posedge clk) (B == 1'b1) |-> (COUT == A)
    );

// X equals A ^ B on each sampled clock edge.
    check_xor_function: assert property (
        @(posedge clk) X == (A ^ B)
    );

// When A equals B, X must be 0.
    check_equal_inputs_drive_zero: assert property (
        @(posedge clk) (A == B) |-> (X == 1'b0)
    );

// When A differs from B, X must be 1.
    check_different_inputs_drive_one: assert property (
        @(posedge clk) (A != B) |-> (X == 1'b1)
    );

// A=0 and B=0 implies X=0.
    check_zero_inputs_drive_zero: assert property (
        @(posedge clk) ((A == 1'b0) && (B == 1'b0)) |-> (X == 1'b0)
    );

// A=1 and B=1 implies X=0.
    check_one_inputs_drive_zero: assert property (
        @(posedge clk) ((A == 1'b1) && (B == 1'b1)) |-> (X == 1'b0)
    );

// A=0 and B=1 implies X=1.
    check_mismatch_01_drives_one: assert property (
        @(posedge clk) ((A == 1'b0) && (B == 1'b1)) |-> (X == 1'b1)
    );

// A=1 and B=0 implies X=1.
    check_mismatch_10_drives_one: assert property (
        @(posedge clk) ((A == 1'b1) && (B == 1'b0)) |-> (X == 1'b1)
    );

// X must match the RTL mux equation.
    check_mux_equation: assert property (
        @(posedge clk) X == ((S == 1'b1) ? A1 : A0)
    );

// When S is low, X must follow A0.
    check_select_low_routes_a0: assert property (
        @(posedge clk) (S == 1'b0) |-> (X == A0)
    );

// When S is high, X must follow A1.
    check_select_high_routes_a1: assert property (
        @(posedge clk) (S == 1'b1) |-> (X == A1)
    );

// Equal data inputs must force X to that value regardless of S.
    check_equal_inputs_force_x: assert property (
        @(posedge clk) (A0 == A1) |-> (X == A0)
    );

// Bit 2 sum uses the carry generated from bit 1.
    check_bit2_sum: assert property (
        @(posedge clk) S[2] == (A[2] ^ B[2] ^ ((A[1] & B[1]) | (A[1] & ((A[0] & B[0]) | (A[0] & 1'b0) | (B[0] & 1'b0))) | (B[1] & ((A[0] & B[0]) | (A[0] & 1'b0) | (B[0] & 1'b0)))))
    );

// Y matches the implemented NOR-of-ANDs function.
    check_y_function: assert property (
        @(posedge clk) Y == ~((A1 & A2 & B1) | (A1 & B1))
    );

// With A1 and A2 low, Y is high.
    check_y_high_when_a1_a2_low: assert property (
        @(posedge clk) (!A1 && !A2) |-> Y
    );

// With A1 and B1 low, Y is high.
    check_y_high_when_a1_b1_low: assert property (
        @(posedge clk) (!A1 && !B1) |-> Y
    );

// With A2 and B1 low, Y is high.
    check_y_high_when_a2_b1_low: assert property (
        @(posedge clk) (!A2 && !B1) |-> Y
    );

// greater must reflect A > B.
    check_greater_definition: assert property (
        @(posedge clk) greater == (A > B)
    );

// less must reflect A < B.
    check_less_definition: assert property (
        @(posedge clk) less == (A < B)
    );

// When A equals B, both outputs must be LOW.
    check_equal_inputs_zero_outputs: assert property (
        @(posedge clk) (A == B) |-> (!greater && !less)
    );

// When A is greater than B, only greater can be HIGH.
    check_greater_high_when_a_gt_b: assert property (
        @(posedge clk) (A > B) |-> (greater && !less)
    );

// When A is less than B, only less can be HIGH.
    check_less_high_when_a_lt_b: assert property (
        @(posedge clk) (A < B) |-> (!greater && less)
    );

// clkout is always the bitwise inversion of clkin.
    check_inversion_exact: assert property (
        @(posedge clkin) clkout == ~clkin
    );

// A high clkin must produce a low clkout.
    check_clkin_high_drives_clkout_low: assert property (
        @(posedge clkin) clkin |-> !clkout
    );

// A low clkin must produce a high clkout.
    check_clkin_low_drives_clkout_high: assert property (
        @(posedge clkin) !clkin |-> clkout
    );

// Clock: CLK (posedge). Reset: RST active-high synchronous.
    // Logic: Sequential; next-state depends on current DATA_OUT.

    // On reset, DATA_OUT is driven to 0 on the next cycle.
    reset_clears_next: assert property (
        @(posedge CLK) RST |=> (DATA_OUT == 8'h00)
    );

// When not in reset and DATA_OUT is 0xf4, next value is 0xc2.
    next_c2_when_f4: assert property (
        @(posedge CLK) disable iff (RST) (DATA_OUT == 8'hf4) |=> (DATA_OUT == 8'hc2)
    );

// When not in reset and DATA_OUT is not 0xf4, next value is 0xf4.
    next_f4_when_not_f4: assert property (
        @(posedge CLK) disable iff (RST) (DATA_OUT != 8'hf4) |=> (DATA_OUT == 8'hf4)
    );

// When not in reset, DATA_OUT must be either 0xf4 or 0xc2 on the next cycle.
    next_value_legal: assert property (
        @(posedge CLK) disable iff (RST) 1'b1 |=> ((DATA_OUT == 8'hf4) || (DATA_OUT == 8'hc2))
    );

// If DATA_OUT is 0xc2, it must have come from a previous 0xf4 (not in reset).
    c2_implies_prev_f4: assert property (
        @(posedge CLK) disable iff (RST) (DATA_OUT == 8'hc2) |-> ##1 (DATA_OUT == 8'hf4)
    );

// If DATA_OUT is 0xf4 and previous was not 0xf4, previous must have been 0xc2.
    f4_implies_prev_c2: assert property (
        @(posedge CLK) disable iff (RST) (DATA_OUT == 8'hf4) && $past(DATA_OUT != 8'hf4) |-> ##1 (DATA_OUT == 8'hc2)
    );

// Y must match the RTL combinational equation.
    check_y_matches_rtl_equation: assert property (
        @(posedge clk)
        Y == (
            ((A1 & A2) |
             (VPWR & !VGND & !A1 & A2) |
             (!VPWR & VGND & A1 & !A2)) &
            !B1_N &
            !(VGND & VPB & VNB)
        )
    );

// VGND and VPB and VNB all high must force Y low.
    check_vgnd_vpb_vnb_high_force_y_low: assert property (
        @(posedge clk)
        (VGND & VPB & VNB) |-> !Y
    );

// Y high requires not all of VGND, VPB, and VNB to be high.
    check_y_high_requires_not_all_three_high: assert property (
        @(posedge clk)
        Y |-> !(VGND & VPB & VNB)
    );

// Upper out bit equals previous in[3].
    check_out_msb_from_in3: assert property (
        @(posedge clk) 1'b1 |=> (out[1] == $past(in[3]))
    );

// Lower out bit equals previous in[2].
    check_out_lsb_from_in2: assert property (
        @(posedge clk) 1'b1 |=> (out[0] == $past(in[2]))
    );

// Reset drives data_out low on the next clock.
    check_reset_clears_output: assert property (
        @(posedge clk) rst |=> (data_out == 1'b0)
    );

// If all inputs are 0, X must be 0.
    check_x_zero_when_all_zero: assert property (
        @(posedge clk) (!A && !B && !C) |-> (X == 1'b0)
    );

// X high implies at least one input is high.
    check_x_high_implies_any_one: assert property (
        @(posedge clk) X |-> (A || B || C)
    );

// No reset in RTL; assertions are always active.

    // Shift amount 00 passes data through unchanged.
    check_shift_00_passthrough: assert property (
        @(posedge clk) (shift_amount == 2'b00) |-> (result == data)
    );

// Shift amount 01 shifts left by 1 and inserts 0 in bit 0.
    check_shift_01_left1: assert property (
        @(posedge clk) (shift_amount == 2'b01) |-> (result == {data[2:0], 1'b0})
    );

// Shift amount 10 shifts left by 2 and inserts 00 in bits [1:0].
    check_shift_10_left2: assert property (
        @(posedge clk) (shift_amount == 2'b10) |-> (result == {data[1:0], 2'b00})
    );

// Shift amount 11 shifts left by 3 and inserts 000 in bits [2:0].
    check_shift_11_left3: assert property (
        @(posedge clk) (shift_amount == 2'b11) |-> (result == {data[0], 3'b000})
    );

// Result always matches the selected shift function.
    check_functional_equivalence: assert property (
        @(posedge clk)
            result == ((shift_amount == 2'b00) ? data :
                       (shift_amount == 2'b01) ? {data[2:0], 1'b0} :
                       (shift_amount == 2'b10) ? {data[1:0], 2'b00} :
                                                  {data[0], 3'b000})
    );

// Result must be 00 when inputs are equal.
    check_equal_maps_zero: assert property (
        @(posedge clk) (in0 == in1) |-> (result == 2'b00)
    );

// Result must be 01 when in0 is greater than in1.
    check_greater_maps_one: assert property (
        @(posedge clk) (in0 > in1) |-> (result == 2'b01)
    );

// Result must be 10 when in0 is less than in1.
    check_less_maps_two: assert property (
        @(posedge clk) (in0 < in1) |-> (result == 2'b10)
    );

// Result must never be 11.
    check_result_never_three: assert property (
        @(posedge clk) (result != 2'b11)
    );

// DE high loads D on the next clock.
    check_de_loads_d: assert property (
        @(posedge CLK) DE |=> (Q == $past(D))
    );

// DE high has priority over SCE when both are high.
    check_de_priority_over_sce: assert property (
        @(posedge CLK) (DE && SCE) |=> (Q == $past(D))
    );

// SCE high loads SCD when DE is low.
    check_sce_loads_scd: assert property (
        @(posedge CLK) (!DE && SCE) |=> (Q == $past(SCD))
    );

// With both controls low, Q holds its previous value.
    check_hold_when_idle: assert property (
        @(posedge CLK) (!DE && !SCE) |=> (Q == $past(Q))
    );

// Sum equals 4-bit addition of A and B.
    check_sum_matches_addition: assert property (
        @(posedge clk) S == (A + B)
    );

// Carry-out equals overflow of 4-bit addition.
    check_cout_matches_overflow: assert property (
        @(posedge clk) Cout == ((A + B) > 4'hF)
    );

// When no overflow, sum is 4 bits and carry is 0.
    check_no_overflow_result: assert property (
        @(posedge clk) ((A + B) <= 4'hF) |-> (S[3:0] == (A + B)) && (Cout == 1'b0)
    );

// When overflow, sum is truncated and carry is 1.
    check_overflow_result: assert property (
        @(posedge clk) ((A + B) > 4'hF) |-> (S[3:0] == (A + B)) && (Cout == 1'b1)
    );

// Zero on B passes A through with no carry.
    check_b_zero_passthrough: assert property (
        @(posedge clk) (B == 4'h0) |-> (S == A) && (Cout == 1'b0)
    );

// Zero on A passes B through with no carry.
    check_a_zero_passthrough: assert property (
        @(posedge clk) (A == 4'h0) |-> (S == B) && (Cout == 1'b0)
    );

// Clock: CLK (posedge). Reset: AR active-low, asynchronous.
    // Logic: sequential with asynchronous reset; Q is registered with add-on-e condition.

    // When AR is LOW at a clock edge, Q becomes zero on the next clock.
    check_async_reset_clears_q: assert property (
        @(posedge CLK) !AR |=> (Q == 23'b0)
    );

// When E is HIGH and D is zero, Q holds its value on the next clock.
    check_hold_when_e_high_d_zero: assert property (
        @(posedge CLK) disable iff (!AR) (E && (D == 23'b0)) |=> (Q == $past(Q))
    );

// When E is LOW, Q holds its value on the next clock.
    check_hold_when_e_low: assert property (
        @(posedge CLK) disable iff (!AR) (!E) |=> (Q == $past(Q))
    );

// All A inputs high force Y low.
    check_a_triplet_forces_y_low: assert property (
        @(posedge clk) (A1 & A2 & A3) |-> !Y
    );

// All B inputs high force Y low.
    check_b_triplet_forces_y_low: assert property (
        @(posedge clk) (B1 & B2) |-> !Y
    );

// A low and B low together force Y high.
    check_a0_b0_forces_y_high: assert property (
        @(posedge clk) (!A1 & !A2 & !A3 & !B1 & !B2) |-> Y
    );

// A low and B high together force Y low.
    check_a0_b12_forces_y_low: assert property (
        @(posedge clk) (!A1 & !A2 & !A3 & B1 & B2) |-> !Y
    );

// A high and B low together force Y low.
    check_a12_b0_forces_y_low: assert property (
        @(posedge clk) (A1 & A2 & A3 & !B1 & !B2) |-> !Y
    );

// A high and B high together force Y low.
    check_a12_b12_forces_y_low: assert property (
        @(posedge clk) (A1 & A2 & A3 & B1 & B2) |-> !Y
    );

// 0 maps to 00000000.
    check_map_0: assert property (
        @(posedge clk) (D == 4'h0) |-> (BCD == 8'h00)
    );

// 1 maps to 00000001.
    check_map_1: assert property (
        @(posedge clk) (D == 4'h1) |-> (BCD == 8'h01)
    );

// 2 maps to 00000010.
    check_map_2: assert property (
        @(posedge clk) (D == 4'h2) |-> (BCD == 8'h02)
    );

// 3 maps to 00000011.
    check_map_3: assert property (
        @(posedge clk) (D == 4'h3) |-> (BCD == 8'h03)
    );

// 4 maps to 00000100.
    check_map_4: assert property (
        @(posedge clk) (D == 4'h4) |-> (BCD == 8'h04)
    );

// 5 maps to 00000101.
    check_map_5: assert property (
        @(posedge clk) (D == 4'h5) |-> (BCD == 8'h05)
    );

// 6 maps to 00000110.
    check_map_6: assert property (
        @(posedge clk) (D == 4'h6) |-> (BCD == 8'h06)
    );

// 7 maps to 00000111.
    check_map_7: assert property (
        @(posedge clk) (D == 4'h7) |-> (BCD == 8'h07)
    );

// 8 maps to 00001000.
    check_map_8: assert property (
        @(posedge clk) (D == 4'h8) |-> (BCD == 8'h08)
    );

// 9 maps to 00001001.
    check_map_9: assert property (
        @(posedge clk) (D == 4'h9) |-> (BCD == 8'h09)
    );

// 10 maps to 00010000.
    check_map_10: assert property (
        @(posedge clk) (D == 4'hA) |-> (BCD == 8'h10)
    );

// 11 maps to 00010001.
    check_map_11: assert property (
        @(posedge clk) (D == 4'hB) |-> (BCD == 8'h11)
    );

// 12 maps to 00010010.
    check_map_12: assert property (
        @(posedge clk) (D == 4'hC) |-> (BCD == 8'h12)
    );

// 13 maps to 00010011.
    check_map_13: assert property (
        @(posedge clk) (D == 4'hD) |-> (BCD == 8'h13)
    );

// 14 maps to 00010100.
    check_map_14: assert property (
        @(posedge clk) (D == 4'hE) |-> (BCD == 8'h14)
    );

// 15 maps to 00010101.
    check_map_15: assert property (
        @(posedge clk) (D == 4'hF) |-> (BCD == 8'h15)
    );

// Output is always one of the exact encodings listed.
    check_output_encoding: assert property (
        @(posedge clk) 1'b1 |-> (
            (BCD == 8'h00) || (BCD == 8'h01) || (BCD == 8'h02) || (BCD == 8'h03) ||
            (BCD == 8'h04) || (BCD == 8'h05) || (BCD == 8'h06) || (BCD == 8'h07) ||
            (BCD == 8'h08) || (BCD == 8'h09) || (BCD == 8'h10) || (BCD == 8'h11) ||
            (BCD == 8'h12) || (BCD == 8'h13) || (BCD == 8'h14) || (BCD == 8'h15)
        )
    );

// SUM is the 3-input XOR of A, B, and CI.
    check_sum_is_xor3: assert property (
        @(posedge clk) SUM == (A ^ B ^ CI)
    );

// COUT is the majority function of A, B, and CI.
    check_cout_is_majority: assert property (
        @(posedge clk) COUT == ((A & B) | (A & CI) | (B & CI))
    );

// All-zero inputs produce zero SUM and zero COUT.
    check_zero_inputs: assert property (
        @(posedge clk) (!A && !B && !CI) |-> (!SUM && !COUT)
    );

// Exactly one high input produces SUM high and COUT low.
    check_one_hot_inputs: assert property (
        @(posedge clk)
        ((A && !B && !CI) || (!A && B && !CI) || (!A && !B && CI))
        |-> (SUM && !COUT)
    );

// Exactly two high inputs produce SUM low and COUT high.
    check_two_hot_inputs: assert property (
        @(posedge clk)
        ((A && B && !CI) || (A && !B && CI) || (!A && B && CI))
        |-> (!SUM && COUT)
    );

// All-high inputs produce SUM high and COUT high.
    check_all_high_inputs: assert property (
        @(posedge clk) (A && B && CI) |-> (SUM && COUT)
    );

// out_or_bitwise must match the bitwise OR of a and b.
    check_or_bitwise_matches_inputs: assert property (
        @(posedge clk) out_or_bitwise == (a | b)
    );

// out_or_logical must match the logical OR of out_or_bitwise.
    check_or_logical_matches_or_bitwise: assert property (
        @(posedge clk) out_or_logical == |out_or_bitwise
    );

// out_not must match the concatenation of the inverted inputs.
    check_not_concat_matches_inputs: assert property (
        @(posedge clk) out_not == {~a, ~b}
    );

// The upper three bits of out_not must be the inverted a values.
    check_not_upper_matches_a: assert property (
        @(posedge clk) out_not[5:3] == ~a
    );

// The lower three bits of out_not must be the inverted b values.
    check_not_lower_matches_b: assert property (
        @(posedge clk) out_not[2:0] == ~b
    );

// A high out_or_logical implies at least one input bit is high.
    check_or_logical_high_implies_any_input_high: assert property (
        @(posedge clk) out_or_logical |-> (|a || |b)
    );

// Any high input bit must drive out_or_logical high.
    check_any_input_high_implies_or_logical_high: assert property (
        @(posedge clk) (|a || |b) |-> out_or_logical
    );

// A low out_or_logical implies all input bits are low.
    check_or_logical_low_implies_all_inputs_low: assert property (
        @(posedge clk) !out_or_logical |-> (!|a && !|b)
    );

// All low input bits must drive out_or_logical low.
    check_all_inputs_low_implies_or_logical_low: assert property (
        @(posedge clk) (!|a && !|b) |-> !out_or_logical
    );

// Reset drives count to zero on the next clock.
    check_reset_clears_count: assert property (
        @(posedge clk) reset |=> (count == 4'h0)
    );

// When not at max, count increments by one on the next clock.
    check_count_increments: assert property (
        @(posedge clk) disable iff (reset)
        (count != 4'hF) |=> (count == ($past(count) + 4'h1))
    );

// When at max, count wraps to zero on the next clock.
    check_count_wraps: assert property (
        @(posedge clk) disable iff (reset)
        (count == 4'hF) |=> (count == 4'h0)
    );

// All four high inputs force Y low.
    check_all_inputs_high_force_y_low: assert property (
        @(posedge clk) (A1 && A2 && B1 && C1) |-> !Y
    );

// A low Y requires at least one high input.
    check_y_low_requires_some_input_high: assert property (
        @(posedge clk) !Y |-> (A1 || A2 || B1 || C1)
    );

// X matches the RTL combinational equation.
    check_function_equivalence: assert property (
        @(posedge clk) X == ((~(A1 & A2)) & (A1 ^ B1)) | ((~B1) & A1)
    );

// When A1 and B1 differ, X must be high.
    check_a1_xor_b1_forces_x_high: assert property (
        @(posedge clk) (A1 ^ B1) |-> X
    );

// A high X requires either A1 and B1 to differ or B1 to be low.
    check_x_high_has_valid_cause: assert property (
        @(posedge clk) X |-> ((A1 ^ B1) || !B1)
    );

// Y matches the RTL expression for all inputs.
    check_functional_equivalence: assert property (
        @(posedge clk) Y == ((invert) ? ~(~A + 4'b0001) : (~A + 4'b0001))
    );

// When invert is low, Y is the 4-bit sum of ~A and 1.
    check_sum_when_not_invert: assert property (
        @(posedge clk) !invert |-> (Y == (~A + 4'b0001))
    );

// The least-significant bit follows the RTL expression.
    check_lsb_equation: assert property (
        @(posedge clk) Y[0] == ((invert) ? ~A[0] : (~A[0] ^ 1'b1))
    );

// With invert low, Y[1] is the RTL sum of ~A[1] and 1.
    check_bit1_sum_when_not_invert: assert property (
        @(posedge clk) (!invert && (A[0] == 1'b0)) |-> (Y[1] == (~A[1] ^ 1'b1))
    );

// With invert low, Y[1] is the RTL sum of ~A[1] and 0.
    check_bit1_sum_when_not_invert_carry: assert property (
        @(posedge clk) (!invert && (A[0] == 1'b1)) |-> (Y[1] == (~A[1]))
    );

// With invert high, Y[1] is the RTL complement of ~A[1].
    check_bit1_complement_when_invert: assert property (
        @(posedge clk) (invert && (A[0] == 1'b0)) |-> (Y[1] == ~A[1])
    );

// With invert high, Y[1] is the RTL complement of ~A[1] with carry.
    check_bit1_complement_when_invert_carry: assert property (
        @(posedge clk) (invert && (A[0] == 1'b1)) |-> (Y[1] == (~A[1] ^ 1'b1))
    );

// With invert low, Y[2] is the RTL sum of ~A[2] and 1.
    check_bit2_sum_when_not_invert: assert property (
        @(posedge clk) (!invert && (A[1:0] == 2'b00)) |-> (Y[2] == (~A[2] ^ 1'b1))
    );

// With invert low, Y[2] is the RTL sum of ~A[2] and 0.
    check_bit2_sum_when_not_invert_carry: assert property (
        @(posedge clk) (!invert && (A[1:0] == 2'b01)) |-> (Y[2] == (~A[2]))
    );

// With invert high, Y[2] is the RTL complement of ~A[2].
    check_bit2_complement_when_invert: assert property (
        @(posedge clk) (invert && (A[1:0] == 2'b00)) |-> (Y[2] == ~A[2])
    );

// With invert high, Y[2] is the RTL complement of ~A[2] with carry.
    check_bit2_complement_when_invert_carry: assert property (
        @(posedge clk) (invert && (A[1:0] == 2'b01)) |-> (Y[2] == (~A[2] ^ 1'b1))
    );

// Y equals (~B) & (~A_N).
    check_function_equivalence: assert property (
        @(posedge clk) Y == ((~B) & (~A_N))
    );

// When both inputs are LOW, Y must be HIGH.
    check_both_low_drives_high: assert property (
        @(posedge clk) (!B && !A_N) |-> (Y == 1'b1)
    );

// If B is HIGH, Y must be LOW.
    check_b_high_drives_low: assert property (
        @(posedge clk) (B == 1'b1) |-> (Y == 1'b0)
    );

// If A_N is HIGH, Y must be LOW.
    check_an_high_drives_low: assert property (
        @(posedge clk) (A_N == 1'b1) |-> (Y == 1'b0)
    );

// If Y is HIGH, both inputs must be LOW.
    check_high_output_requires_both_low: assert property (
        @(posedge clk) (Y == 1'b1) |-> (!B && !A_N)
    );

// If Y is LOW, at least one input must be HIGH.
    check_low_output_requires_some_high: assert property (
        @(posedge clk) (Y == 1'b0) |-> (B || A_N)
    );

// Y matches the implemented OR-OR-NAND function.
    check_y_function: assert property (
        @(posedge clk) Y == ~( (A1 | A2) & (B1 | B2) & C1 )
    );

// C1 low forces Y high.
    check_c1_low_forces_y_high: assert property (
        @(posedge clk) !C1 |-> Y
    );

// With C1 high, both A and B pairs low force Y high.
    check_ab_pairs_low_force_y_high: assert property (
        @(posedge clk) C1 && (!A1 && !A2 && !B1 && !B2) |-> Y
    );

// With C1 high, any A pair high with any B pair high forces Y low.
    check_any_ab_pair_high_forces_y_low: assert property (
        @(posedge clk) C1 && ((A1 || A2) && (B1 || B2)) |-> !Y
    );

// A1 high with B1 high with C1 high forces Y low.
    check_a1_b1_high_force_y_low: assert property (
        @(posedge clk) C1 && A1 && B1 |-> !Y
    );

// A2 high with B2 high with C1 high forces Y low.
    check_a2_b2_high_force_y_low: assert property (
        @(posedge clk) C1 && A2 && B2 |-> !Y
    );

// A1 high with B2 high with C1 high forces Y low.
    check_a1_b2_high_force_y_low: assert property (
        @(posedge clk) C1 && A1 && B2 |-> !Y
    );

// A2 high with B1 high with C1 high forces Y low.
    check_a2_b1_high_force_y_low: assert property (
        @(posedge clk) C1 && A2 && B1 |-> !Y
    );

// Out must match the RTL mux expression.
    check_mux_function: assert property (
        @(posedge clk)
        out == ((sel1 & sel0) ? in3 :
                (sel1 & ~sel0) ? in2 :
                (~sel1 & sel0) ? in1 :
                in0)
    );

// When sel is 00, out must select in0.
    check_sel_00_selects_in0: assert property (
        @(posedge clk)
        (!sel1 && !sel0) |-> (out == in0)
    );

// When sel is 01, out must select in1.
    check_sel_01_selects_in1: assert property (
        @(posedge clk)
        (!sel1 && sel0) |-> (out == in1)
    );

// When sel is 10, out must select in2.
    check_sel_10_selects_in2: assert property (
        @(posedge clk)
        (sel1 && !sel0) |-> (out == in2)
    );

// When sel is 11, out must select in3.
    check_sel_11_selects_in3: assert property (
        @(posedge clk)
        (sel1 && sel0) |-> (out == in3)
    );

// oRD_BUSY is permanently asserted low.
    check_rd_busy_low: assert property (
        @(posedge iCLOCK) disable iff (!inRESET) (oRD_BUSY == 1'b0)
    );

// oRD_HIT is permanently asserted low.
    check_rd_hit_low: assert property (
        @(posedge iCLOCK) disable iff (!inRESET) (oRD_HIT == 1'b0)
    );

// oRD_DATA is permanently asserted zero.
    check_rd_data_zero: assert property (
        @(posedge iCLOCK) disable iff (!inRESET) (oRD_DATA == 32'h0)
    );

// oRD_MMU_FLAGS is permanently asserted zero.
    check_rd_mmu_zero: assert property (
        @(posedge iCLOCK) disable iff (!inRESET) (oRD_MMU_FLAGS == 12'h0)
    );

// oUP_BUSY is permanently asserted low.
    check_up_busy_low: assert property (
        @(posedge iCLOCK) disable iff (!inRESET) (oUP_BUSY == 1'b0)
    );

// oWR_BUSY is permanently asserted low.
    check_wr_busy_low: assert property (
        @(posedge iCLOCK) disable iff (!inRESET) (oWR_BUSY == 1'b0)
    );

// Result 00 only occurs when A equals B.
    check_equal_maps_zero: assert property (
        @(posedge clk) (A == B) |-> (result == 2'b00)
    );

// Result 01 only occurs when A is greater than B.
    check_greater_maps_one: assert property (
        @(posedge clk) (A > B) |-> (result == 2'b01)
    );

// Result 10 only occurs when A is less than B.
    check_less_maps_two: assert property (
        @(posedge clk) (A < B) |-> (result == 2'b10)
    );

// Result 11 is never produced by this comparator.
    check_no_three: assert property (
        @(posedge clk) (result != 2'b11)
    );

// Result is always one of the three implemented encodings.
    check_result_legal: assert property (
        @(posedge clk) (result == 2'b00) || (result == 2'b01) || (result == 2'b10)
    );

// Output matches the RTL AND/OR equation.
    check_function_equation: assert property (
        @(posedge clk) out == ((~sel & in0) | (sel & in1))
    );

// When sel is low, out follows in0.
    check_sel_low_routes_in0: assert property (
        @(posedge clk) !sel |-> (out == in0)
    );

// When sel is high, out follows in1.
    check_sel_high_routes_in1: assert property (
        @(posedge clk) sel |-> (out == in1)
    );

// If both inputs are low, out must be low.
    check_both_inputs_low_drive_out_low: assert property (
        @(posedge clk) (!in0 && !in1) |-> (!out)
    );

// If both inputs are high, out must be high.
    check_both_inputs_high_drive_out_high: assert property (
        @(posedge clk) (in0 && in1) |-> (out)
    );

// A high output requires at least one high input.
    check_out_high_requires_some_high_input: assert property (
        @(posedge clk) out |-> (in0 || in1)
    );

// X must match the RTL Boolean equation.
    check_x_equation: assert property (
        @(posedge clk) X == ((A & B) | (C | D) | !(E & F) | !(G | H))
    );

// A and B high must force X high.
    check_and0_forces_x_high: assert property (
        @(posedge clk) (A && B) |-> X
    );

// C or D high must force X high.
    check_or0_forces_x_high: assert property (
        @(posedge clk) (C || D) |-> X
    );

// E and F low must force X high.
    check_and1_low_forces_x_high: assert property (
        @(posedge clk) (!E && !F) |-> X
    );

// G or H high must force X high.
    check_or1_low_forces_x_high: assert property (
        @(posedge clk) (!G && !H) |-> X
    );

// With all terms inactive, X must be low.
    check_all_terms_inactive_forces_x_low: assert property (
        @(posedge clk) (!(A && B) && !(C || D) && (E && F) && (G || H)) |-> !X
    );

// Addition mode drives add_out to a+b and the other outputs to zero.
    check_add_mode: assert property (
        @(posedge clk) (op == 2'b00) |-> (add_out == (a + b)) && (sub_out == 8'sd0) && (mul_out == 8'sd0) && (div_out == 8'sd0)
    );

// Subtraction mode drives sub_out to a-b and the other outputs to zero.
    check_sub_mode: assert property (
        @(posedge clk) (op == 2'b01) |-> (add_out == 8'sd0) && (sub_out == (a - b)) && (mul_out == 8'sd0) && (div_out == 8'sd0)
    );

// When op is 00, add_out equals a+b and the other outputs are zero.
    check_add_out_when_add: assert property (
        @(posedge clk) (op == 2'b00) |-> (add_out == (a + b))
    );

// When op is 01, sub_out equals a-b and the other outputs are zero.
    check_sub_out_when_sub: assert property (
        @(posedge clk) (op == 2'b01) |-> (sub_out == (a - b))
    );

// Y equals A - B on each sampled cycle.
    check_functional_equivalence: assert property (
        @(posedge clk) Y == (A - B)
    );

// When B is zero, Y equals A.
    check_zero_subtrahend: assert property (
        @(posedge clk) (B == 4'h0) |-> (Y == A)
    );

// When A equals B, Y is zero.
    check_equal_operands_zero: assert property (
        @(posedge clk) (A == B) |-> (Y == 4'h0)
    );

// Subtracting 1 from 0 yields 15 (4-bit wrap).
    check_wrap_from_zero: assert property (
        @(posedge clk) ((A == 4'h0) && (B == 4'h1)) |-> (Y == 4'hF)
    );

// Subtracting 1 from 1 yields 0.
    check_wrap_from_one: assert property (
        @(posedge clk) ((A == 4'h1) && (B == 4'h1)) |-> (Y == 4'h0)
    );

// Subtracting 1 from 2 yields 1.
    check_wrap_from_two: assert property (
        @(posedge clk) ((A == 4'h2) && (B == 4'h1)) |-> (Y == 4'h1)
    );

// Subtracting 1 from 3 yields 2.
    check_wrap_from_three: assert property (
        @(posedge clk) ((A == 4'h3) && (B == 4'h1)) |-> (Y == 4'h2)
    );

// Subtracting 1 from 4 yields 3.
    check_wrap_from_four: assert property (
        @(posedge clk) ((A == 4'h4) && (B == 4'h1)) |-> (Y == 4'h3)
    );

// Subtracting 1 from 5 yields 4.
    check_wrap_from_five: assert property (
        @(posedge clk) ((A == 4'h5) && (B == 4'h1)) |-> (Y == 4'h4)
    );

// Subtracting 1 from 6 yields 5.
    check_wrap_from_six: assert property (
        @(posedge clk) ((A == 4'h6) && (B == 4'h1)) |-> (Y == 4'h5)
    );

// Subtracting 1 from 7 yields 6.
    check_wrap_from_seven: assert property (
        @(posedge clk) ((A == 4'h7) && (B == 4'h1)) |-> (Y == 4'h6)
    );

// Subtracting 1 from 8 yields 7.
    check_wrap_from_eight: assert property (
        @(posedge clk) ((A == 4'h8) && (B == 4'h1)) |-> (Y == 4'h7)
    );

// Subtracting 1 from 9 yields 8.
    check_wrap_from_nine: assert property (
        @(posedge clk) ((A == 4'h9) && (B == 4'h1)) |-> (Y == 4'h8)
    );

// Subtracting 1 from 10 yields 9.
    check_wrap_from_ten: assert property (
        @(posedge clk) ((A == 4'hA) && (B == 4'h1)) |-> (Y == 4'h9)
    );

// Subtracting 1 from 11 yields 10.
    check_wrap_from_eleven: assert property (
        @(posedge clk) ((A == 4'hB) && (B == 4'h1)) |-> (Y == 4'hA)
    );

// Subtracting 1 from 12 yields 11.
    check_wrap_from_twelve: assert property (
        @(posedge clk) ((A == 4'hC) && (B == 4'h1)) |-> (Y == 4'hB)
    );

// Subtracting 1 from 13 yields 12.
    check_wrap_from_thirteen: assert property (
        @(posedge clk) ((A == 4'hD) && (B == 4'h1)) |-> (Y == 4'hC)
    );

// Subtracting 1 from 14 yields 13.
    check_wrap_from_fourteen: assert property (
        @(posedge clk) ((A == 4'hE) && (B == 4'h1)) |-> (Y == 4'hD)
    );

// Subtracting 1 from 15 yields 14.
    check_wrap_from_fifteen: assert property (
        @(posedge clk) ((A == 4'hF) && (B == 4'h1)) |-> (Y == 4'hE)
    );

// Y must implement the NAND of A and B.
    check_nand_function: assert property (
        @(posedge clk) Y == ~(A & B)
    );

// A low forces Y high.
    check_a_low_forces_y_high: assert property (
        @(posedge clk) !A |-> Y
    );

// B low forces Y high.
    check_b_low_forces_y_high: assert property (
        @(posedge clk) !B |-> Y
    );

// Both inputs high force Y low.
    check_both_high_force_y_low: assert property (
        @(posedge clk) (A && B) |-> !Y
    );

// A high and B low force Y high.
    check_a_high_b_low_force_y_high: assert property (
        @(posedge clk) (A && !B) |-> Y
    );

// A low and B high force Y high.
    check_a_low_b_high_force_y_high: assert property (
        @(posedge clk) (!A && B) |-> Y
    );

// y must match the implemented XOR function.
    check_functional_equivalence: assert property (
        @(posedge clk) y == (a ^ b)
    );

// When a is 0, y must equal b.
    check_a_zero_pass_through: assert property (
        @(posedge clk) (a == 1'b0) |-> (y == b)
    );

// When a is 1, y must be the inverse of b.
    check_a_one_inverts_b: assert property (
        @(posedge clk) (a == 1'b1) |-> (y == ~b)
    );

// When b is 0, y must equal a.
    check_b_zero_pass_through: assert property (
        @(posedge clk) (b == 1'b0) |-> (y == a)
    );

// When b is 1, y must be the inverse of a.
    check_b_one_inverts_a: assert property (
        @(posedge clk) (b == 1'b1) |-> (y == ~a)
    );

// Equal inputs must drive y low.
    check_equal_inputs_low: assert property (
        @(posedge clk) (a == b) |-> (y == 1'b0)
    );

// Different inputs must drive y high.
    check_different_inputs_high: assert property (
        @(posedge clk) (a != b) |-> (y == 1'b1)
    );

// Reset clears the counter on the next clock.
    check_reset_clears_count: assert property (
        @(posedge clk) reset |=> (count == 4'b0000)
    );

// When enabled, the counter increments by one on the next clock.
    check_count_increments_when_enabled: assert property (
        @(posedge clk) disable iff (reset) enable |=> (count == ($past(count) + 4'd1))
    );

// When not enabled, the counter holds its value on the next clock.
    check_count_holds_when_disabled: assert property (
        @(posedge clk) disable iff (reset) !enable |=> (count == $past(count))
    );

// The 4-bit counter wraps from 15 back to 0 when enabled.
    check_count_wraps_from_max: assert property (
        @(posedge clk) disable iff (reset) (enable && (count == 4'hF)) |=> (count == 4'h0)
    );

// gray_out[3] captures the previous cycle's binary_in[3].
    check_gray_msb_capture: assert property (
        @(posedge clk) 1'b1 |=> (gray_out[3] == $past(binary_in[3]))
    );

// gray_out[2] is the previous cycle's binary_in[3] XOR binary_in[2].
    check_gray_bit2_xor: assert property (
        @(posedge clk) 1'b1 |=> (gray_out[2] == ($past(binary_in[3]) ^ $past(binary_in[2])))
    );

// gray_out[1] is the previous cycle's binary_in[2] XOR binary_in[1].
    check_gray_bit1_xor: assert property (
        @(posedge clk) 1'b1 |=> (gray_out[1] == ($past(binary_in[2]) ^ $past(binary_in[1])))
    );

// gray_out[0] is the previous cycle's binary_in[1] XOR binary_in[0].
    check_gray_bit0_xor: assert property (
        @(posedge clk) 1'b1 |=> (gray_out[0] == ($past(binary_in[1]) ^ $past(binary_in[0])))
    );

// Clock: clk (posedge). Reset: none. Logic: sequential with enable and select.

    // q captures si when se is high.
    check_se_loads_si: assert property (
        @(posedge clk) se |=> (q == $past(si))
    );

// q captures din when se is low and en is high.
    check_en_loads_din: assert property (
        @(posedge clk) (!se && en) |=> (q == $past(din))
    );

// q holds its value when neither select/enable is asserted.
    check_hold_when_idle: assert property (
        @(posedge clk) (!se && !en) |=> (q == $past(q))
    );

// so is always a direct copy of q.
    check_so_is_q: assert property (
        @(posedge clk) (so == q)
    );

// select=00 routes in0 to out.
    check_select_00_routes_in0: assert property (
        @(posedge clk) (select == 2'b00) |-> (out == in0)
    );

// select=01 routes in1 to out.
    check_select_01_routes_in1: assert property (
        @(posedge clk) (select == 2'b01) |-> (out == in1)
    );

// select=10 routes in2 to out.
    check_select_10_routes_in2: assert property (
        @(posedge clk) (select == 2'b10) |-> (out == in2)
    );

// select=11 routes in3 to out.
    check_select_11_routes_in3: assert property (
        @(posedge clk) (select == 2'b11) |-> (out == in3)
    );

// Out always matches the selected input.
    check_out_matches_selected_input: assert property (
        @(posedge clk)
        (select == 2'b00) || (select == 2'b01) || (select == 2'b10) || (select == 2'b11)
        |-> (out == (select == 2'b00 ? in0 :
                     select == 2'b01 ? in1 :
                     select == 2'b10 ? in2 : in3))
    );

// Result equals bitwise AND of inputs.
    check_result_matches_and: assert property (
        @(posedge clk) result == (a & b)
    );

// Bit 0 equals a[0] & b[0].
    check_bit0_matches_and: assert property (
        @(posedge clk) result[0] == (a[0] & b[0])
    );

// Bit 1 equals a[1] & b[1].
    check_bit1_matches_and: assert property (
        @(posedge clk) result[1] == (a[1] & b[1])
    );

// Bit 2 equals a[2] & b[2].
    check_bit2_matches_and: assert property (
        @(posedge clk) result[2] == (a[2] & b[2])
    );

// Bit 3 equals a[3] & b[3].
    check_bit3_matches_and: assert property (
        @(posedge clk) result[3] == (a[3] & b[3])
    );

// If a is all zeros, result must be all zeros.
    check_zero_a_implies_zero_result: assert property (
        @(posedge clk) (a == 4'b0000) |-> (result == 4'b0000)
    );

// If b is all zeros, result must be all zeros.
    check_zero_b_implies_zero_result: assert property (
        @(posedge clk) (b == 4'b0000) |-> (result == 4'b0000)
    );

// If a is all ones, result equals b.
    check_ones_a_implies_result_eq_b: assert property (
        @(posedge clk) (a == 4'b1111) |-> (result == b)
    );

// If b is all ones, result equals a.
    check_ones_b_implies_result_eq_a: assert property (
        @(posedge clk) (b == 4'b1111) |-> (result == a)
    );

// If a equals b, result equals a.
    check_equal_inputs_implies_result_eq_a: assert property (
        @(posedge clk) (a == b) |-> (result == a)
    );

// Y matches the implemented NOR(AND(A1,A2), B1) function.
    check_functional_equivalence: assert property (
        @(posedge clk) Y == ~((A1 & A2) | B1)
    );

// B1 high forces Y low.
    check_b1_forces_y_low: assert property (
        @(posedge clk) B1 |-> !Y
    );

// A1 and A2 high together force Y low.
    check_a1_a2_high_force_y_low: assert property (
        @(posedge clk) (A1 && A2) |-> !Y
    );

// With B1 low, Y equals the inverted AND of A1 and A2.
    check_b1_low_y_equals_not_a1_a2: assert property (
        @(posedge clk) !B1 |-> (Y == ~(A1 & A2))
    );

// With A1 and A2 low, Y equals the inverted B1.
    check_a1_a2_low_y_equals_not_b1: assert property (
        @(posedge clk) (!A1 && !A2) |-> (Y == ~B1)
    );

// A high Y requires B1 low and at least one of A1 or A2 low.
    check_y_high_requires_b1_low_and_not_both_a1_a2: assert property (
        @(posedge clk) Y |-> (!B1 && (!A1 || !A2))
    );

// A low Y requires B1 high or both A1 and A2 high.
    check_y_low_requires_b1_high_or_both_a1_a2: assert property (
        @(posedge clk) !Y |-> (B1 || (A1 && A2))
    );

// out_final equals (a^b) & (c^d).
    check_function_equivalence: assert property (
        @(posedge clk) out_final == ((a ^ b) & (c ^ d))
    );

// When a^b==0, out_final must be 0.
    check_when_ab_xor0: assert property (
        @(posedge clk) ((a ^ b) == 1'b0) |-> (out_final == 1'b0)
    );

// When c^d==0, out_final must be 0.
    check_when_cd_xor0: assert property (
        @(posedge clk) ((c ^ d) == 1'b0) |-> (out_final == 1'b0)
    );

// When a^b==1 and c^d==1, out_final must be 1.
    check_when_ab_cd_xor1: assert property (
        @(posedge clk) (((a ^ b) == 1'b1) && ((c ^ d) == 1'b1)) |-> (out_final == 1'b1)
    );

// When a^b==1 and c^d==0, out_final must be 0.
    check_when_ab_xor1_cd0: assert property (
        @(posedge clk) (((a ^ b) == 1'b1) && ((c ^ d) == 1'b0)) |-> (out_final == 1'b0)
    );

// When a^b==0 and c^d==1, out_final must be 0.
    check_when_ab0_cd_xor1: assert property (
        @(posedge clk) (((a ^ b) == 1'b0) && ((c ^ d) == 1'b1)) |-> (out_final == 1'b0)
    );

// Sum must equal the 32-bit addition of a and b.
    check_sum_matches_addition: assert property (
        @(posedge clk) sum == (a + b)
    );

// Bit 0 of sum must be the XOR of the LSBs of a and b.
    check_lsb_xor: assert property (
        @(posedge clk) sum[0] == (a[0] ^ b[0])
    );

// 0 maps to 0000.
    check_map_0: assert property (
        @(posedge clk) (in_value == 4'b0000) |-> (out_value == 4'b0000)
    );

// 1 maps to 0001.
    check_map_1: assert property (
        @(posedge clk) (in_value == 4'b0001) |-> (out_value == 4'b0001)
    );

// 2 maps to 0010.
    check_map_2: assert property (
        @(posedge clk) (in_value == 4'b0010) |-> (out_value == 4'b0010)
    );

// 3 maps to 0011.
    check_map_3: assert property (
        @(posedge clk) (in_value == 4'b0011) |-> (out_value == 4'b0011)
    );

// 4 maps to 0100.
    check_map_4: assert property (
        @(posedge clk) (in_value == 4'b0100) |-> (out_value == 4'b0100)
    );

// 5 maps to 0101.
    check_map_5: assert property (
        @(posedge clk) (in_value == 4'b0101) |-> (out_value == 4'b0101)
    );

// 6 maps to 0110.
    check_map_6: assert property (
        @(posedge clk) (in_value == 4'b0110) |-> (out_value == 4'b0110)
    );

// 7 maps to 0111.
    check_map_7: assert property (
        @(posedge clk) (in_value == 4'b0111) |-> (out_value == 4'b0111)
    );

// 8 maps to 1000.
    check_map_8: assert property (
        @(posedge clk) (in_value == 4'b1000) |-> (out_value == 4'b1000)
    );

// 9 maps to 1001.
    check_map_9: assert property (
        @(posedge clk) (in_value == 4'b1001) |-> (out_value == 4'b1001)
    );

// Output is always 0000..1001 or X.
    check_output_range: assert property (
        @(posedge clk) out_value inside {4'b0000,4'b0001,4'b0010,4'b0011,4'b0100,4'b0101,4'b0110,4'b0111,4'b1000,4'b1001,4'bXXXX}
    );

// Y matches the implemented OR-then-NAND function.
    check_function_equivalence: assert property (
        @(posedge clk) Y == ~(B1 & (A1 | A2 | A3))
    );

// With all A inputs low, Y is high.
    check_all_a_low_high: assert property (
        @(posedge clk) !(A1 | A2 | A3) |-> Y
    );

// With B1 low and any A input high, Y is high.
    check_b1_low_any_a_high_high: assert property (
        @(posedge clk) (!B1 && (A1 | A2 | A3)) |-> Y
    );

// Reset clears the registered outputs on the next clock.
    check_reset_clears_outputs: assert property (
        @(posedge clk) reset |=> (out == 16'sd0)
    );

// X must equal A AND SLEEP_B.
    check_function_equivalence: assert property (
        @(posedge clk) X == (A & SLEEP_B)
    );

// When SLEEP_B is LOW, X must be LOW.
    check_sleep_forces_low: assert property (
        @(posedge clk) !SLEEP_B |-> (X == 1'b0)
    );

// When A is LOW, X must be LOW.
    check_a_low_forces_low: assert property (
        @(posedge clk) !A |-> (X == 1'b0)
    );

// When both A and SLEEP_B are HIGH, X must be HIGH.
    check_both_high_drive_high: assert property (
        @(posedge clk) (A && SLEEP_B) |-> (X == 1'b1)
    );

// A HIGH X requires both A and SLEEP_B to be HIGH.
    check_high_output_requires_both_high: assert property (
        @(posedge clk) X |-> (A && SLEEP_B)
    );

// No reset in RTL; sample combinational behavior on clk.

    // When sel1==0, out selects between in0/in1 based on sel0.
    check_sel1_low_selects_in0_in1: assert property (
        @(posedge clk) (sel1 == 1'b0) |-> (out == (sel0 ? in1 : in0))
    );

// When sel1==1, out selects between in2/in3 based on sel0.
    check_sel1_high_selects_in2_in3: assert property (
        @(posedge clk) (sel1 == 1'b1) |-> (out == (sel0 ? in3 : in2))
    );

// When sel0==0, out selects between in0/in2 based on sel1.
    check_sel0_low_selects_in0_in2: assert property (
        @(posedge clk) (sel0 == 1'b0) |-> (out == (sel1 ? in2 : in0))
    );

// When sel0==1, out selects between in1/in3 based on sel1.
    check_sel0_high_selects_in1_in3: assert property (
        @(posedge clk) (sel0 == 1'b1) |-> (out == (sel1 ? in3 : in1))
    );

// With sel1==0 and sel0==0, out equals in0.
    check_sel00_out_in0: assert property (
        @(posedge clk) (sel1 == 1'b0 && sel0 == 1'b0) |-> (out == in0)
    );

// With sel1==0 and sel0==1, out equals in1.
    check_sel01_out_in1: assert property (
        @(posedge clk) (sel1 == 1'b0 && sel0 == 1'b1) |-> (out == in1)
    );

// With sel1==1 and sel0==0, out equals in2.
    check_sel10_out_in2: assert property (
        @(posedge clk) (sel1 == 1'b1 && sel0 == 1'b0) |-> (out == in2)
    );

// With sel1==1 and sel0==1, out equals in3.
    check_sel11_out_in3: assert property (
        @(posedge clk) (sel1 == 1'b1 && sel0 == 1'b1) |-> (out == in3)
    );

// Reset drives count to 0 on the next clock.
    check_reset_clears_count: assert property (
        @(posedge clk) !rst |=> (count == 2'b00)
    );

// When enabled below 3, count increments by 1.
    check_count_increments: assert property (
        @(posedge clk) disable iff (!rst)
        (en && (count != 2'b11)) |=> (count == ($past(count) + 2'b01))
    );

// When enabled at 3, count wraps to 0.
    check_count_wraps: assert property (
        @(posedge clk) disable iff (!rst)
        (en && (count == 2'b11)) |=> (count == 2'b00)
    );

// When disabled, count holds its value.
    check_count_holds_when_disabled: assert property (
        @(posedge clk) disable iff (!rst)
        (!en) |=> (count == $past(count))
    );

// Y must equal the AND of A, B, and C.
    check_y_matches_and: assert property (
        @(posedge clk) Y == (A & B & C)
    );

// A high, B high, and C high must drive Y high.
    check_all_high_drives_y_high: assert property (
        @(posedge clk) (A && B && C) |-> Y
    );

// A low must force Y low.
    check_a_low_forces_y_low: assert property (
        @(posedge clk) !A |-> !Y
    );

// B low must force Y low.
    check_b_low_forces_y_low: assert property (
        @(posedge clk) !B |-> !Y
    );

// C low must force Y low.
    check_c_low_forces_y_low: assert property (
        @(posedge clk) !C |-> !Y
    );

// Y high implies all three inputs are high.
    check_y_high_requires_all_high: assert property (
        @(posedge clk) Y |-> (A && B && C)
    );

// Y must equal the AND of A, B, and C.
    check_y_matches_and: assert property (
        @(posedge clk) Y == (A & B & C)
    );

// A high with B and C high must drive Y high.
    check_y_high_when_all_inputs_high: assert property (
        @(posedge clk) (A && B && C) |-> Y
    );

// A low must force Y low.
    check_y_low_when_a_low: assert property (
        @(posedge clk) !A |-> !Y
    );

// B low must force Y low.
    check_y_low_when_b_low: assert property (
        @(posedge clk) !B |-> !Y
    );

// C low must force Y low.
    check_y_low_when_c_low: assert property (
        @(posedge clk) !C |-> !Y
    );

// X must equal the implemented O211A function.
    check_function_equivalence: assert property (
        @(posedge clk) X == ((A1 | A2) & B1 & C1)
    );

// B1 low forces X low.
    check_b1_low_forces_x_low: assert property (
        @(posedge clk) !B1 |-> !X
    );

// C1 low forces X low.
    check_c1_low_forces_x_low: assert property (
        @(posedge clk) !C1 |-> !X
    );

// A1 high with B1 and C1 high drives X high.
    check_a1_with_b1_c1_high_drives_x_high: assert property (
        @(posedge clk) (A1 && B1 && C1) |-> X
    );

// A2 high with B1 and C1 high drives X high.
    check_a2_with_b1_c1_high_drives_x_high: assert property (
        @(posedge clk) (A2 && B1 && C1) |-> X
    );

// X high requires B1, C1, and at least one A input high.
    check_x_high_requires_all_enables: assert property (
        @(posedge clk) X |-> (B1 && C1 && (A1 || A2))
    );

// Addition opcode returns the low byte of a + b.
    check_add_result: assert property (
        @(posedge clk) (op == 2'b00) |-> (result == ((a + b) & 8'hFF))
    );

// Subtraction opcode returns the low byte of a - b.
    check_sub_result: assert property (
        @(posedge clk) (op == 2'b01) |-> (result == ((a - b) & 8'hFF))
    );

// Division by zero returns 0xFF.
    check_div_zero_result: assert property (
        @(posedge clk) (op == 2'b11 && b == 8'h00) |-> (result == 8'hFF)
    );

// S=00 routes C to Y.
    check_select_00_routes_c: assert property (
        @(posedge clk) (S == 2'b00) |-> (Y == C)
    );

// S=01 routes D to Y.
    check_select_01_routes_d: assert property (
        @(posedge clk) (S == 2'b01) |-> (Y == D)
    );

// S=10 routes A to Y.
    check_select_10_routes_a: assert property (
        @(posedge clk) (S == 2'b10) |-> (Y == A)
    );

// S=11 routes B to Y.
    check_select_11_routes_b: assert property (
        @(posedge clk) (S == 2'b11) |-> (Y == B)
    );

// I equals 12'b000000000001 implies O is 1.
    check_one_implies_o_one: assert property (
        @(posedge clk) (I == 12'b000000000001) |-> (O == 1'b1)
    );

// I equals 12'b000000000010 implies O is 0.
    check_two_implies_o_zero: assert property (
        @(posedge clk) (I == 12'b000000000010) |-> (O == 1'b0)
    );

// X must equal the OR of the two 3-input AND terms.
    check_function_equivalence: assert property (
        @(posedge clk) X == ((A1 & A2 & A3) | (B1 & B2))
    );

// All three A inputs high must drive X high.
    check_a_triplet_sets_x: assert property (
        @(posedge clk) (A1 & A2 & A3) |-> X
    );

// Both B inputs high must drive X high.
    check_b_pair_sets_x: assert property (
        @(posedge clk) (B1 & B2) |-> X
    );

// X low implies neither AND term is satisfied.
    check_x_low_implies_no_term: assert property (
        @(posedge clk) !X |-> (!(A1 & A2 & A3) && !(B1 & B2))
    );

// A high X must come from at least one AND term.
    check_x_high_implies_some_term: assert property (
        @(posedge clk) X |-> (A1 & A2 & A3) || (B1 & B2)
    );

// Reset clears all outputs.
    check_reset_clears_outputs: assert property (
        @(posedge clk) reset |-> (EQ == 1'b0) && (GT == 1'b0) && (LT == 1'b0)
    );

// When disabled, all outputs are low.
    check_disabled_clears_outputs: assert property (
        @(posedge clk) disable iff (reset) (!enable) |-> (EQ == 1'b0) && (GT == 1'b0) && (LT == 1'b0)
    );

// EQ, GT, and LT are never asserted together.
    check_outputs_mutex: assert property (
        @(posedge clk) disable iff (reset) !(EQ && GT && LT)
    );

// add is the 4-bit sum of A and B.
    check_add_result: assert property (
        @(posedge clk) add == (A + B)
    );

// sub is the 4-bit difference of A and B.
    check_sub_result: assert property (
        @(posedge clk) sub == (A - B)
    );

// X must equal the 4-input AND of A, B, C, and D.
    check_and_function: assert property (
        @(posedge clk) X == (A & B & C & D)
    );

// A low forces X low.
    check_a_low_forces_x_low: assert property (
        @(posedge clk) !A |-> !X
    );

// B low forces X low.
    check_b_low_forces_x_low: assert property (
        @(posedge clk) !B |-> !X
    );

// C low forces X low.
    check_c_low_forces_x_low: assert property (
        @(posedge clk) !C |-> !X
    );

// D low forces X low.
    check_d_low_forces_x_low: assert property (
        @(posedge clk) !D |-> !X
    );

// All inputs high drive X high.
    check_all_high_drives_x_high: assert property (
        @(posedge clk) (A & B & C & D) |-> X
    );

// X high implies all inputs are high.
    check_x_high_implies_all_high: assert property (
        @(posedge clk) X |-> (A & B & C & D)
    );

// min must be less than or equal to a.
    check_min_le_a: assert property (
        @(posedge clk) min <= a
    );

// min must be less than or equal to b.
    check_min_le_b: assert property (
        @(posedge clk) min <= b
    );

// min must be less than or equal to c.
    check_min_le_c: assert property (
        @(posedge clk) min <= c
    );

// min must be less than or equal to d.
    check_min_le_d: assert property (
        @(posedge clk) min <= d
    );

// free3 with tm_count==3 selects 0011.
    check_free3_tm3: assert property (
        @(posedge clk) (free3 && (tm_count == 2'b11)) |-> (fifowp_inc == 4'b0011)
    );

// tm_count==0 selects 0000.
    check_tm0: assert property (
        @(posedge clk) (tm_count == 2'b00) |-> (fifowp_inc == 4'b0000)
    );

// free2 with tm_count==0 selects 0000.
    check_free2_tm0: assert property (
        @(posedge clk) (free2 && (tm_count == 2'b00)) |-> (fifowp_inc == 4'b0000)
    );

// free3 with tm_count==0 selects 0000.
    check_free3_tm0: assert property (
        @(posedge clk) (free3 && (tm_count == 2'b00)) |-> (fifowp_inc == 4'b0000)
    );

// Sum output matches the 4-bit addition of A, B, and CIN.
    check_sum_matches_addition: assert property (
        @(posedge clk) S == (A + B + CIN)
    );

// COUT matches the carry-out bit of the 4-bit addition.
    check_cout_matches_carry: assert property (
        @(posedge clk) COUT == ((A + B + CIN) >= 5'd16)
    );

// Zero inputs produce a zero sum and no carry.
    check_zero_inputs: assert property (
        @(posedge clk) (A == 4'd0 && B == 4'd0 && CIN == 1'b0) |-> (S == 4'd0 && COUT == 1'b0)
    );

// Maximum inputs produce 4'hF with carry-out asserted.
    check_max_inputs: assert property (
        @(posedge clk) (A == 4'hF && B == 4'hF && CIN == 1'b1) |-> (S == 4'hF && COUT == 1'b1)
    );

// Adding zero with no carry-in passes A through unchanged.
    check_a_passthrough_when_b_zero: assert property (
        @(posedge clk) (B == 4'd0 && CIN == 1'b0) |-> (S == A && COUT == 1'b0)
    );

// Adding zero with no carry-in passes B through unchanged.
    check_b_passthrough_when_a_zero: assert property (
        @(posedge clk) (A == 4'd0 && CIN == 1'b0) |-> (S == B && COUT == 1'b0)
    );

// A carry-in increments 4'hF to 4'h0 with carry-out asserted.
    check_cin_increments_max: assert property (
        @(posedge clk) (A == 4'hF && B == 4'd0 && CIN == 1'b1) |-> (S == 4'h0 && COUT == 1'b1)
    );

// A carry-in increments 4'hF with B==1 to 4'h1 with carry-out asserted.
    check_cin_with_b_one: assert property (
        @(posedge clk) (A == 4'hF && B == 4'd1 && CIN == 1'b1) |-> (S == 4'h1 && COUT == 1'b1)
    );

// SUM is the XOR of A, B, and inverted CIN.
    check_sum_function: assert property (
        @(posedge clk) SUM == (A ^ B ^ ~CIN)
    );

// COUT is the majority function of A, B, and inverted CIN.
    check_cout_function: assert property (
        @(posedge clk) COUT == ((A & B) | (A & ~CIN) | (B & ~CIN))
    );

// Reset clears the counter on the next clock.
    check_reset_clears_count: assert property (
        @(posedge clk) reset |=> (count == 2'b00)
    );

// When enabled, the counter increments by one on the next clock.
    check_count_increments_when_enabled: assert property (
        @(posedge clk) disable iff (reset) enable |=> (count == ($past(count) + 2'd1))
    );

// When not enabled, the counter holds its value on the next clock.
    check_count_holds_when_disabled: assert property (
        @(posedge clk) disable iff (reset) !enable |=> (count == $past(count))
    );

// The 2-bit counter wraps from 3 to 0 when enabled.
    check_count_wraps_from_max: assert property (
        @(posedge clk) disable iff (reset) (enable && (count == 2'b11)) |=> (count == 2'b00)
    );

// EQ must match the 4-input equality function.
    check_eq_definition: assert property (
        @(posedge clk) EQ == ((A == B) && (B == C) && (C == D))
    );

// GT must match the implemented greater-or-equal function.
    check_gt_definition: assert property (
        @(posedge clk) GT == ((A > B) || ((A == B) && (C > D)))
    );

// If A is greater than B, GT must be high.
    check_gt_when_a_greater_b: assert property (
        @(posedge clk) (A > B) |-> GT
    );

// If A equals B and C is greater than D, GT must be high.
    check_gt_when_a_eq_b_and_c_greater_d: assert property (
        @(posedge clk) ((A == B) && (C > D)) |-> GT
    );

// If A is less than B, GT must be low.
    check_gt_low_when_a_less_b: assert property (
        @(posedge clk) (A < B) |-> !GT
    );

// If A is not equal to B, EQ must be low.
    check_eq_low_when_a_ne_b: assert property (
        @(posedge clk) (A != B) |-> !EQ
    );

// When enabled, S matches the 4-bit sum of A, B, and Cin.
    check_enabled_sum: assert property (
        @(posedge clk) En |-> (S == (A + B + Cin))
    );

// When disabled, S is zero.
    check_disabled_zero: assert property (
        @(posedge clk) !En |-> (S == 4'b0000)
    );

// When disabled, Cout is low.
    check_disabled_cout_low: assert property (
        @(posedge clk) !En |-> (Cout == 1'b0)
    );

// With B and Cin low, S passes A when enabled.
    check_a_passthrough_when_b0_cin0: assert property (
        @(posedge clk) (!En || (B == 4'b0000 && Cin == 1'b0)) |-> (S == (En ? A : 4'b0000))
    );

// With A and Cin low, S passes B when enabled.
    check_b_passthrough_when_a0_cin0: assert property (
        @(posedge clk) (!En || (A == 4'b0000 && Cin == 1'b0)) |-> (S == (En ? B : 4'b0000))
    );

// With A and B low, S equals Cin when enabled.
    check_cin_passthrough_when_a0_b0: assert property (
        @(posedge clk) (!En || (A == 4'b0000 && B == 4'b0000)) |-> (S == (En ? Cin : 4'b0000))
    );

// A sampled reset cycle leaves count at zero on the next clock.
    check_reset_clears_count: assert property (
        @(posedge clk) !rst |=> (count == 4'h0)
    );

// When not in reset, count increments by one on the next clock.
    check_count_increments: assert property (
        @(posedge clk) disable iff (!rst) 1'b1 |=> (count == ($past(count) + 4'd1))
    );

// The 4-bit counter wraps from 15 back to 0.
    check_count_wraps: assert property (
        @(posedge clk) disable iff (!rst) (count == 4'hF) |=> (count == 4'h0)
    );

// X must equal A ^ B.
    check_xor_function: assert property (
        @(posedge clk) X == (A ^ B)
    );

// When A and B are equal, X must be 0.
    check_equal_inputs_zero: assert property (
        @(posedge clk) (A == B) |-> (X == 1'b0)
    );

// When A and B differ, X must be 1.
    check_different_inputs_one: assert property (
        @(posedge clk) (A != B) |-> (X == 1'b1)
    );

// X must equal ~(A & B & C & D).
    check_function_equivalence: assert property (
        @(posedge clk) X == ~(A & B & C & D)
    );

// When all inputs are HIGH, X must be LOW.
    check_all_high_implies_x_low: assert property (
        @(posedge clk) (A && B && C && D) |-> (X == 1'b0)
    );

// If X is HIGH, then not all inputs are HIGH.
    check_x_high_implies_not_all_high: assert property (
        @(posedge clk) (X == 1'b1) |-> !(A && B && C && D)
    );

// If X is LOW, then all inputs are HIGH.
    check_x_low_implies_all_high: assert property (
        @(posedge clk) (X == 1'b0) |-> (A && B && C && D)
    );

// A falling edge on X implies all inputs are HIGH now.
    check_x_fall_implies_all_high_now: assert property (
        @(posedge clk) $fell(X) |-> (A && B && C && D)
    );

// A rising edge on X implies not all inputs are HIGH now.
    check_x_rise_implies_not_all_high_now: assert property (
        @(posedge clk) $rose(X) |-> !(A && B && C && D)
    );

// X matches the RTL expression C ? ~or(A,B) : or(A,B).
    check_function_equivalence: assert property (
        @(posedge clk) X == (C ? ~((A | B)) : (A | B))
    );

// When C is 0, X equals A | B.
    check_c0_pass_through: assert property (
        @(posedge clk) (C == 1'b0) |-> (X == (A | B))
    );

// When C is 1, X equals ~(A | B).
    check_c1_invert: assert property (
        @(posedge clk) (C == 1'b1) |-> (X == ~(A | B))
    );

// If C is 1 and A and B are 0, X must be 1.
    check_c1_both_zero: assert property (
        @(posedge clk) ((C == 1'b1) && (A == 1'b0) && (B == 1'b0)) |-> (X == 1'b1)
    );

// and_out must equal bitwise_and of a and b.
    check_and_function: assert property (
        @(posedge clk) and_out == (a & b)
    );

// or_out must equal bitwise_or of a and b.
    check_or_function: assert property (
        @(posedge clk) or_out == (a | b)
    );

// xor_out must equal bitwise_xor of a and b.
    check_xor_function: assert property (
        @(posedge clk) xor_out == (a ^ b)
    );

// not_out must equal bitwise_not of a.
    check_not_function: assert property (
        @(posedge clk) not_out == (~a)
    );

// and_out must be a subset of a.
    check_and_subset_a: assert property (
        @(posedge clk) (and_out & ~a) == 8'h00
    );

// and_out must be a subset of b.
    check_and_subset_b: assert property (
        @(posedge clk) (and_out & ~b) == 8'h00
    );

// not_out must be the bitwise complement of a.
    check_not_complement: assert property (
        @(posedge clk) (not_out & a) == 8'h00 && (not_out | a) == 8'hFF
    );

// sel=00 routes x_axis to data.
    check_sel_x_axis: assert property (
        @(posedge clk) (sel == 2'b00) |-> (data == x_axis)
    );

// sel=01 routes y_axis to data.
    check_sel_y_axis: assert property (
        @(posedge clk) (sel == 2'b01) |-> (data == y_axis)
    );

// sel=10 routes z_axis to data.
    check_sel_z_axis: assert property (
        @(posedge clk) (sel == 2'b10) |-> (data == z_axis)
    );

// sel=11 routes temp_data into the upper byte of data.
    check_sel_temp_data: assert property (
        @(posedge clk) (sel == 2'b11) |-> (data == {8'h00, temp_data})
    );

// data always matches the selected input or zero-extended temp_data.
    check_output_matches_select: assert property (
        @(posedge clk)
            (data == (sel == 2'b00 ? x_axis :
                      sel == 2'b01 ? y_axis :
                      sel == 2'b10 ? z_axis :
                                     {8'h00, temp_data}))
    );

// Reset clears result on the next clock.
    check_reset_clears_result: assert property (
        @(posedge clk) reset |=> (result == 32'd0)
    );

// Reset drives count to zero on the next clock.
    check_reset_clears_count: assert property (
        @(posedge clk) rst |=> (count == 4'd0)
    );

// Load captures data into count on the next clock.
    check_load_captures_data: assert property (
        @(posedge clk) disable iff (rst)
        load |=> (count == $past(data))
    );

// Without load, count increments by one on the next clock.
    check_increment_when_not_loading: assert property (
        @(posedge clk) disable iff (rst)
        !load |=> (count == ($past(count) + 4'd1))
    );

// Increment wraps from 15 back to 0.
    check_increment_wraps_from_max: assert property (
        @(posedge clk) disable iff (rst)
        (!load && (count == 4'hF)) |=> (count == 4'h0)
    );

// out must equal the 4-bit sum of in1 and in2.
    check_out_sum: assert property (
        @(posedge clk) out == (in1 + in2)
    );

// max_out must equal the 4-bit maximum of out and the sum of in1 and in2.
    check_max_out_function: assert property (
        @(posedge clk) max_out == ((out > (in1 + in2)) ? out : (in1 + in2))
    );

// When out is greater than the sum, max_out must equal out.
    check_max_out_selects_out_when_greater: assert property (
        @(posedge clk) (out > (in1 + in2)) |-> (max_out == out)
    );

// When out is less than or equal to the sum, max_out must equal the sum.
    check_max_out_selects_sum_when_not_greater: assert property (
        @(posedge clk) (out <= (in1 + in2)) |-> (max_out == (in1 + in2))
    );

// Equal inputs must drive out and max_out to the same value.
    check_equal_inputs_same_output: assert property (
        @(posedge clk) (in1 == in2) |-> (out == max_out)
    );

// If the sum is zero, max_out must equal out.
    check_zero_sum_out_equals_max_out: assert property (
        @(posedge clk) ((in1 + in2) == 4'h0) |-> (max_out == out)
    );

// If out is zero, max_out must equal the sum.
    check_zero_out_sum_equals_max_out: assert property (
        @(posedge clk) (out == 4'h0) |-> (max_out == (in1 + in2))
    );

// The maximum 4-bit value must drive max_out to itself.
    check_max_value_pass_through: assert property (
        @(posedge clk) (in1 + in2 == 4'hF) |-> (max_out == 4'hF)
    );

// out[99] captures the previous cycle's LSB of in.
    check_out99_captures_prev_lsb: assert property (
        @(posedge clk) 1'b1 |=> (out[99] == $past(in[0]))
    );

// Reset drives count to zero on the next clock.
    check_reset_clears_count: assert property (
        @(posedge clk) reset |=> (count == 4'b0000)
    );

// Load captures data_in when reset is low.
    check_load_captures_data: assert property (
        @(posedge clk) disable iff (reset) load |=> (count == $past(data_in))
    );

// Without load, count increments by one when reset is low.
    check_increment_when_not_load: assert property (
        @(posedge clk) disable iff (reset) !load |=> (count == ($past(count) + 4'd1))
    );

// Increment wraps from 15 back to 0 when reset is low.
    check_increment_wraps_from_max: assert property (
        @(posedge clk) disable iff (reset) (!load && (count == 4'hF)) |=> (count == 4'h0)
    );

// Addition mode returns the 8-bit sum of A and B.
    check_add_result: assert property (
        @(posedge clk) (op == 2'b00) |-> (result == (A + B))
    );

// Subtraction mode returns the 8-bit difference of A and B.
    check_sub_result: assert property (
        @(posedge clk) (op == 2'b01) |-> (result == (A - B))
    );

// Division by zero forces the result to zero.
    check_div_zero_result: assert property (
        @(posedge clk) (op == 2'b11 && B == 8'h00) |-> (result == 8'h00)
    );

// Reset clears all four stages on the next clock.
    check_reset_clears_all: assert property (
        @(posedge shift_clk) reset |=> (q0 == 4'b0000) && (q1 == 4'b0000) && (q2 == 4'b0000) && (q3 == 4'b0000)
    );

// q0 captures data_in on the next clock when reset is low.
    check_q0_captures_data_in: assert property (
        @(posedge shift_clk) disable iff (reset) 1'b1 |=> (q0 == $past(data_in))
    );

// q1 captures the previous q0 value on the next clock when reset is low.
    check_q1_captures_prev_q0: assert property (
        @(posedge shift_clk) disable iff (reset) 1'b1 |=> (q1 == $past(q0))
    );

// q2 captures the previous q1 value on the next clock when reset is low.
    check_q2_captures_prev_q1: assert property (
        @(posedge shift_clk) disable iff (reset) 1'b1 |=> (q2 == $past(q1))
    );

// q3 captures the previous q2 value on the next clock when reset is low.
    check_q3_captures_prev_q2: assert property (
        @(posedge shift_clk) disable iff (reset) 1'b1 |=> (q3 == $past(q2))
    );

// No RTL clock or reset; sample this combinational logic on clk.

    // shift_amt 00 passes the input through unchanged.
    check_shift_amt_00_passthrough: assert property (
        @(posedge clk) (shift_amt == 2'b00) |-> (out == in)
    );

// shift_amt 01 shifts left when dir==1.
    check_shift_amt_01_left: assert property (
        @(posedge clk) (shift_amt == 2'b01 && dir == 1'b1) |-> (out == {in[2:0], in[3]})
    );

// shift_amt 01 shifts right when dir==0.
    check_shift_amt_01_right: assert property (
        @(posedge clk) (shift_amt == 2'b01 && dir == 1'b0) |-> (out == {in[1:0], in[3:2]})
    );

// shift_amt 10 shifts left when dir==1.
    check_shift_amt_10_left: assert property (
        @(posedge clk) (shift_amt == 2'b10 && dir == 1'b1) |-> (out == {in[1:0], in[3:2]})
    );

// shift_amt 10 shifts right when dir==0.
    check_shift_amt_10_right: assert property (
        @(posedge clk) (shift_amt == 2'b10 && dir == 1'b0) |-> (out == {in[2:0], in[3]})
    );

// shift_amt 11 rotates left by one bit.
    check_shift_amt_11_rotate_left: assert property (
        @(posedge clk) (shift_amt == 2'b11) |-> (out == {in[0], in[3:1]})
    );

// Sum must equal A + B.
    check_total_sum: assert property (
        @(posedge clk) disable iff (1'b0) {CO, C} == ({1'b0, A} + {1'b0, B})
    );

// LSB of C must equal A[0] ^ B[0].
    check_lsb_xor: assert property (
        @(posedge clk) disable iff (1'b0) C[0] == (A[0] ^ B[0])
    );

// Carry-out must equal the carry generated by the 4-bit addition.
    check_carry_out: assert property (
        @(posedge clk) disable iff (1'b0) CO == (({1'b0, A} + {1'b0, B}) > 5'd15)
    );

// 0 + 0 must produce 0 with no carry.
    check_zero_plus_zero: assert property (
        @(posedge clk) disable iff (1'b0) (A == 4'h0 && B == 4'h0) |-> ({CO, C} == 5'h00)
    );

// 15 + 15 must produce 30 with carry-out.
    check_max_plus_max: assert property (
        @(posedge clk) disable iff (1'b0) (A == 4'hF && B == 4'hF) |-> ({CO, C} == 5'h1E)
    );

// Y must match the RTL mux equation.
    check_mux_equation: assert property (
        @(posedge clk) Y == (SEL ? B : A)
    );

// When SEL is 0, Y must equal A.
    check_select_a: assert property (
        @(posedge clk) (SEL == 1'b0) |-> (Y == A)
    );

// When SEL is 1, Y must equal B.
    check_select_b: assert property (
        @(posedge clk) (SEL == 1'b1) |-> (Y == B)
    );

// If A and B are equal, Y must equal that value regardless of SEL.
    check_equal_inputs_passthrough: assert property (
        @(posedge clk) (A == B) |-> (Y == A)
    );

// Bit 2 sum uses the carry generated from bit 1.
    check_sum_bit2: assert property (
        @(posedge clk) S[2] == (A[2] ^ B[2] ^ (
            (A[1] & B[1]) |
            (A[1] & ((A[0] & B[0]) | (A[0] & Cin) | (B[0] & Cin))) |
            (B[1] & ((A[0] & B[0]) | (A[0] & Cin) | (B[0] & Cin)))
        ))
    );

// All three A inputs high must drive X high.
    check_all_a_high_sets_x: assert property (
        @(posedge clk)
        (A1 & A2 & A3) |-> X
    );

// A1, A2, and C1 high must drive X high.
    check_a1_a2_c1_sets_x: assert property (
        @(posedge clk)
        (A1 & A2 & C1) |-> X
    );

// A1, A3, and C1 high must drive X high.
    check_a1_a3_c1_sets_x: assert property (
        @(posedge clk)
        (A1 & A3 & C1) |-> X
    );

// A2, A3, and C1 high must drive X high.
    check_a2_a3_c1_sets_x: assert property (
        @(posedge clk)
        (A2 & A3 & C1) |-> X
    );

// Reset drives count to zero on the next clock.
    check_reset_clears_count: assert property (
        @(posedge clk) reset |=> (count == 4'b0000)
    );

// Load captures data_in into count when not in reset.
    check_load_captures_data: assert property (
        @(posedge clk) disable iff (reset)
        load |=> (count == $past(data_in))
    );

// Up-count increments count by one when load is low.
    check_up_count_increments: assert property (
        @(posedge clk) disable iff (reset)
        (!load && up_down) |=> (count == ($past(count) + 4'd1))
    );

// Down-count decrements count by one when load is low.
    check_down_count_decrements: assert property (
        @(posedge clk) disable iff (reset)
        (!load && !up_down) |=> (count == ($past(count) - 4'd1))
    );

// Y is always the logical inversion of A.
    check_inversion_function: assert property (
        @(posedge CLK) disable iff (1'b0) (Y == ~A)
    );

// A low input drives Y high.
    check_low_input_drives_high_output: assert property (
        @(posedge CLK) disable iff (1'b0) (A == 1'b0) |-> (Y == 1'b1)
    );

// A high input drives Y low.
    check_high_input_drives_low_output: assert property (
        @(posedge CLK) disable iff (1'b0) (A == 1'b1) |-> (Y == 1'b0)
    );

// Y can only be high when A is low.
    check_output_high_implies_input_low: assert property (
        @(posedge CLK) disable iff (1'b0) (Y == 1'b1) |-> (A == 1'b0)
    );

// Y can only be low when A is high.
    check_output_low_implies_input_high: assert property (
        @(posedge CLK) disable iff (1'b0) (Y == 1'b0) |-> (A == 1'b1)
    );

// Addition mode returns the 8-bit sum.
    check_addition_result: assert property (
        @(posedge clk) (op == 2'b00) |-> (result == (num1 + num2))
    );

// Subtraction mode returns the 8-bit difference.
    check_subtraction_result: assert property (
        @(posedge clk) (op == 2'b01) |-> (result == (num1 - num2))
    );

// Division by zero forces the result to zero.
    check_division_by_zero_result: assert property (
        @(posedge clk) (op == 2'b11 && num2 == 8'h00) |-> (result == 8'h00)
    );

// blank forces the output high.
    check_blank_forces_high: assert property (
        @(posedge clk) blank |-> (s7 == 7'b1111111)
    );

// With all B inputs low and both A inputs high, Y is high.
    check_all_enable_high_drives_high: assert property (
        @(posedge clk) (!B1 && !B2 && A1_N && A2_N) |-> Y
    );

// Clock: s_aclk (posedge). Reset: AR (active-high synchronous). Logic: sequential counter.

    // When AR is high, Q is cleared to 0 on the next cycle.
    check_async_reset_clears_q: assert property (
        @(posedge s_aclk) AR |=> (Q == 4'b0000)
    );

// When E is high and Q is not at max, Q increments by 1 on the next cycle.
    check_increment_when_enabled_not_max: assert property (
        @(posedge s_aclk) disable iff (AR) E && (Q != 4'b1111) |=> (Q == ($past(Q) + 4'd1))
    );

// When E is high and Q is at max, Q wraps to 0 on the next cycle.
    check_wrap_when_enabled_at_max: assert property (
        @(posedge s_aclk) disable iff (AR) E && (Q == 4'b1111) |=> (Q == 4'b0000)
    );

// When E is low, Q holds its value on the next cycle.
    check_hold_when_disabled: assert property (
        @(posedge s_aclk) disable iff (AR) !E |=> (Q == $past(Q))
    );

// If E is high and Q is 0, the next value must be 1 (no wrap).
    check_increment_from_zero: assert property (
        @(posedge s_aclk) disable iff (AR) E && (Q == 4'b0000) |=> (Q == 4'b0001)
    );

// Reset clears the output on the next clock.
    check_reset_clears_out: assert property (
        @(posedge clk) reset |=> (out == 4'b0000)
    );

// 0 maps to 0000.
    check_map_0: assert property (
        @(posedge clk) (input_val == 10'b0000000000) |-> (binary_val == 4'b0000)
    );

// 1 maps to 0001.
    check_map_1: assert property (
        @(posedge clk) (input_val == 10'b0000000001) |-> (binary_val == 4'b0001)
    );

// 2 maps to 0010.
    check_map_2: assert property (
        @(posedge clk) (input_val == 10'b0000000010) |-> (binary_val == 4'b0010)
    );

// 3 maps to 0011.
    check_map_3: assert property (
        @(posedge clk) (input_val == 10'b0000000011) |-> (binary_val == 4'b0011)
    );

// 4 maps to 0100.
    check_map_4: assert property (
        @(posedge clk) (input_val == 10'b0000000100) |-> (binary_val == 4'b0100)
    );

// 5 maps to 0101.
    check_map_5: assert property (
        @(posedge clk) (input_val == 10'b0000000101) |-> (binary_val == 4'b0101)
    );

// 6 maps to 0110.
    check_map_6: assert property (
        @(posedge clk) (input_val == 10'b0000000110) |-> (binary_val == 4'b0110)
    );

// 7 maps to 0111.
    check_map_7: assert property (
        @(posedge clk) (input_val == 10'b0000000111) |-> (binary_val == 4'b0111)
    );

// 8 maps to 1000.
    check_map_8: assert property (
        @(posedge clk) (input_val == 10'b0000001000) |-> (binary_val == 4'b1000)
    );

// 9 maps to 1001.
    check_map_9: assert property (
        @(posedge clk) (input_val == 10'b0000001001) |-> (binary_val == 4'b1001)
    );

// Values 10 through 1023 map to 0000 (default).
    check_default_range: assert property (
        @(posedge clk) (input_val >= 10'b0000001010) |-> (binary_val == 4'b0000)
    );

// When A1 is 0, X must be 0.
    check_a1_zero_forces_x_zero: assert property (
        @(posedge clk) (A1 == 1'b0) |-> (X == 1'b0)
    );

// When A2 is 0, X must be 0.
    check_a2_zero_forces_x_zero: assert property (
        @(posedge clk) (A2 == 1'b0) |-> (X == 1'b0)
    );

// When B1_N is 1, X must be 0.
    check_b1n_one_forces_x_zero: assert property (
        @(posedge clk) (B1_N == 1'b1) |-> (X == 1'b0)
    );

// X can only be 1 when A1=1, A2=1, and B1_N=0.
    check_x_one_implies_inputs: assert property (
        @(posedge clk) (X == 1'b1) |-> (A1 && A2 && !B1_N)
    );

// Reset drives count to zero on the next clock.
    check_reset_clears_count: assert property (
        @(posedge clk) rst |=> (count == 4'b0000)
    );

// Count increments from 0 to 1 when reset is low.
    check_count_0_to_1: assert property (
        @(posedge clk) disable iff (rst) (count == 4'b0000) |=> (count == 4'b0001)
    );

// Count increments from 1 to 2 when reset is low.
    check_count_1_to_2: assert property (
        @(posedge clk) disable iff (rst) (count == 4'b0001) |=> (count == 4'b0010)
    );

// Count increments from 2 to 3 when reset is low.
    check_count_2_to_3: assert property (
        @(posedge clk) disable iff (rst) (count == 4'b0010) |=> (count == 4'b0011)
    );

// Count increments from 3 to 4 when reset is low.
    check_count_3_to_4: assert property (
        @(posedge clk) disable iff (rst) (count == 4'b0011) |=> (count == 4'b0100)
    );

// Count increments from 4 to 5 when reset is low.
    check_count_4_to_5: assert property (
        @(posedge clk) disable iff (rst) (count == 4'b0100) |=> (count == 4'b0101)
    );

// Count increments from 5 to 6 when reset is low.
    check_count_5_to_6: assert property (
        @(posedge clk) disable iff (rst) (count == 4'b0101) |=> (count == 4'b0110)
    );

// Count increments from 6 to 7 when reset is low.
    check_count_6_to_7: assert property (
        @(posedge clk) disable iff (rst) (count == 4'b0110) |=> (count == 4'b0111)
    );

// Count increments from 7 to 8 when reset is low.
    check_count_7_to_8: assert property (
        @(posedge clk) disable iff (rst) (count == 4'b0111) |=> (count == 4'b1000)
    );

// Count increments from 8 to 9 when reset is low.
    check_count_8_to_9: assert property (
        @(posedge clk) disable iff (rst) (count == 4'b1000) |=> (count == 4'b1001)
    );

// Count wraps from 9 back to 0 when reset is low.
    check_count_9_to_0: assert property (
        @(posedge clk) disable iff (rst) (count == 4'b1001) |=> (count == 4'b0000)
    );

// X must equal the RTL expression.
    check_function_equivalence: assert property (
        @(posedge clk) X == ~(A_N | B | C | D)
    );

// B high forces X low.
    check_b_high_forces_x_low: assert property (
        @(posedge clk) B |-> !X
    );

// C high forces X low.
    check_c_high_forces_x_low: assert property (
        @(posedge clk) C |-> !X
    );

// D high forces X low.
    check_d_high_forces_x_low: assert property (
        @(posedge clk) D |-> !X
    );

// All inputs in their low-state condition force X high.
    check_all_low_forces_x_high: assert property (
        @(posedge clk) (!A_N && !B && !C && !D) |-> X
    );

// A high X requires all inputs to be in their low-state condition.
    check_x_high_requires_all_low: assert property (
        @(posedge clk) X |-> (!A_N && !B && !C && !D)
    );

// A low X requires at least one input to be high.
    check_x_low_requires_some_high: assert property (
        @(posedge clk) !X |-> (A_N || B || C || D)
    );

// Load captures data_in on the next cycle.
    check_load_captures_data: assert property (
        @(posedge clk) load |=> (data_out == $past(data_in))
    );

// When not loading, data_out rotates left by one bit.
    check_shift_left_when_not_loading: assert property (
        @(posedge clk) !load |=> (data_out == {$past(data_out[2:0]), $past(data_out[3])})
    );

// The least-significant bit takes the previous MSB value.
    check_lsb_captures_msb: assert property (
        @(posedge clk) !load |=> (data_out[0] == $past(data_out[3]))
    );

// The upper three bits shift left by one.
    check_upper_bits_shift_left: assert property (
        @(posedge clk) !load |=> (data_out[3:1] == $past(data_out[2:0]))
    );

// Y must equal A & B & ~C.
    check_function_equivalence: assert property (
        @(posedge clk) Y == (A & B & ~C)
    );

// When C is HIGH, Y must be LOW.
    check_c_high_forces_y_low: assert property (
        @(posedge clk) C |-> !Y
    );

// When C is LOW, Y must equal A & B.
    check_c_low_reduces_to_and: assert property (
        @(posedge clk) !C |-> (Y == (A & B))
    );

// A and B HIGH with C LOW must drive Y HIGH.
    check_all_inputs_true_drive_y_high: assert property (
        @(posedge clk) (!C && A && B) |-> Y
    );

// A LOW with C LOW must drive Y LOW.
    check_a_low_forces_y_low: assert property (
        @(posedge clk) (!C && !A) |-> !Y
    );

// B LOW with C LOW must drive Y LOW.
    check_b_low_forces_y_low: assert property (
        @(posedge clk) (!C && !B) |-> !Y
    );

// X equals (A1 & A2) | B1 | C1.
    check_function_equivalence: assert property (
        @(posedge clk) X == ((A1 & A2) | B1 | C1)
    );

// If B1 is HIGH, X must be HIGH.
    check_b1_forces_x_high: assert property (
        @(posedge clk) B1 |-> X
    );

// If C1 is HIGH, X must be HIGH.
    check_c1_forces_x_high: assert property (
        @(posedge clk) C1 |-> X
    );

// If A1 and A2 are both HIGH, X must be HIGH.
    check_a1_a2_force_x_high: assert property (
        @(posedge clk) (A1 & A2) |-> X
    );

// If B1 and C1 are LOW and A1/A2 are not both HIGH, X must be LOW.
    check_no_active_input_means_x_low: assert property (
        @(posedge clk) (!B1 && !C1 && !(A1 && A2)) |-> !X
    );

// If X is LOW, then B1, C1, and (A1 & A2) must all be LOW.
    check_x_low_implies_inputs_low: assert property (
        @(posedge clk) !X |-> (!B1 && !C1 && !(A1 && A2))
    );

// Y must equal the XNOR of A and B.
    check_xnor_function: assert property (
        @(posedge clk) Y == ~(A ^ B)
    );

// When A and B are equal, Y must be HIGH.
    check_equal_inputs_drive_high: assert property (
        @(posedge clk) (A == B) |-> (Y == 1'b1)
    );

// When A and B differ, Y must be LOW.
    check_different_inputs_drive_low: assert property (
        @(posedge clk) (A != B) |-> (Y == 1'b0)
    );

// Gated clock is low when the prior-cycle enable was low.
    check_gated_low_when_prev_en_low: assert property (
        @(posedge src_clk) !clk_en |-> !gated_clk
    );

// A high gated clock implies the prior-cycle enable was high.
    check_prev_en_high_when_gated_high: assert property (
        @(posedge src_clk) gated_clk |-> clk_en
    );

// Y must match the RTL mux equation.
    check_mux_equation: assert property (
        @(posedge clk) Y == (SEL ? B : A)
    );

// When SEL is low, Y must follow A.
    check_select_a: assert property (
        @(posedge clk) !SEL |-> (Y == A)
    );

// When SEL is high, Y must follow B.
    check_select_b: assert property (
        @(posedge clk) SEL |-> (Y == B)
    );

// MO equals B when S==1.
    check_select_b_when_s1: assert property (
        @(posedge CLK) (S == 1'b1) |-> (MO == B)
    );

// MO equals A when S==0.
    check_select_a_when_s0: assert property (
        @(posedge CLK) (S == 1'b0) |-> (MO == A)
    );

// MO equals A when S is unknown (X/Z).
    check_select_a_when_s_unknown: assert property (
        @(posedge CLK) (S != 1'b1) |-> (MO == A)
    );

// MO equals B when S is unknown (X/Z).
    check_select_b_when_s_unknown: assert property (
        @(posedge CLK) (S != 1'b0) |-> (MO == B)
    );

// MO equals A when both inputs are equal.
    check_equal_inputs_select_a: assert property (
        @(posedge CLK) (A == B) |-> (MO == A)
    );
